        'Slack'    = @{ P = @('slack'); Dirs = @("$env:LOCALAPPDATA\slack\") }
        'Signal'   = @{ P = @('Signal'); Dirs = @("$env:LOCALAPPDATA\Programs\signal-desktop\") }
        'LINE'     = @{ P = @('LINE','LineLauncher','LineUpdater','LineMediaPlayer'); Dirs = @("$env:LOCALAPPDATA\LINE\bin\") }
