# 换成英文的帮助页（整页替换中文的那一页）
function Use-EnglishHelp([xml]$doc, [string]$enXaml) {
    try {
        $ns = New-Object System.Xml.XmlNamespaceManager $doc.NameTable
        $ns.AddNamespace('w', 'http://schemas.microsoft.com/winfx/2006/xaml/presentation'); $ns.AddNamespace('x', 'http://schemas.microsoft.com/winfx/2006/xaml')
        $old = $doc.SelectSingleNode("//w:Grid[@x:Name='PageHelp']", $ns)
        $frag = [xml]("<R xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml'>" + $enXaml + '</R>')
        $new = $frag.DocumentElement.SelectSingleNode("w:Grid[@x:Name='PageHelp']", $ns)
        if ($old -and $new) { [void]$old.ParentNode.ReplaceChild($doc.ImportNode($new, $true), $old) }
    } catch {}
}
# 界面上的文字逐个查表换成英文
function Set-XamlLang([xml]$doc) {
    $attrs = @('Text', 'Content', 'ToolTip', 'Header', 'Title')
    foreach ($el in $doc.SelectNodes('//*')) {
        foreach ($a in @($el.Attributes)) {
            # 触发器里和数据比较的值（比如行的操作「删除」）也要换成同样的英文，否则颜色等样式对不上
            $use = ($attrs -contains $a.LocalName) -or ($a.LocalName -eq 'Value' -and (($el.LocalName -eq 'Setter' -and ($attrs -contains [string]$el.GetAttribute('Property'))) -or $el.LocalName -in @('Condition', 'DataTrigger', 'Trigger')))
            if ($use -and $a.Value -and -not $a.Value.StartsWith('{')) { $a.Value = T $a.Value }
            elseif ($use -and $a.Value -like "*StringFormat='{}{0} 项'*") { $a.Value = $a.Value.Replace("{}{0} 项", '{}' + (T '{0} 项')) }
        }
        foreach ($c in @($el.ChildNodes)) { if ($c.NodeType -eq 'Text' -and $c.Value) { $c.Value = T $c.Value } }
    }
}
# ---------- 帮助页用到时才加载 ----------
# 帮助页的内容占主界面 XAML 的四分之一。打开窗口时只留一个空的 PageHelp，内容拿出来存成字符串，第一次打开帮助时
# 再解析（Initialize-HelpPage）。单独解析时找不到主窗口里的样式，所以 StaticResource 换成 DynamicResource：挂进窗口以后再取
function Split-HelpPage([xml]$doc) {
    $ns = New-Object System.Xml.XmlNamespaceManager $doc.NameTable
    $ns.AddNamespace('w', 'http://schemas.microsoft.com/winfx/2006/xaml/presentation'); $ns.AddNamespace('x', 'http://schemas.microsoft.com/winfx/2006/xaml')
    $hp = $doc.SelectSingleNode("//w:Grid[@x:Name='PageHelp']", $ns)
    if (-not $hp) { return '' }
    # 整个 PageHelp 复制成一份单独的文档，根上去掉名字、位置、隐藏和边距（这些留在窗口里那个空的 PageHelp 上）。
    # 不能把每个子元素的 OuterXml 拼起来：那样 <Grid.RowDefinitions> 这类属性元素会带上 xmlns，XAML 不认
    $frag = New-Object System.Xml.XmlDocument
    $frag.LoadXml($hp.OuterXml)
    $r = $frag.DocumentElement
    foreach ($a in @($r.Attributes)) { if ($a.Name -ne 'xmlns' -and -not $a.Name.StartsWith('xmlns:')) { [void]$r.Attributes.Remove($a) } }
    $r.SetAttribute('xmlns:x', 'http://schemas.microsoft.com/winfx/2006/xaml')
    foreach ($c in @($hp.ChildNodes)) { [void]$hp.RemoveChild($c) }
    return ($frag.OuterXml -replace '\{StaticResource ', '{DynamicResource ')
}
if ($script:Lang -eq 'en') { Use-EnglishHelp $xaml $script:helpEnXaml }
$script:helpXml = Split-HelpPage $xaml
if ($script:Lang -eq 'en') {
    # 英文词更长：重复文件页左边那一列标签放宽一点
    foreach ($cd in $xaml.SelectNodes("//*[local-name()='ColumnDefinition' and @Width='92']")) { $cd.SetAttribute('Width', '108') }
    Set-XamlLang $xaml
}
$win = $null; $script:themeFail = ''
if ([Theme]::Dark) {
    # 深色版本万一打不开，就用浅色打开（不然连换回浅色的按钮都看不到）
    try { $win = [Windows.Markup.XamlReader]::Parse([Theme]::Xaml($xaml.OuterXml)) } catch { $script:themeFail = $_.Exception.Message; [Theme]::Dark = $false; $win = $null }
}
if (-not $win) { $win = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml)) }
# 深色的窗口标题栏
$win.Add_SourceInitialized({ try { [Theme]::DarkTitle((New-Object System.Windows.Interop.WindowInteropHelper $win).Handle) } catch {} })
# 字距：Display 模式把每个字的宽度取整到整像素，96 DPI 的小字最清楚，但在缩放 125% 以上的屏幕上，字和字之间会忽宽忽窄。
# 这种屏幕改用 Ideal，字距照字体本来的设计；像素够多，也不会发虚。对话框跟着主窗口
$script:textIdeal = $false
function Set-TextMode($w) {
    try {
        $ps = [System.Windows.PresentationSource]::FromVisual($w)
        $scale = if ($ps -and $ps.CompositionTarget) { [double]$ps.CompositionTarget.TransformToDevice.M11 } else { 1.0 }
        if ($scale -ge 1.2 -or $script:textIdeal) {
            $script:textIdeal = $true
            [System.Windows.Media.TextOptions]::SetTextFormattingMode($w, [System.Windows.Media.TextFormattingMode]::Ideal)
        }
    } catch {}
}
$win.Add_SourceInitialized({ Set-TextMode $win })
$script:tUi = $script:startClock.Elapsed.TotalSeconds
$ctl = @{}
foreach ($n in 'NavSave','NavMap','NavApps','NavMoves','NavAuto','NavLog','PageMap','PageSave','PageApps','PageMoves','PageAuto','PageLog','BtnDupMerge',
