foreach ($c in @($ctl.SizeMinUnit, $ctl.SizeMaxUnit)) { $c.Add_SelectionChanged({ On-SizeEdited }) }

# ---------- 条件摘要：收起面板后也能看到当前条件 ----------
function Update-FilterSummary {
    if ($null -eq $script:typeAll -or $null -eq $script:sizeCustom) { return }
    if ($ctl.ModeSimilar.IsChecked) { $types = (T '相似照片') }
    elseif ($script:typeAll.IsChecked) { $types = (T '全部类型') }
    else {
        $names = @($script:chips | Where-Object { $_.Btn.IsChecked } | ForEach-Object { $_.Label })
        $extra = Parse-ExtraExt
        if ($extra.Count -gt 0) { $names += ($extra -join ' ') }
        $types = if ($names.Count -gt 3) { ($names[0..2] -join (T '、')) + ((T " 等 {0} 类") -f $($names.Count)) } else { $names -join (T '、') }
    }
    $r = Get-SizeRange
    if (-not $r.Ok) { $size = (T '大小填写有误') }
    elseif ($r.Min -le 1 -and $r.Max -le 0) { $size = (T '不限大小') }
    elseif ($r.Max -le 0) { $size = (Size-Text $r.Min) + (T ' 以上') }
    elseif ($r.Min -le 1) { $size = (Size-Text $r.Max) + (T ' 以下') }
    else { $size = (T "{0} 到 {1}") -f (Size-Text $r.Min), (Size-Text $r.Max) }
    $ctl.SizeHint.Text = if ($r.Ok) { (T '留空表示不限') } else { $r.Err }
    $ctl.SizeHint.Foreground = if ($r.Ok) { Brush '#6E6E73' } else { Brush '#D70015' }
    $mode = if ($ctl.ModeName.IsChecked) { (T '文件名和内容都相同') } else { (T '只要内容相同') }
    $mode += if ($ctl.SpeedExact.IsChecked) { (T '，完整比对') } else { (T '，快速比对') }
    $n = @($script:roots | Where-Object { $_.Enabled }).Count
    $ctl.FilterSummary.Text = (T "{0}，{1}，{2}，{3} 个位置") -f $types, $size, $mode, $n
    # 选项卡上直接写着现在的条件：收起来也看得到
    $ctl.DTabRootsVal.Text = (T "{0} 个") -f $n
    $ctl.DTabTypeVal.Text = $types
    $ctl.DTabSizeVal.Text = $size
    $ctl.DTabModeVal.Text = $(if ($ctl.ModeSimilar.IsChecked) { (T '相似照片') } elseif ($ctl.ModeName.IsChecked) { (T '名字和内容') } else { (T '只看内容') }) + (T ' · ') + $(if ($ctl.ModeSimilar.IsChecked) { $(if ($ctl.SimStrict.IsChecked) { (T '几乎一样') } elseif ($ctl.SimLoose.IsChecked) { (T '大致相似') } else { (T '相似') }) } elseif ($ctl.SpeedExact.IsChecked) { (T '完整比对') } else { (T '快速') })
}
# ---------- 查找条件的选项卡：点一个打开那一类；再点一下（或点「收起」）收起来；开始查找时自动收起 ----------
$script:dupPanes = [ordered]@{ roots = @('DTabRoots', 'DPaneRoots'); type = @('DTabType', 'DPaneType'); size = @('DTabSize', 'DPaneSize'); mode = @('DTabMode', 'DPaneMode') }
$script:dupPane = 'roots'; $script:dupTabQuiet = $false; $script:dupTabWas = $false
function Set-DupFilterOpen([bool]$open, [string]$pane = '') {
    if ($pane -and $script:dupPanes.Contains($pane)) { $script:dupPane = $pane }
    $ctl.DupFilterBody.Visibility = $(if ($open) { 'Visible' } else { 'Collapsed' })
    $script:dupTabQuiet = $true
    try {
        foreach ($k in $script:dupPanes.Keys) {
            $ctl[$script:dupPanes[$k][1]].Visibility = $(if ($k -eq $script:dupPane) { 'Visible' } else { 'Collapsed' })
            $ctl[$script:dupPanes[$k][0]].IsChecked = ($open -and $k -eq $script:dupPane)   # 收起时一个都不选中，看得出是收着的
        }
    } finally { $script:dupTabQuiet = $false }
    $ctl.DupFilterToggle.Content = $(if ($open) { (T '收起') } else { (T '展开条件') })
}
foreach ($k in $script:dupPanes.Keys) {
    $rb = $ctl[$script:dupPanes[$k][0]]; $rb.Tag = $k
    $rb.Add_Checked({ if ($script:dupTabQuiet) { return }; Set-DupFilterOpen $true ([string]$this.Tag) })
    # 点已经打开的那个选项卡：收起来
    $rb.Add_PreviewMouseLeftButtonDown({ $script:dupTabWas = [bool]$this.IsChecked -and $ctl.DupFilterBody.Visibility -eq 'Visible' })
    $rb.Add_Click({ if ($script:dupTabWas) { Set-DupFilterOpen $false }; $script:dupTabWas = $false })
}
$ctl.DupFilterToggle.Add_Click({ Set-DupFilterOpen ($ctl.DupFilterBody.Visibility -ne 'Visible') })
foreach ($c in @($ctl.ModeName, $ctl.ModeContent, $ctl.SpeedFast, $ctl.SpeedExact, $ctl.SimStrict, $ctl.SimNormal, $ctl.SimLoose)) { $c.Add_Click({ Update-FilterSummary }) }
# 点胶囊 = 勾选/取消；点自己加的文件夹上的小叉 = 移除
$ctl.Roots.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $src = $e.OriginalSource
    if ($src -is [System.Windows.Controls.Button] -and $src.Tag -is [RootItem]) { [void]$script:roots.Remove($src.Tag) }
    Update-FilterSummary
})

# 默认：全部类型，1 MB 以上
$script:sizeRadios[1].Btn.IsChecked = $true
Apply-SizePreset $script:sizeRadios[1].Btn

$ctl.BtnAddRoot.Add_Click({
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = (T '选择要查找重复文件的文件夹')
    if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $sp = $dlg.SelectedPath; $nm = Split-Path $sp -Leaf; if (-not $nm) { $nm = $sp }
        Add-Root $sp $nm $true $sp $true; Update-FilterSummary
    }
})

function Build-DupRows($groups, [int]$totalGroups) {
    $protectOn = [bool]$ctl.DupProtect.IsChecked
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[DupRow]'
    $byGroup = @{}
    $kept = New-Object System.Collections.Generic.List[DupGroup]
    $gid = 0; $waste = [double]0
    foreach ($g in $groups) {
        if ($g.Files.Count -lt 2) { continue }
        $gid++
        if ($gid -gt 3000) { break }
        $kept.Add($g)
        $meta  = (T "{0} × {1} 份，可释放 {2}") -f (Fmt $g.Size), $g.Files.Count, (Fmt $g.Waste)
        if ($g.Verified) { $badge = (T '已完整比对'); $tip = (T '每个文件都读完了全部内容，内容完全相同。'); $bbg = '#E6F4EA'; $bfg = '#1E7B34' }
        else { $badge = (T '抽样判定'); $tip = (T '文件名、大小和 16 处抽样内容都相同。删除前会逐字节完整比对，有任何不同就不删。'); $bbg = '#EFEFF4'; $bfg = '#6E6E73' }
        $list = New-Object System.Collections.ArrayList
        foreach ($f in $g.Files) {
            $r = New-Object DupRow
            $r.GroupId = $gid; $r.GroupName = $g.Name; $r.GroupMeta = $meta; $r.Verified = $g.Verified
            $r.GroupBadge = $badge; $r.GroupBadgeTip = $tip; $r.GroupBadgeBg = $bbg; $r.GroupBadgeFg = $bfg
            $r.Path = $f.Path; $r.Size = $f.Size
            $r.Dir = [IO.Path]::GetDirectoryName($f.Path).TrimEnd('\') + '\'; $r.FileName = [IO.Path]::GetFileName($f.Path)
            $r.Modified = $f.Modified.ToString('yyyy-MM-dd HH:mm'); $r.ModifiedTicks = $f.Modified.Ticks
            $r.Risk = $f.Risk; $r.HasRisk = -not [string]::IsNullOrEmpty($f.Risk)
            $r.Protected = Test-Personal $f.Path
            $why = Get-DupBlock $f.Path $r.Protected
            if ($why) { $r.Blocked = $true; $r.Risk = $why; $r.HasRisk = $true }
            $r.CanDelete = -not $r.Blocked -and -not ($protectOn -and $r.Protected)
            $fx = [IO.Path]::GetExtension($f.Path).ToLowerInvariant()
            $r.TypeBrush = if ($script:extColor.ContainsKey($fx)) { $script:extColor[$fx] } else { '#C7C7CC' }
            $col.Add($r); [void]$list.Add($r)
        }
        $byGroup[$gid] = $list
        $waste += $g.Waste
    }
    $script:dupRows = $col; $script:dupByGroup = $byGroup; $script:dupGroups = $kept; $script:dupWaste = $waste
    $ctl.DupList.ItemsSource = $col
    $ctl.EmptyDup.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    $ctl.EmptyDupText.Text = (T '没有找到重复文件')
    $view = [System.Windows.Data.CollectionViewSource]::GetDefaultView($col)
    $view.GroupDescriptions.Clear()
    $view.GroupDescriptions.Add((New-Object System.Windows.Data.PropertyGroupDescription 'GroupId'))
    if ($totalGroups -gt 3000) { UI-Log ((T "一共找到 {0} 组，只显示可释放空间最大的前 3000 组。删完这些后再查一次即可看到剩下的。") -f $totalGroups) }
    [DupRow]::Dirty = $false
    Update-DupSummary
}

function Update-DupSummary {
    if (-not $script:dupRows) { $ctl.DupSummary.Text = ''; $ctl.BtnDupDelete.IsEnabled = $false; $ctl.BtnDupMove.IsEnabled = $false; return }
    $n = 0; $b = [double]0
    foreach ($r in $script:dupRows) { if ($r.ToDelete) { $n++; $b += $r.Size } }
    $locked = 0; foreach ($r in $script:dupRows) { if (-not $r.CanDelete) { $locked++ } }
    if ($script:dupRows.Count -eq 0) { $ctl.DupSummary.Text = (T '没有找到重复文件。') }
    else {
        $ctl.DupSummary.Text = ((T "找到 {0} 组重复文件。已勾选 {1} 个，删除后释放 {2}。") -f $script:dupByGroup.Count, $n, (Fmt $b))
        if ($locked -gt 0) { $ctl.DupSummary.Text += ((T " C 盘个人文件夹里的 {0} 个副本受保护，不会删。") -f $locked) }
    }
    $ctl.BtnDupDelete.IsEnabled = ($n -gt 0) -and (-not $script:worker); $ctl.BtnDupMove.IsEnabled = $ctl.BtnDupDelete.IsEnabled
    $ctl.BtnDupMerge.IsEnabled = ($n -gt 0) -and (-not $script:worker)
}

# 每组只留一份，其余全部勾选删除
#   new：留最新的   old：留最早的   c：优先留不在 C 盘上的那份（有多份时留其中最新的）   none：全部取消
function Pick-Dup([string]$mode) {
    foreach ($gid in @($script:dupByGroup.Keys)) {
        $rows = @($script:dupByGroup[$gid])
        if ($mode -eq 'none') { foreach ($r in $rows) { $r.ToDelete = $false }; continue }
        # 受保护的副本（C 盘个人文件夹里的）一律保留；有它在，这一组就已经留了一份
        $locked = @($rows | Where-Object { -not $_.CanDelete })
        if ($locked.Count -gt 0) {
            foreach ($r in $rows) {
                if (-not $r.CanDelete) { $r.ToDelete = $false; continue }
                # 「优先留 C 盘以外的」只删 C 盘上的；其他留法删掉所有能删的
                $onC = $r.Path.StartsWith("$env:SystemDrive\", [StringComparison]::OrdinalIgnoreCase)
                $r.ToDelete = if ($mode -eq 'c') { $onC } else { $true }
            }
            continue
        }
        $pool = $rows
        if ($mode -eq 'c') {
            $notC = @($rows | Where-Object { -not $_.Path.StartsWith("$env:SystemDrive\", [StringComparison]::OrdinalIgnoreCase) })
            if ($notC.Count -gt 0) { $pool = $notC }
        }
        elseif ($mode -eq 'in' -and $script:keepInDir) {
            $inside = @($rows | Where-Object { $_.Path.StartsWith($script:keepInDir, [StringComparison]::OrdinalIgnoreCase) })
            if ($inside.Count -gt 0) { $pool = $inside }
        }
        $keep = if ($mode -eq 'short') { @($pool | Sort-Object { $_.Path.Length }, { $_.Path })[0] } else { @($pool | Sort-Object ModifiedTicks -Descending:($mode -ne 'old'))[0] }
        foreach ($r in $rows) { $r.ToDelete = -not [object]::ReferenceEquals($r, $keep) }
    }
    [DupRow]::Dirty = $false
    Update-DupSummary
}
# 「不删 C 盘个人文件夹里的文件」：默认打开；关掉要先确认
$script:protSync = $false
function Apply-Protect {
    $on = [bool]$ctl.DupProtect.IsChecked
    if ($script:dupRows) {
        foreach ($r in $script:dupRows) {
            $r.CanDelete = -not $r.Blocked -and -not ($on -and $r.Protected)
            if (-not $r.CanDelete) { $r.ToDelete = $false }
        }
    }
    [DupRow]::Dirty = $false
    Update-DupSummary
}
$ctl.DupProtect.Add_Checked({ if (-not $script:protSync) { Apply-Protect; UI-Log (T '已打开保护：C 盘个人文件夹里的文件不会删除') } })
$ctl.DupProtect.Add_Unchecked({
    if ($script:protSync) { return }
    $ans = Show-Sheet -Kind danger -Title (T '允许删除 C 盘个人文件夹里的文件？') `
        -Text (T '桌面、文档、下载、图片、视频、音乐等文件夹里通常是你自己的资料。关掉保护后，这些位置的重复副本也可能被勾选删除。每组仍会至少保留一份。') `
        -Confirm (T '我已确认删除这些位置的副本不会给我带来损失；因删除造成的后果由我自己承担。') -Buttons @((T '保持保护'), (T '允许删除')) -Primary (T '允许删除') -Cancel (T '保持保护')
    if ($ans -ne (T '允许删除')) { $script:protSync = $true; $ctl.DupProtect.IsChecked = $true; $script:protSync = $false; return }
    Apply-Protect
    UI-Log (T '已关闭保护：C 盘个人文件夹里的重复副本也可以勾选删除（勾选不会自动改变，需要时点「留最新的」等重新勾选）')
})

$ctl.BtnKeepNew.Add_Click({ Pick-Dup 'new' })
$ctl.BtnKeepOld.Add_Click({ Pick-Dup 'old' })
$ctl.BtnPickC.Add_Click({ Pick-Dup 'c' })
$ctl.BtnKeepShort.Add_Click({ Pick-Dup 'short' })
$script:keepInDir = ''
$ctl.BtnKeepIn.Add_Click({
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = (T '每组优先保留这个文件夹（含子文件夹）里的那份')
    if ($script:keepInDir) { $dlg.SelectedPath = $script:keepInDir }
    if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $script:keepInDir = $dlg.SelectedPath.TrimEnd('\') + '\'
    Pick-Dup 'in'
    UI-Log ((T "每组优先保留 {0} 里的那份") -f $script:keepInDir)
})
$ctl.BtnPickNone.Add_Click({ Pick-Dup 'none' })

# 「打开位置」按钮：在资源管理器里选中这个文件
$ctl.DupList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $btn = $e.OriginalSource
    if ($btn -is [System.Windows.Controls.Button] -and $btn.Tag) {
        Start-Process -FilePath "$env:SystemRoot\explorer.exe" -ArgumentList ("/select,`"{0}`"" -f $btn.Tag)
    }
})

$ctl.ModeSimilar.Add_Checked({ $ctl.SimilarRow.Visibility = 'Visible'; Update-FilterSummary })
$ctl.ModeSimilar.Add_Unchecked({ $ctl.SimilarRow.Visibility = 'Collapsed'; Update-FilterSummary })
$script:dupSimilar = $false
Register-BgJob 'similar' -Cancel look -ReadOnly -Done {
    $res = $sync.DupResult
    $cnt = if ($res) { $res.Count } else { 0 }
    $script:dupSimilar = $true
    $ctl.DupProgressText.Text = [string]$sync.SimNote
    End-Op ((T "完成，{0} 组相似照片") -f $cnt)
    if ($res) { Build-DupRows $res $cnt } else { Build-DupRows @() 0 }
    if ($script:dupRows -and $script:dupRows.Count -gt 0) {
        Pick-Dup 'none'
        UI-Log (T '相似照片不是同一个文件：没有自动勾选。每组第一张是分辨率最高的，看过以后自己勾要处理的；只能放进回收站或归档，不能永久删除，也不能合并。')
    } elseif (-not $sync.WasCancelled) { $ctl.EmptyDupText.Text = (T '没有找到相似的照片') }
}
function Start-SimilarScan([string[]]$paths, $range) {
    if (-not (Initialize-PhotoHash)) { Show-Sheet -Kind warn -Title (T '这台电脑上用不了相似照片') -Text (T '图片解码组件没有加载成功（运行记录里有原因）。') | Out-Null; return }
    $dist = if ($ctl.SimStrict.IsChecked) { 4 } elseif ($ctl.SimLoose.IsChecked) { 12 } else { 8 }
    $script:dupRows = $null; $script:dupByGroup = @{}; $ctl.DupList.ItemsSource = $null
    $ctl.EmptyDup.Visibility = 'Visible'; $ctl.EmptyDupText.Text = (T '正在找照片…')
    Set-DupFilterOpen $false
    Use-BgJob 'similar'; $sync.DupResult = $null; $sync.SimNote = ''
    Start-Op (T '查找相似照片')
    $ctl.DupProgressText.Text = (T '正在找照片…')
    UI-Busy $true
    UI-Log ((T "开始查找相似照片（相差 {0} 位以内）。位置：{1}") -f $dist, ($paths -join (T '；')))
    Start-Worker @'
[PhotoHash]::Cancel = $false
SetP @{ SubKind = 'none'; Detail = (T '列出照片') }
$list = [PhotoHash]::Scan([string[]]$arg.Roots, [long]$arg.Min, [long]$arg.Max, 200000)
$sync.SimSeen = $list.Count
if ($list.Count -ge 200000) { Log (T '照片太多，只看前 200000 张') }
SetP @{ SubKind = 'none'; Detail = ((T "算 {0:N0} 张照片的指纹") -f $list.Count); Steps = $list.Count; Step = 0 }
# 一边算一边报进度：分批
$batch = New-Object System.Collections.Generic.List[PhotoItem]
$k = 0
foreach ($p in $list) {
    $batch.Add($p); $k++
    if ($batch.Count -ge 200) { [PhotoHash]::HashAll($batch); $batch.Clear(); SetP @{ Step = $k }; if (Stopping) { break } }
}
if ($batch.Count -gt 0 -and -not (Stopping)) { [PhotoHash]::HashAll($batch) }
$stopped = [bool](Stopping)
$n = [PhotoHash]::Group($list, [int]$arg.Dist)
$by = @{}
foreach ($p in $list) { if ($p.Bad -or $p.Group -lt 0) { continue }; if (-not $by.ContainsKey($p.Group)) { $by[$p.Group] = New-Object System.Collections.Generic.List[PhotoItem] }; $by[$p.Group].Add($p) }
$groups = New-Object System.Collections.Generic.List[DupGroup]
foreach ($g in $by.Values) {
    if ($g.Count -lt 2) { continue }
    $dg = New-Object DupGroup
    $big = $g | Sort-Object { $_.Size } -Descending | Select-Object -First 1
    $dg.Name = (T "相似照片：{0}") -f [IO.Path]::GetFileName($big.Path); $dg.Size = $big.Size; $dg.Verified = $false
    foreach ($p in ($g | Sort-Object { $_.W * $_.H } -Descending)) {
        $f = New-Object DupFile
        $f.Path = $p.Path; $f.Size = $p.Size; $f.Modified = $p.Modified
        $f.Risk = (T "{0}×{1}，相差 {2} 位。相似不等于相同：先看一眼再决定") -f $p.W, $p.H, ([PhotoHash]::Dist($p.Hash, $big.Hash))
        $dg.Files.Add($f)
    }
    $groups.Add($dg)
}
$sorted = @($groups | Sort-Object { $_.Waste } -Descending)
$sync.DupResult = New-Object System.Collections.Generic.List[DupGroup]
foreach ($g in $sorted) { $sync.DupResult.Add($g) }
$sync.SimNote = (T "看了 {0:N0} 张照片，{1:N0} 张读不了，{2} 组相似{3}") -f $list.Count, [PhotoHash]::Failed, $groups.Count, $(if ($stopped) { (T '（中途停止）') } else { '' })
'@ @{ Roots = [string[]]$paths; Min = [long][math]::Max([double]1, [double]$range.Min); Max = [long]$range.Max; Dist = $dist }
}
Register-BgJob 'dup' -Cancel look -Stop { [DupFinder]::Cancel = $true } -ReadOnly -Done {
    $script:dupSimilar = $false
    $res = $sync.DupResult
    $cnt = if ($res) { $res.Count } else { 0 }
    $stopped = [DupFinder]::Cancel
    $ctl.DupProgressText.Text = ((T "{0}看过 {1:N0} 个文件夹、{2:N0} 个文件，找到 {3:N0} 组重复。") -f $(if ($stopped) { (T '已停止。') } else { (T '查找完成。') }), [DupFinder]::DirsSeen, [DupFinder]::FilesSeen, $cnt)
    End-Op $(if ($stopped) { ((T "已停止，找到 {0} 组") -f $cnt) } else { ((T "完成，找到 {0} 组") -f $cnt) })
    if ($res) { Build-DupRows $res $cnt } else { Build-DupRows @() 0 }
    if ($script:dupRows -and $script:dupRows.Count -gt 0) {
        Pick-Dup 'new'
        UI-Log (T '已自动勾选：每组留最新的一份，其余删除。可以改勾选，或点上面的按钮换一种留法。')
    }
}
$ctl.BtnDupScan.Add_Click({
    $paths = @($script:roots | Where-Object { $_.Enabled } | ForEach-Object { $_.Path })
    if (-not $paths) { Show-Sheet -Title (T '还没选查找位置') -Text (T '请在「查找位置」里至少勾选一个文件夹或磁盘。') | Out-Null; Set-DupFilterOpen $true 'roots'; return }
    $range = Get-SizeRange
    if (-not $range.Ok) { Show-Sheet -Kind warn -Title (T '文件大小填写有误') -Text $range.Err | Out-Null; Set-DupFilterOpen $true 'size'; return }
    if ($ctl.ModeSimilar.IsChecked) { Start-SimilarScan $paths $range; return }
    $ext = Get-SelectedExt
    $script:dupRows = $null; $script:dupByGroup = @{}; $ctl.DupList.ItemsSource = $null
    $ctl.EmptyDup.Visibility = 'Visible'; $ctl.EmptyDupText.Text = (T '正在查找…')
    $arg = @{
        Roots     = [string[]]$paths
        Min       = [long][math]::Max([double]1, [double]$range.Min)
        Max       = [long]$range.Max
        MatchName = [bool]$ctl.ModeName.IsChecked
        Ext       = $ext
        Exact     = [bool]$ctl.SpeedExact.IsChecked
    }
    $sync.DriveNote = ''
    Set-DupFilterOpen $false
    Use-BgJob 'dup'; $sync.DupResult = $null
    Start-Op (T '查找重复文件')
    $ctl.DupProgressText.Text = (T '正在查找…')
    UI-Busy $true
    UI-Log ((T "开始查找重复文件：{0}。位置：{1}") -f $ctl.FilterSummary.Text, ($paths -join (T '；')))
    Start-Worker @'
$ext = $null; if ($arg.Ext) { $ext = [string[]]$arg.Ext }
# 看每块盘是固态还是机械：固态多线程并行读，机械硬盘单线程顺序读（并行反而让磁头来回跳）
$spec = New-Object System.Collections.ArrayList; $notes = @()
$cpu = [math]::Max(2, [math]::Min(8, [Environment]::ProcessorCount))
$letters = @($arg.Roots | ForEach-Object { if ($_ -match '^([A-Za-z]):') { $matches[1].ToUpper() } } | Sort-Object -Unique)
foreach ($L in $letters) {
    $kind = ''
    try {
        $part = Get-Partition -DriveLetter $L -ErrorAction Stop
        $pd = Get-PhysicalDisk -ErrorAction Stop | Where-Object { $_.DeviceId -eq [string]$part.DiskNumber } | Select-Object -First 1
        if ($pd) { $kind = [string]$pd.MediaType }
    } catch {}
    if ($kind -eq 'SSD' -or $kind -eq 'SCM') { $n = $cpu; $desc = ((T "固态硬盘，{0} 线程并行") -f $n) }
    elseif ($kind -eq 'HDD') { $n = 1; $desc = (T '机械硬盘，单线程按顺序读') }
    else { $n = 2; $desc = (T '类型未知，2 线程') }
    [void]$spec.Add("$($L):=$n"); $notes += "$($L): $desc"
}
if ($notes) { Log ((T "磁盘：") + ($notes -join (T '；'))); $sync.DriveNote = ($notes -join (T '；')) }
# NTFS 盘的文件表（已经在内存里的按变更日志补读；查整块盘时现读一次）：1 MB 以上的文件直接从里面列，不用逐个文件夹去看
$trees = New-Object 'System.Collections.Generic.List[DmNode]'
if ([long]$arg.Min -ge 1MB) {
    foreach ($L in $letters) {
        if (Stopping) { break }
        $whole = @($arg.Roots | Where-Object { ([string]$_).TrimEnd('\') -ieq "$($L):" }).Count -gt 0
        if (-not $whole -and -not [DiskMap]::HasIndex("$($L):")) { continue }   # 只查一个文件夹、文件表又不在手上：逐个看更快
        if ([FsTools]::IsSubst("$($L):")) { continue }
        try {
            SetP @{ Detail = ((T "读取 {0} 盘的文件表") -f $L) }
            $t = [DiskMap]::GetTree("$($L):", [DirStat]::ThreadsFor("$($L):"), $false, $false)
            $m = [string][DiskMap]::LastMethod
            if ($t -and $t.HasDisk -and ($m -eq 'mft' -or $m -eq 'mft-usn')) { $trees.Add($t); Log ((T "读取 {0} 盘的文件表：{1:N0} 个文件，用时 {2:N1} 秒") -f $L, $t.Files, ([double][DiskMap]::LastMs / 1000)) }
        } catch {}
    }
}
$sync.DupResult = [DupFinder]::Find([string[]]$arg.Roots, [long]$arg.Min, [long]$arg.Max, [bool]$arg.MatchName, $ext, [bool]$arg.Exact, [string[]]$spec, [DmNode[]]$trees.ToArray())
if ([DupFinder]::FromTreeRoots -gt 0) { Log ((T "{0} 个查找位置从文件表里列出文件（不用逐个文件夹去看）") -f [DupFinder]::FromTreeRoots) }
if (-not [DupFinder]::UsedFastEnum) { Log (T '提示：快速列举不可用，已改用普通方式列举文件（结果相同，只是慢一些）。') }
'@ $arg
})

$ctl.BtnDupStop.Add_Click({ [DupFinder]::Cancel = $true; try { [PhotoHash]::Cancel = $true } catch {}; UI-Log (T "正在停止...") })

Register-BgJob 'dupdel' -Cancel dupdel -Stop { [DupFinder]::Cancel = $true } -Done {
    $moveMode = ($sync.Mode -eq 'dupmove')
    $gone = @{}
    if ($sync.DupDeleted) { foreach ($p in $sync.DupDeleted) { $gone[$p.ToLowerInvariant()] = $true } }
    $left = New-Object System.Collections.Generic.List[DupGroup]
    foreach ($g in $script:dupGroups) {
        $ng = New-Object DupGroup
        $ng.Name = $g.Name; $ng.Size = $g.Size; $ng.Verified = $g.Verified
        foreach ($f in $g.Files) { if (-not $gone.ContainsKey($f.Path.ToLowerInvariant())) { $ng.Files.Add($f) } }
        if ($ng.Files.Count -ge 2) { $left.Add($ng) }
    }
    Build-DupRows $left $left.Count
    $nDel = if ($sync.DupDeleted) { $sync.DupDeleted.Count } else { 0 }
    $cardWasOpen = ($ctl.Overlay.Visibility -eq 'Visible')
    if ($moveMode) {
        $cx = [bool]$sync.WasCancelled
        End-Op ($(if ($cx) { (T "已中途取消，归档了 {0} 个文件") } else { (T "完成，归档了 {0} 个文件") }) -f $nDel)
        UI-Log ((T "归档完成：{0} 个文件已搬到 {1}") -f $nDel, $sync.DupMoveDest)
    } else {
        $bin = if ($script:lastRecycle) { (T "`n`n文件在回收站里，清空回收站后才真正释放磁盘空间。") } else { '' }
        $binShort = if ($script:lastRecycle) { (T '文件在回收站里，清空回收站后才真正释放空间。') } else { '' }
        $cx = [bool]$sync.WasCancelled
        End-Op ($(if ($cx) { (T "已中途取消，删除了 {0} 个文件") } else { (T "完成，删除了 {0} 个文件") }) -f $nDel) -KeepCard -headline ($(if ($cx) { (T "已中途取消：删除了 {0} 个重复文件，剩下的没删。{1}") } else { (T "删除了 {0} 个重复文件。{1}") }) -f $nDel, $binShort) -reportLines @(,@((T '没删的（内容和保留的那份不完全相同，或文件被占用）记在左下角的「运行记录」里。'), '#6E6E73', $false))
        try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
        if (-not $cardWasOpen) { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已中途取消') } else { (T '删除完成') }); Kind = 'done'; Text = ((T "删除了 {0} 个重复文件，共用时 {1}。{2}`n`n没删的（内容和保留的那份不完全相同，或文件被占用）记在「运行记录」里。") -f $nDel, (FmtSpan $script:lastElapsed), $bin) } }
    }
}
$ctl.BtnDupDelete.Add_Click({
    $plan = New-Object System.Collections.ArrayList
    $allChecked = 0; $risky = 0; $bytes = [double]0
    foreach ($gid in @($script:dupByGroup.Keys)) {
        $rows = $script:dupByGroup[$gid]
        $del  = @($rows | Where-Object { $_.ToDelete -and $_.CanDelete })
        if ($del.Count -eq 0) { continue }
        if ($del.Count -ge $rows.Count) { $allChecked++; continue }
        $keep = @($rows | Where-Object { -not $_.ToDelete } | ForEach-Object { $_.Path })
        $keepTicks = @{}; foreach ($kr in @($rows | Where-Object { -not $_.ToDelete })) { $keepTicks[[string]$kr.Path] = [long]$kr.ModifiedTicks }
        foreach ($r in $del) {
            [void]$plan.Add(@{ Path = $r.Path; Size = $r.Size; Keep = $keep; KeepTicks = $keepTicks; Verified = $r.Verified; Mtime = $r.ModifiedTicks })
            $bytes += $r.Size
            if ($r.HasRisk) { $risky++ }
        }
    }
    if ($plan.Count -eq 0) {
        if ($allChecked) { Show-Sheet -Kind warn -Title (T '每组至少要留一份') -Text ((T "有 {0} 组把所有副本都勾上了，这些组不会删除。") -f $allChecked) | Out-Null }
        return
    }
    $recycle = [bool]$ctl.DupRecycle.IsChecked
    if ($script:dupSimilar -and -not $recycle) {
        Show-Sheet -Kind warn -Title (T '相似照片只能放进回收站') -Text (T '相似照片不是同一个文件（分辨率、裁剪、压缩都可能不同），删错了没法从另一份恢复，所以只允许放进回收站。已经帮你勾上「放入回收站」。') | Out-Null
        $ctl.DupRecycle.IsChecked = $true; $recycle = $true
    }
    if ($script:dupSimilar) { foreach ($p in $plan) { $p.Similar = $true } }
    $script:lastRecycle = $recycle
    $msg = if ($script:dupSimilar) { (T "这些是相似照片，不是同一个文件：每组至少保留一份没勾选的，勾选的放进回收站。") } else { (T "每组至少保留一份没勾选的。") }
    $msg += if ($recycle) { (T "文件会放进回收站，可以恢复；清空回收站后才真正释放空间。") } else { (T "文件会被永久删除，不能恢复。") }
    if ($allChecked) { $msg += ((T "`n`n另有 {0} 组所有副本都被勾选，这些组会跳过。") -f $allChecked) }
    if ($risky)      { $msg += ((T "`n`n其中 {0} 个文件带有「注意」提示（程序目录或微信数据），请确认确实要删。") -f $risky) }
    $btnDel = if ($recycle) { (T '移到回收站') } else { (T '永久删除') }
    $ack = (T '我已确认这些文件删除后不会给我带来损失；因删除造成的后果由我自己承担。')
    if ((Show-Sheet -Kind danger -Title ((T "删除 {0} 个重复文件，释放 {1}？") -f $plan.Count, (Fmt $bytes)) -Text $msg -Buttons @((T '取消'), $btnDel) -Primary $btnDel -Destructive $(if ($recycle) { '' } else { $btnDel }) -Cancel (T '取消') -Confirm $ack) -ne $btnDel) { return }
    Use-BgJob 'dupdel'; $sync.DupDeleted = $null
    Start-Op ((T "删除 {0} 个重复文件") -f $plan.Count)
    UI-Busy $true
    UI-Log ((T "开始删除 {0} 个重复文件...") -f $plan.Count)
    Start-Worker @'
Add-Type -AssemblyName Microsoft.VisualBasic
$done = New-Object System.Collections.ArrayList
$i = 0; $total = $arg.Plan.Count; $freed = [double]0; $same = $false
$how = if ($arg.Recycle) { (T '重复文件：移到回收站') } else { (T '重复文件：永久删除') }
foreach ($p in $arg.Plan) {
    if (Stopping) { break }
    $i++
    SetP @{ Steps = $total; Step = $i; StepName = [IO.Path]::GetFileName($p.Path); SubKind = 'none' }
    # 再保险：保护打开时，C 盘个人文件夹里的文件无论如何不删
    if ($arg.Protect -and (Test-Personal $p.Path)) { Log ((T "  跳过（C 盘个人文件夹，受保护）：{0}") -f $($p.Path)); continue }
    $why = Get-DupBlock $p.Path (Test-Personal $p.Path)
    if ($why) { Log ((T "  跳过（{0}）：{1}") -f $why, $p.Path); continue }
    # 删之前再确认一次：要删的文件大小没变，并且至少有一份保留的副本还在、大小相同
    $fi = Get-Item -LiteralPath $p.Path -Force -ErrorAction SilentlyContinue
    if (-not $fi) { [void]$done.Add($p.Path); continue }
    if ($fi.Length -ne $p.Size -or ($p.Mtime -and $fi.LastWriteTime.Ticks -ne [long]$p.Mtime)) { Log ((T "  跳过（文件在扫描后被修改过）：{0}") -f $($p.Path)); continue }
    $kept = $false; $keepAt = ''
    foreach ($k in $p.Keep) {
        $ki = Get-Item -LiteralPath $k -Force -ErrorAction SilentlyContinue
        if (-not $ki) { continue }
        # 保留的那份和要删的其实是同一个文件（硬链接的两个名字，或者经过目录链接的两条路径）：删了就一份都不剩
        if ([FsTools]::SameFile($k, $p.Path)) { Log ((T "  跳过（和保留的那份是同一个文件，只是路径不同）：{0}") -f $($p.Path)); $kept = $false; $same = $true; break }
        if ($p.Similar) { $kept = $true; $keepAt = $k; break }   # 相似照片：保留的那份还在就行（大小本来就不同）
        if ($ki.Length -ne $p.Size) { continue }
        # 保留的那份在扫描后被改过（大小没变也算）：它已经不是那份内容了，不能拿它当保留
        if ($p.KeepTicks -and $p.KeepTicks.ContainsKey([string]$k) -and $ki.LastWriteTime.Ticks -ne [long]$p.KeepTicks[[string]$k]) { continue }
        if ($p.Verified) { $kept = $true; $keepAt = $k; break }
        # 抽样判定的组：和保留的那份逐字节比一遍，完全相同才删
        SetP @{ SubKind = 'verify'; Detail = $p.Path }
        if ([DupFinder]::SameContent($k, $p.Path)) { $kept = $true; $keepAt = $k; break }
    }
    SetP @{ SubKind = 'none' }
    if ($same) { $same = $false; continue }
    if (-not $kept -and (Stopping)) { break }   # 核对到一半取消了：这个文件不删
    if (-not $kept) { Log ((T "  没有删除（和保留的那份内容不完全相同，或保留的那份已不在）：{0}") -f $($p.Path)); continue }
    # 删除本身（再查一遍删不删得、放不放得进回收站、删完核对、写操作日志）都在 Invoke-SafeRemove 里
    $r = Invoke-SafeRemove -Item $fi -Scope dup -How $(if ($arg.Recycle) { 'recycle' } else { 'delete' }) -Bytes ([double]$p.Size) -AllowPersonal:(-not $arg.Protect) `
        -What $how -Detail ((T "{0}，保留的那份：{1}") -f (GB $p.Size), $keepAt)
    if ($r.Ok) {
        [void]$done.Add($p.Path); $freed += $p.Size
        if ($total -le 200 -or $i % 100 -eq 0) { Log ((T "  [{0}/{1}] 已删除  {2}") -f $i, $total, $p.Path) }
    } else { Log ((T "  删除失败  {0}：{1}") -f $($p.Path), $r.Why) }
}
Log ((T "删除完成：{0} 个文件，{1}。") -f $done.Count, $(if ($freed -ge 1GB) { "{0:N2} GB" -f ($freed / 1GB) } else { "{0:N1} MB" -f ($freed / 1MB) }))
$sync.DupDeleted = $done
'@ @{ Plan = $plan; Recycle = $recycle; Protect = [bool]$ctl.DupProtect.IsChecked }
})

# ------------------------------------------------------------
# 公用：打开位置、选磁盘
# ------------------------------------------------------------
function Open-Location([string]$path) {
    if (-not $path) { return }
    if (Test-Path -LiteralPath $path -PathType Leaf) { Start-Process -FilePath "$env:SystemRoot\explorer.exe" -ArgumentList ("/select,`"{0}`"" -f $path) }
    elseif (Test-Path -LiteralPath $path) { Start-Process -FilePath "$env:SystemRoot\explorer.exe" -ArgumentList ("`"{0}`"" -f $path) }
    else { Show-Sheet -Kind warn -Title (T '这个位置不存在') -Text $path | Out-Null }
}
function Fixed-Drives([switch]$NoSystem) {
    $all = @([IO.DriveInfo]::GetDrives() | Where-Object {
        try { $_.DriveType -eq 'Fixed' -and $_.IsReady -and (-not $NoSystem -or $_.Name.TrimEnd('\') -ine $env:SystemDrive) } catch { $false } })
    if (-not $NoSystem) { return $all }
    # 选目标盘用的（页面文件、临时文件夹）：移动硬盘排在后面，默认选中的是本机硬盘
    $plug = @($all | Where-Object { Test-PluggableDrive $_.Name.Substring(0, 2) })
    @(@($all | Where-Object { $plug -notcontains $_ }) + $plug)
}
# 目标盘下拉框里一行：盘符、空闲，移动硬盘标出来
function Drive-ChoiceLabel($d) { ((T "{0}  空闲 {1}") -f $d.Name.TrimEnd('\'), (Fmt $d.AvailableFreeSpace)) + $(if (Test-PluggableDrive $d.Name.Substring(0, 2)) { (T '，移动硬盘') } else { '' }) }
function Ask-Restart([string]$why) {
    if ((Show-Sheet -Kind info -Title (T '需要重启电脑才生效') -Text $why -Buttons @((T '稍后自己重启'), (T '现在重启')) -Primary (T '现在重启') -Cancel (T '稍后自己重启')) -eq (T '现在重启')) {
        & "$env:SystemRoot\System32\shutdown.exe" /r /t 15 /c (T "腾挪 ClearC：15 秒后重启，让刚才的设置生效") | Out-Null
    }
}
function Shorten-Mid([string]$p, [int]$n = 70) { if (-not $p -or $p.Length -le $n) { return $p }; return $p.Substring(0, 24) + '…' + $p.Substring($p.Length - ($n - 25)) }

# ------------------------------------------------------------
# 空间地图
# ------------------------------------------------------------
$script:mapRoot = $null; $script:mapCur = $null; $script:mapView = 'dirs'; $script:growRows = $null; $script:mapScanAt = $null
function Fill-MapDrives {
    $keep = if ($ctl.MapDrive.SelectedItem) { [string]$ctl.MapDrive.SelectedItem.Tag } else { "$env:SystemDrive\" }
    $ctl.MapDrive.Items.Clear()
    foreach ($d in (Fixed-Drives)) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        # 只写盘符：用了多少、剩多少写在下面每块盘的卡片上，这里不再写一遍
        $it.Content = $d.Name.TrimEnd('\') + $(if ($d.Name -ieq ($env:SystemDrive + '\')) { '  ' + (T '系统盘') } else { '' })
        $it.Tag = $d.RootDirectory.FullName
        [void]$ctl.MapDrive.Items.Add($it)
        if ($it.Tag -ieq $keep) { $ctl.MapDrive.SelectedItem = $it }
    }
    if (-not $ctl.MapDrive.SelectedItem -and $ctl.MapDrive.Items.Count -gt 0) { $ctl.MapDrive.SelectedIndex = 0 }
}
# 盘的健康信息（SSD 磨损、温度、通电时间）：在另一个线程里读，读到了写在标题下面
$script:dhPs = $null
# 在后台线程里跑一段引擎代码（不占主工作线程、不显示进度条），完成后在界面线程里回调。同一个 key 同时只跑一个
$script:bg = @{}
function Start-BgEngine([string]$key, [string]$code, $arg, [scriptblock]$done) {
    if ($script:bg[$key]) { return $false }
    $ps = $null
    try {
        $ps = [powershell]::Create()
        [void]$ps.AddScript("param(`$arg, `$engine)`nInvoke-Expression `$engine`n" + $code).AddArgument($arg).AddArgument($engine)
        $script:bg[$key] = @{ PS = $ps; AR = $ps.BeginInvoke(); Done = $done; Key = $key }
    } catch { Write-LogFile ("bg {0}: {1}" -f $key, $_.Exception.Message); if ($ps) { try { $ps.Dispose() } catch {} }; return $false }
    $t = New-Object System.Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(400); $t.Tag = $key
    $t.Add_Tick({
        $k = [string]$this.Tag; $j = $script:bg[$k]
        if (-not $j) { $this.Stop(); return }
        if (-not $j.AR.IsCompleted) { return }
        $this.Stop()
        $result = $null; $err = ''
        try { $out = $j.PS.EndInvoke($j.AR); if ($out.Count -gt 0) { $result = $out[$out.Count - 1] } } catch { $err = [string]$_.Exception.Message }
        try { foreach ($er in @($j.PS.Streams.Error | Select-Object -First 3)) { $err += ' | ' + [string]$er } } catch {}
        if ($err) { Write-LogFile ("bg {0}: {1}" -f $k, $err) }
        try { $j.PS.Dispose() } catch {}
        $script:bg.Remove($k)
        if ($j.Done) { try { & $j.Done $result $err } catch { Write-LogFile ("bg {0} done: {1}" -f $k, $_.Exception.Message) } }
    })
    $t.Start()
    return $true
}
function Stop-BgEngine([string]$key) { $j = $script:bg[$key]; if ($j) { try { $j.PS.Stop() } catch {} } }
function Start-DiskHealth {
    if ($script:dhPs) { return }
    $ctl.MapHealthNote.Text = (T '正在读取各块盘的健康信息…'); $ctl.MapHealthNote.Visibility = 'Visible'
    $drives = @(Fixed-Drives | ForEach-Object { $_.Name.TrimEnd('\') })
    if ($drives.Count -eq 0) { return }
    $code = 'param($drives, $engine) Invoke-Expression $engine; $o = @(); foreach ($d in $drives) { $h = Get-DiskHealthInfo $d; $h.Drive = $d; $o += $h }; ,$o'
    try {
        $ps = [powershell]::Create()
        [void]$ps.AddScript($code).AddArgument($drives).AddArgument($engine)
        $script:dhPs = $ps; $script:dhAr = $ps.BeginInvoke()
    } catch { $script:dhPs = $null; return }
    $t = New-Object System.Windows.Threading.DispatcherTimer
    $t.Interval = [TimeSpan]::FromMilliseconds(400)
    $t.Add_Tick({
        if (-not $script:dhPs) { $this.Stop(); return }
        if (-not $script:dhAr.IsCompleted) { return }
        $this.Stop()
        $lines = @(); $script:dhErr = ''
        try { $out = $script:dhPs.EndInvoke($script:dhAr); if ($out.Count -gt 0) { $lines = @($out[$out.Count - 1]) } } catch { $script:dhErr = [string]$_.Exception.Message }
        try { foreach ($er in @($script:dhPs.Streams.Error | Select-Object -First 3)) { $script:dhErr += ' | ' + [string]$er } } catch {}
        if ($script:dhErr) { Write-LogFile ('disk health: ' + $script:dhErr) }
        try { $script:dhPs.Dispose() } catch {}
        $script:dhPs = $null
        Show-DiskHealth $lines
    })
    $t.Start()
}
# 每块盘一张卡片。档位：温度 45 度以下绿、60 以下橙、再高红；磨损 10% 以下绿、50% 以下橙；用量 85% 以上橙、95% 以上红
function Show-DiskHealth($list) {
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[DiskCard]'
    $green = @('#1D7A35', '#E5F4E9'); $amber = @('#995700', '#FFF1DB'); $red = @('#C0101C', '#FDEBEC'); $grey = @('#6E6E73', '#F0F0F3')
    foreach ($h in @($list)) {
        if (-not $h -or -not $h.Drive) { continue }
        $c = New-Object DiskCard
        $c.Letter = [string]$h.Drive
        $c.Model = if ($h.Ok -and $h.Model) { $h.Model + $(if ($h.Media) { ' · ' + $h.Media } else { '' }) } else { (T '读不到型号和健康信息') }
        $u = Get-DriveUse ([string]$h.Drive + '\')
        $used = $u.Used; $total = $u.Total; $pct = $u.Pct
        $dw = [double]$win.Resources['DcCardW']; if ($dw -lt 100) { $dw = 300 }
        $c.UsedPct = $pct; $c.BarW = [math]::Round(($dw - 34) * $pct / 100.0)
        $c.UsedText = (T "已用 {0} / {1} · {2:N0}%") -f (Fmt $used), (Fmt $total), $pct
        $c.FreeText = (T "剩 {0}") -f (Fmt $u.Free)
        $c.BarBrush = if ($pct -ge 95) { '#FF3B30' } elseif ($pct -ge 85) { '#FF9F0A' } else { '#0071E3' }
        $worst = 0   # 0 绿 1 橙 2 红
        if ($h.Ok -and $h.Health) {
            $okh = ($h.Health -eq 'Healthy')
            $c.HealthText = if ($okh) { (T '健康') } else { ((T "健康状态：{0}") -f $h.Health) }
            $tone = if ($okh) { $green } else { $red }; if (-not $okh) { $worst = 2 }
        } else { $c.HealthText = (T '健康状态未知'); $tone = $grey }
        $c.HealthFg = $tone[0]; $c.HealthBg = $tone[1]
        if ($h.Ok -and $h.Temp -gt 0) {
            $c.TempText = (T "{0} °C") -f $h.Temp
            $tone = if ($h.Temp -gt 60) { $red } elseif ($h.Temp -gt 45) { $amber } else { $green }
            if ($h.Temp -gt 60) { $worst = [math]::Max($worst, 2) } elseif ($h.Temp -gt 45) { $worst = [math]::Max($worst, 1) }
            $c.TempFg = $tone[0]; $c.TempBg = $tone[1]
        }
        if ($h.Ok -and $h.Wear -ge 0) {
            $c.WearText = (T "磨损 {0}%") -f $h.Wear
            $tone = if ($h.Wear -gt 50) { $red } elseif ($h.Wear -gt 10) { $amber } else { $green }
            if ($h.Wear -gt 50) { $worst = [math]::Max($worst, 2) } elseif ($h.Wear -gt 10) { $worst = [math]::Max($worst, 1) }
            $c.WearFg = $tone[0]; $c.WearBg = $tone[1]
        }
        if ($h.Ok -and $h.Hours -gt 0) { $c.HoursText = (T "通电 {0:N0} 小时") -f $h.Hours }
        $c.Stripe = if (-not $h.Ok) { '#C7C7CC' } elseif ($worst -eq 2) { '#FF3B30' } elseif ($worst -eq 1) { '#FF9F0A' } else { '#34C759' }
        $tip = @((T '点一下扫描这块盘，下面显示它的详细情况。'))
        if ($h.Ok) {
            $tip += (T '温度：45 °C 以下正常，60 °C 以上偏高，长期高温会缩短固态硬盘寿命。')
            $tip += (T '磨损：固态硬盘已用掉的写入寿命，到 100% 厂商就不保了；10% 以下很新，50% 以上要开始考虑备份。')
            if ($h.ReadErrors -gt 0) { $tip += ((T "读错误 {0:N0} 次，有读错误请尽快备份。") -f $h.ReadErrors) }
            $tip += (T '这些数据从 Windows 的存储可靠性计数器读，只读不改；有的硬盘不报温度或磨损。')
        } else { $tip += (T '这台电脑的存储模块读不到这块盘的信息。') }
        $c.Tip = ($tip -join "`n")
        $col.Add($c)
    }
    $ctl.MapHealth.ItemsSource = $col
    Update-DcCardW
    Update-MapCardSel
    $ctl.MapHealthNote.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($col.Count -eq 0) { $ctl.MapHealthNote.Text = (T '读不到磁盘的健康信息（型号、磨损、温度）') }
    Update-MapOvHead
}
# 磁盘卡片显示着这块盘时，下面的概览就不再写一遍「已用多少 / 共多少」；卡片不显示（设置里关了、读不到）时才写
function Update-MapOvHead {
    if (-not $script:mapRoot) { return }
    $drive = ''; try { $drive = $script:mapRoot.FullPath().TrimEnd('\') } catch {}
    $shown = $false
    if ($ctl.MapHealthBox.Visibility -eq 'Visible') { foreach ($c in @($ctl.MapHealth.ItemsSource)) { if ($c -and ([string]$c.Letter).TrimEnd('\') -ieq $drive) { $shown = $true } } }
    $ctl.MapOvHead.Visibility = if ($shown) { 'Collapsed' } else { 'Visible' }
}
# 选中的盘：卡片描边跟着下拉框走
function Update-MapCardSel {
    $sel = if ($ctl.MapDrive.SelectedItem) { ([string]$ctl.MapDrive.SelectedItem.Tag).TrimEnd('\') } else { '' }
    $any = $false
    foreach ($c in @($ctl.MapHealth.ItemsSource)) { if (-not $c) { continue }; $on = $sel -and ([string]$c.Letter).TrimEnd('\') -ieq $sel; if ($c.Sel -ne $on) { $c.Sel = $on; $any = $true } }
    if ($any) { try { $ctl.MapHealth.Items.Refresh() } catch {} }
}
$ctl.MapDrive.Add_SelectionChanged({ Update-MapCardSel })
# 点卡片 = 选这块盘并扫描它（已经显示的就是这块盘时不重扫；正在忙别的就只选上）
function Select-MapDriveCard([string]$letter, [bool]$scan = $true) {
    $hit = $null
    foreach ($it in $ctl.MapDrive.Items) { if (([string]$it.Tag).StartsWith($letter, [StringComparison]::OrdinalIgnoreCase)) { $hit = $it } }
    if (-not $hit) { return }
    $ctl.MapDrive.SelectedItem = $hit
    if (-not $scan) { return }
    $root = [string]$hit.Tag
    $shown = if ($script:mapRoot) { try { $script:mapRoot.FullPath() } catch { '' } } else { '' }
    if ($shown -and $shown.TrimEnd('\') -ieq $root.TrimEnd('\')) { UI-Log ((T "空间地图：下面已经是 {0} 的结果；要重新扫描点「扫描」") -f $root.TrimEnd('\')); return }
    if ($script:worker) { UI-Log (T '空间地图：正在忙别的，等它做完再点「扫描」'); return }
    if ($script:uiTest) { $script:uiOpened.Add('scan:' + $root); return }
    Start-MapScan $root
}
$ctl.MapHealth.AddHandler([System.Windows.UIElement]::MouseLeftButtonUpEvent, [System.Windows.Input.MouseButtonEventHandler]{
    param($s, $e)
    $el = $e.OriginalSource
    while ($el -and -not ($el -is [System.Windows.Controls.Border] -and $el.Tag -is [DiskCard])) { $el = [System.Windows.Media.VisualTreeHelper]::GetParent($el) }
    if (-not $el) { return }
    Select-MapDriveCard ([string]$el.Tag.Letter) $true
})
Register-BgJob 'map' -Cancel look -ReadOnly -Done {
    $root = $sync.MapResult
    $mm = [string]$sync.MapMethod; $secs = [double]$sync.MapMs / 1000
    # 读文件表时，读完以后（核对的时候）才点停止的，结果是完整的
    $stopped = ($mm -eq 'mft-partial') -or ([DiskMap]::Cancel -and $mm -notlike 'mft*')
    if ($sync.MapNote -and $mm -notlike 'mft*') { UI-Log ((T "空间地图：没能直接读取文件表（{0}），改为逐个文件夹扫描") -f $sync.MapNote) }
    if ($root) {
        $script:mapHow = if ($mm -eq 'mft-usn') { (T '按变更日志更新') } elseif ($mm -like 'mft*') { (T '直接读文件表') } else { (T '逐个文件夹扫描') }
        UI-Log ((T "空间地图：{0}，用时 {1:N1} 秒") -f $script:mapHow, $secs)
        [DiskMap]::Use($root)
        $script:mapMethod = $mm
        $script:mapRoot = $root; $script:mapCur = $root; $script:mapScanAt = Get-Date
        Reset-MapHistory; $script:worthKey = $null
        $script:movedTargets = $null
        $script:prevSnap = $null
        if (-not $stopped) { try { Update-Growth $root } catch { $script:growNote = (T '没能和上次比较') } } else { $script:growNote = (T '这次扫描中途停止了，不和上次比较') }
        End-Op ($(if ($stopped) { (T "已中途停止，看过 {0:N0} 个文件，共 {1}") } else { (T "完成，{0:N0} 个文件，共 {1}") }) -f $root.Files, (Fmt $root.Size))
        $script:recentRows = $null; $script:recentNote = ''
        if ($script:mapView -eq 'grow') { Set-MapView 'grow' } elseif ($script:mapView -eq 'files') { Show-MapOverview; Show-MapFiles } elseif ($script:mapView -eq 'types') { Show-MapTypes } elseif ($script:mapView -eq 'recent') { Show-MapOverview; Show-MapRecent } else { Show-MapLevel $root }
        if ($stopped) { $ctl.MapInfo.Text = (T '扫描中途停止了，下面只是已经看过的部分') }
        Add-History
    } else { End-Op (T '没有完成') }
    $ctl.BtnMapStop.IsEnabled = $false
}
function Start-MapScan([string]$root) {
    if ($script:worker -or -not $root) { return }
    $di = $null; try { $di = New-Object System.IO.DriveInfo $root } catch {}
    $sync.MapUsed = if ($di) { [double]($di.TotalSize - $di.AvailableFreeSpace) } else { [double]0 }
    $sync.MapRoot = $root; $sync.MapResult = $null; $sync.MapMethod = ''; $sync.MapNote = ''
    [DiskMap]::Cancel = $false
    Use-BgJob 'map'
    Start-Op ((T "扫描 {0}") -f $root)
    UI-Busy $true; $ctl.BtnMapStop.IsEnabled = $true
    $ctl.EmptyMap.Visibility = 'Visible'; $ctl.EmptyMapText.Text = (T '正在扫描…')
    $ctl.MapList.ItemsSource = $null; $ctl.MapGrow.ItemsSource = $null; $ctl.BtnMapExport.IsEnabled = $false; $ctl.BtnMapReport.IsEnabled = $false
    $ctl.MapTree.Children.Clear()
    UI-Log ((T "空间地图：开始扫描 {0}") -f $root)
    Start-Worker @'
# 能读文件表（MFT）就读；读不了再逐个文件夹扫一遍
$sync.MapResult = [DiskMap]::GetTree($arg.Root, [DirStat]::ThreadsFor($arg.Root), $true, $true)
$sync.MapMethod = [string][DiskMap]::LastMethod; $sync.MapMs = [double][DiskMap]::LastMs; $sync.MapNote = [string][DiskMap]::LastNote
'@ @{ Root = $root }
}
$ctl.BtnMapScan.Add_Click({ if ($ctl.MapDrive.SelectedItem) { Start-MapScan ([string]$ctl.MapDrive.SelectedItem.Tag) } })
$ctl.BtnMapStop.Add_Click({ [DiskMap]::Cancel = $true; UI-Log (T '空间地图：正在停止…') })

function New-MapRow($name, $path, [double]$size, [double]$max, [double]$parent, [bool]$isDir, $node, [string]$meta, [string]$kind) {
    $r = New-Object MapRow
    $r.Name = $name; $r.Path = $path; $r.Size = [long]$size; $r.SizeText = Fmt $size; $r.IsDir = $isDir; $r.Node = $node; $r.Meta = $meta; $r.Disk = -1; $r.Kind = $kind
    $r.Bar = if ($max -gt 0) { [math]::Max([double]2, 160.0 * $size / $max) } else { 0 }
    if ($size -le 0) { $r.Bar = 0 }
    $r.Pct = if ($parent -gt 0) { "{0:N1}%" -f (100.0 * $size / $parent) } else { '' }
    switch ($kind) {
        'dir'  { $r.Glyph = [string][char]0xE8B7; $r.GlyphBrush = '#0A84FF' }
        'link' { $r.Glyph = [string][char]0xE71B; $r.GlyphBrush = '#8E8E93' }
        'more' { $r.Glyph = [string][char]0xE712; $r.GlyphBrush = '#8E8E93' }
        'type' { $r.Glyph = [string][char]0xE8FD; $r.GlyphBrush = '#0A84FF' }
        'recent' { $r.Glyph = [string][char]0xE823; $r.GlyphBrush = '#0A84FF' }
        default { $r.Glyph = [string][char]0xE8A5; $r.GlyphBrush = '#8E8E93' }
    }
    $why = if ($path -and $kind -ne 'type' -and $kind -ne 'recent') { Get-DeleteBlock $path } else { '' }
    if (-not $why -and $path -and (Test-ChatPath $path)) { $why = (T '聊天记录里的文件只能查看和打开位置；要腾地方，到「搬家管理」把整个聊天记录搬到其他盘') }
    if ($kind -eq 'type' -or $kind -eq 'recent') { $why = (T '这一行是统计，不是文件；双击查看') }
    $r.Locked = [bool]$why; $r.LockTip = $why
    if ($path -and $script:mapMarks -and $script:mapMarks.Contains((Get-MarkKey $r))) { $r.Marked = $true }
    return $r
}
# 路径在不在某个聊天软件的聊天记录文件夹里（这些只看不删，要腾地方就整体搬家）
function Test-ChatPath([string]$path) {
    if ($null -eq $script:chatDirs) {
        $script:chatDirs = New-Object System.Collections.Generic.List[string]
        foreach ($pat in @('*WhatsAppDesktop*', 'MSTeams*', 'FACEBOOK.317180B0BB486*', '*TelegramDesktop*', '*Signal*', '*LINE*')) {
            foreach ($d in @(Get-ChildItem -LiteralPath (Join-Path $env:LOCALAPPDATA 'Packages') -Directory -Filter $pat -Force -ErrorAction SilentlyContinue)) { $script:chatDirs.Add($d.FullName.TrimEnd('\')) }
        }
        foreach ($c in $catalog) {
            if ($c.Tier -ne 'chat' -or -not $c.Paths) { continue }
            foreach ($p in $c.Paths) { if ($p) { foreach ($it in @(Get-PathItems $p)) { if ($it.PSIsContainer) { $script:chatDirs.Add($it.FullName.TrimEnd('\')) } } } }
        }
    }
    $p = $path.TrimEnd('\')
    foreach ($d in $script:chatDirs) { if ($p -ieq $d -or $p.StartsWith($d + '\', [StringComparison]::OrdinalIgnoreCase)) { return $true } }
    return $false
}
# 实际占用和硬链接的说明（快速扫描读文件表时才知道；设置里可以关掉）
function Get-DiskNote([double]$size, [double]$disk, [double]$shared, [bool]$isFile) {
    $t = ''
    if ($isFile -and $shared -gt 0) { $t += (T ' · 硬链接：别处还有同一份，删了这个不腾空间') }
    elseif (-not $isFile -and $shared -ge 32MB -and $shared -ge $size * 0.05) { $t += (T " · 其中 {0} 是硬链接（别处还有同一份）") -f (Fmt $shared) }
    if ($disk -ge 0 -and ($size - $disk) -ge 32MB -and $disk -lt $size * 0.85) { $t += (T " · 实际只占 {0}") -f (Fmt $disk) }
    return $t
}
# 文件大小、实际占用、压缩后大小：NTFS 压缩过的文件，实际占用就是压缩后的大小
function Get-SizeNote([string]$path, [double]$size, [double]$disk, [double]$shared) {
    if ($disk -lt 0 -or ($size - $disk) -lt 32MB -or $disk -ge $size * 0.85) { return Get-DiskNote $size $disk $shared $true }
    if ($path -and [FsTools]::IsCompressed($path)) { return (T " · NTFS 压缩后 {0}（文件大小 {1}）") -f (Fmt $disk), (Fmt $size) }
    return Get-DiskNote $size $disk $shared $true
}
# 同一个列表重新列一遍时（改了设置、删完、方块图和文件夹之间切换、找文件改条件），原来选中的还选着
function Get-MapKeep([string]$key) {
    $keep = @{}
    if ($script:mapListKey -eq $key) { foreach ($x in @($ctl.MapList.SelectedItems)) { if ($x.Path) { $keep[([string]$x.Path).ToLowerInvariant()] = $true } } }
    $script:mapListKey = $key
    return $keep
}
function Restore-MapKeep($keep) {
    if ($keep.Count -eq 0) { return }
    $script:bulkSel = $true
    try { foreach ($x in @($ctl.MapList.Items)) { if ($x.Path -and $keep.ContainsKey(([string]$x.Path).ToLowerInvariant())) { [void]$ctl.MapList.SelectedItems.Add($x) } } }
    finally { $script:bulkSel = $false }
}
function Show-MapLevel($node) {
    if (-not $node) { return }
    $keep = Get-MapKeep ('dirs|' + $node.FullPath())
    # 换了文件夹：记下刚才在哪，好「后退」；后退、前进自己不记
    if ($script:mapCur -and -not [object]::ReferenceEquals($script:mapCur, $node) -and -not $script:mapNavQuiet) {
        $script:mapBack.Add($script:mapCur); if ($script:mapBack.Count -gt 50) { $script:mapBack.RemoveAt(0) }
        $script:mapFwd.Clear()
    }
    $script:mapCur = $node
    $dn = Get-Flag 'MapDisk'
    $hasDisk = $dn -and $script:mapRoot -and $script:mapRoot.HasDisk
    $path = $node.FullPath()
    $rows = New-Object System.Collections.Generic.List[MapRow]
    # 只列最大的 500 项（子文件夹和这一层自己的文件放在一起比），其余合成一行：上万项的文件夹（比如 WinSxS）也能马上打开
    $cap = 500
    $kids = [DiskMap]::TopKids($node, $cap)
    $files = [DiskMap]::TopFiles($path, 300)   # 这一层自己的文件：现场列一下
    $sorted = New-Object System.Collections.ArrayList
    $i = 0; $j = 0
    while ($sorted.Count -lt $cap -and ($i -lt $kids.Count -or $j -lt $files.Count)) {
        if ($j -ge $files.Count -or ($i -lt $kids.Count -and $kids[$i].Size -ge $files[$j].Size)) { [void]$sorted.Add(@{ K = $kids[$i]; S = [double]$kids[$i].Size }); $i++ }
        else { [void]$sorted.Add(@{ F = $files[$j]; S = [double]$files[$j].Size }); $j++ }
    }
    $restN = [long]($node.Kids.Count - $i) + [math]::Max([long]0, [long]$node.OwnFiles - $j)
    $restB = [double]$node.Size; foreach ($x in $sorted) { $restB -= $x.S }
    $max = if ($sorted.Count -gt 0) { [double]$sorted[0].S } else { 0 }
    foreach ($x in $sorted) {
        if ($x.K) {
            $k = $x.K; $p = $k.FullPath()
            if ($k.IsLink) {
                $t = LinkTarget $p
                [void]$rows.Add((New-MapRow $k.Name $p 0 $max $node.Size $false $k ((T "链接，指向 ") + $(if ($t) { $t } else { (T '其他位置') }) + (T "（多半是搬家留下的，不占这块盘）")) 'link'))
                continue
            }
            $when = if ($k.LastWrite -gt 0) { try { [DateTime]::FromFileTime($k.LastWrite).ToString('yyyy-MM-dd') } catch { '' } } else { '' }
            $meta = (T "{0:N0} 个文件") -f $k.Files
            if ($when) { $meta += ((T " · 最近修改 {0}") -f $when) }
            if ($script:prevSnap -and $script:prevSnap.Count -gt 0) {
                $key = $p.ToLowerInvariant()
                if ($script:prevSnap.ContainsKey($key)) {
                    $dd = [double]$k.Size - [double]$script:prevSnap[$key]
                    if ([math]::Abs($dd) -ge 10MB) { $meta += ((T " · 比上次 {0}") -f ($(if ($dd -gt 0) { '+' } else { '−' }) + (Fmt ([math]::Abs($dd))))) }
                }
            }
            if ($k.Denied) { $meta += (T ' · 部分内容没有权限读取') }
            if ($hasDisk) { $meta += Get-DiskNote ([double]$k.Size) ([double]$k.Disk) ([double]$k.Shared) $false }
            $row = New-MapRow $k.Name $p $k.Size $max $node.Size $true $k $meta 'dir'
            $row.When = $when; $row.FileCount = [long]$k.Files
            if ($script:mapRoot.HasDisk) { $row.Disk = [long]$k.Disk }
            [void]$rows.Add($row)
        } else {
            $f = $x.F
            $fm = (T "文件 · 修改于 {0:yyyy-MM-dd}") -f $f.Modified
            $fd = [double]$f.Disk
            # 目录里记的实际占用看着明显小（压缩、稀疏、只在云端）：再问一次 Windows，以它为准
            if ($fd -ge 0 -and ([double]$f.Size - $fd) -ge 32MB) { $fd = [double][FsTools]::OnDisk($f.Path) }
            if ($dn) { $fm += Get-SizeNote $f.Path ([double]$f.Size) $fd 0 }
            $row = New-MapRow $f.Name $f.Path $f.Size $max $node.Size $false $null $fm 'file'
            $row.When = '{0:yyyy-MM-dd HH:mm}' -f $f.Modified
            $row.Disk = [long]$fd
            [void]$rows.Add($row)
        }
    }
    if ($restN -gt 0) {
        $more = New-MapRow ((T "其余 {0:N0} 项") -f $restN) '' ([math]::Max([double]0, $restB)) $max $node.Size $false $null (T '这里只列出最大的 500 项；其余的可以点「打开位置」在资源管理器里看') 'more'
        $more.Locked = $true; $more.LockTip = (T '这一行是合在一起的其余项目'); $more.IsSummary = $true
        $more.Bar = [math]::Min([double]160, $more.Bar)
        [void]$rows.Add($more)
    }
    $ctl.MapList.ItemsSource = $rows
    Restore-MapKeep $keep
    $ctl.MapPath.Text = $path
    Show-MapCrumbs $node
    $scanNote = if ($script:mapScanAt) { (T " · 扫描于 {0:HH:mm}（{1}）") -f $script:mapScanAt, $script:mapHow } else { '' }
    # 在盘的最上一层不写「这一层共多少」：按文件大小加起来的数和盘的已用空间对不上（硬链接、压缩、文件表），上面卡片写的才是已用
    $ctl.MapInfo.Text = if ($node.Parent) { (T "这一层共 {0}，{1:N0} 个文件{2}") -f (Fmt $node.Size), $node.Files, $scanNote } else { (T "{0:N0} 个文件{1}") -f $node.Files, $scanNote }
    if ($script:mapView -eq 'tree') { $ctl.MapInfo.Text += $(if (Test-CheckMode) { (T ' · 点方块在下面的列表里找到这一行，勾上的方块会描边；双击进入') } else { (T ' · 点方块就是选中下面列表里的那一行，列表里选中的方块会描边；双击进入') }) }
    $ctl.BtnMapAcct.Visibility = if ($script:mapRoot -and $script:mapRoot.HasDisk -and (Get-Mode) -ge 2) { 'Visible' } else { 'Collapsed' }
    $ctl.BtnMapUp.IsEnabled = ($null -ne $node.Parent)
    $ctl.BtnMapBack.IsEnabled = $script:mapBack.Count -gt 0; $ctl.BtnMapFwd.IsEnabled = $script:mapFwd.Count -gt 0
    $ctl.EmptyMap.Visibility = if ($rows.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($rows.Count -eq 0) { $ctl.EmptyMapText.Text = (T '这个文件夹是空的') }
    $ctl.BtnMapExport.IsEnabled = ($rows.Count -gt 0)
    $ctl.BtnMapReport.IsEnabled = $true
    if ($script:mapView -eq 'tree') { Draw-MapTree }
    Show-MapOverview
    Update-MapSel
}
# ---------- 后退 / 前进 / 上一级，路径上的每一层都能点（参考 disktree） ----------
$script:mapBack = New-Object System.Collections.Generic.List[object]; $script:mapFwd = New-Object System.Collections.Generic.List[object]; $script:mapNavQuiet = $false
function Reset-MapHistory { $script:mapBack.Clear(); $script:mapFwd.Clear(); $ctl.BtnMapBack.IsEnabled = $false; $ctl.BtnMapFwd.IsEnabled = $false }
function Move-MapHistory([int]$dir) {
    # 直接赋值（不用 if 表达式）：if 表达式会把列表展开成固定大小的数组，RemoveAt 就会出错
    if ($dir -lt 0) { $from = $script:mapBack; $to = $script:mapFwd } else { $from = $script:mapFwd; $to = $script:mapBack }
    if ($from.Count -eq 0 -or -not $script:mapCur) { return }
    $n = $from[$from.Count - 1]; $from.RemoveAt($from.Count - 1)
    $to.Add($script:mapCur)
    if ($script:mapView -ne 'dirs' -and $script:mapView -ne 'tree') { $ctl.MapViewDirs.IsChecked = $true }
    $script:mapNavQuiet = $true
    try { Show-MapLevel $n } finally { $script:mapNavQuiet = $false }
}
function Go-MapUp { if ($script:mapCur -and $script:mapCur.Parent) { Show-MapLevel $script:mapCur.Parent } }
$ctl.BtnMapBack.Add_Click({ Move-MapHistory -1 })
$ctl.BtnMapFwd.Add_Click({ Move-MapHistory 1 })
# 鼠标的后退、前进侧键；Alt+← / Alt+→；Backspace 上一级（在输入框里打字时不管）
$ctl.PageMap.Add_PreviewMouseDown({
    param($s, $e)
    if ($e.ChangedButton -eq [System.Windows.Input.MouseButton]::XButton1) { Move-MapHistory -1; $e.Handled = $true }
    elseif ($e.ChangedButton -eq [System.Windows.Input.MouseButton]::XButton2) { Move-MapHistory 1; $e.Handled = $true }
})
$ctl.PageMap.Add_PreviewKeyDown({
    param($s, $e)
    if ([System.Windows.Input.Keyboard]::FocusedElement -is [System.Windows.Controls.TextBox]) { return }
    $alt = ([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Alt) -ne 0
    $k = if ($e.Key -eq [System.Windows.Input.Key]::System) { $e.SystemKey } else { $e.Key }
    if ($alt -and $k -eq [System.Windows.Input.Key]::Left) { Move-MapHistory -1; $e.Handled = $true }
    elseif ($alt -and $k -eq [System.Windows.Input.Key]::Right) { Move-MapHistory 1; $e.Handled = $true }
    elseif (-not $alt -and $k -eq [System.Windows.Input.Key]::Back -and ($script:mapView -eq 'dirs' -or $script:mapView -eq 'tree')) { Go-MapUp; $e.Handled = $true }
})
# 路径：每一层一个按钮，最多显示最后 6 层（前面的用「…」代替，点「…」回到再上一层）
function Show-MapCrumbs($node) {
    $cr = $ctl.MapCrumbs; $cr.Children.Clear()
    $chain = New-Object System.Collections.Generic.List[object]
    for ($n = $node; $n; $n = $n.Parent) { $chain.Insert(0, $n) }
    $start = [math]::Max(0, $chain.Count - 6)
    $link = $win.FindResource('LinkButton')
    $add = {
        param([string]$text, $target, [bool]$last)
        if ($cr.Children.Count -gt 0) { $sep = New-Object System.Windows.Controls.TextBlock; $sep.Text = '›'; $sep.Foreground = New-Brush '#86868B'; $sep.Margin = New-Object System.Windows.Thickness 5, 0, 5, 0; $sep.VerticalAlignment = 'Center'; [void]$cr.Children.Add($sep) }
        if ($last) { $t = New-Object System.Windows.Controls.TextBlock; $t.Text = $text; $t.FontWeight = 'SemiBold'; $t.VerticalAlignment = 'Center'; $t.TextTrimming = 'CharacterEllipsis'; $t.MaxWidth = 260; [void]$cr.Children.Add($t); return }
        $b = New-Object System.Windows.Controls.Button; $b.Style = $link; $b.Content = $text; $b.Tag = $target; $b.VerticalAlignment = 'Center'; $b.ToolTip = $target.FullPath()
        $b.Add_Click({ $script:mapCrumbHit = $this.Tag; if ($script:mapView -ne 'dirs' -and $script:mapView -ne 'tree') { $ctl.MapViewDirs.IsChecked = $true }; Show-MapLevel $this.Tag })
        [void]$cr.Children.Add($b)
    }
    if ($start -gt 0) { & $add '…' $chain[$start - 1] $false }
    for ($i = $start; $i -lt $chain.Count; $i++) {
        $n = $chain[$i]; $nm = [string]$n.Name; if ($i -eq 0) { $nm = $nm.TrimEnd('\') }
        & $add $nm $n ($i -eq $chain.Count - 1)
    }
    $cr.Visibility = 'Visible'; $ctl.MapPath.Visibility = 'Collapsed'
}
# ---------- 待删清单：在不同文件夹里挑要删的，先放进清单，一直看得见删完以后还剩多少，看过清单再一起删（参考 disktree） ----------
# 放进一个文件夹时，清单里它里面的项目合进它；已经在清单里的文件夹里面的东西不再单独放
$script:mapMarks = [ordered]@{}
function Get-MarkKey($r) { ([string]$r.Path).TrimEnd('\').ToLowerInvariant() }
function Add-MapMarks($rows) {
    $added = 0; $inside = 0
    foreach ($r in @($rows)) {
        if (-not $r -or $r.Locked -or $r.IsSummary -or -not $r.Path -or $r.Size -le 0 -or ($r.Kind -ne 'dir' -and $r.Kind -ne 'file')) { continue }
        $k = Get-MarkKey $r
        if ($script:mapMarks.Contains($k)) { continue }
        $up = $false; foreach ($m in @($script:mapMarks.Keys)) { if ($k.StartsWith($m + '\')) { $up = $true; break } }
        if ($up) { $inside++; continue }
        foreach ($m in @($script:mapMarks.Keys)) { if ($m.StartsWith($k + '\')) { $script:mapMarks[$m].Marked = $false; $script:mapMarks.Remove($m) } }
        $script:mapMarks[$k] = $r; $r.Marked = $true; $added++
    }
    Update-MapMarks
    if ($inside -gt 0) { $ctl.MapSel.Text = (T "{0} 项所在的文件夹已经在待删清单里，不用再单独放") -f $inside }
    return $added
}
function Remove-MapMarks($rows) {
    foreach ($r in @($rows)) { if (-not $r -or -not $r.Path) { continue }; $k = Get-MarkKey $r; if ($script:mapMarks.Contains($k)) { $script:mapMarks[$k].Marked = $false; $script:mapMarks.Remove($k) }; $r.Marked = $false }
    Update-MapMarks
}
function Clear-MapMarks { foreach ($m in @($script:mapMarks.Values)) { $m.Marked = $false }; $script:mapMarks.Clear(); Update-MapMarks }
# 清单里的东西删掉能腾出多少：知道实际占用的按实际占用算
function Get-MarkBytes($r) { if ($r.Disk -ge 0 -and $script:mapRoot -and $script:mapRoot.HasDisk) { [double]$r.Disk } else { [double]$r.Size } }
function Update-MapMarks {
    $n = $script:mapMarks.Count
    # 列表里现在显示的行（换过文件夹再回来是新的行）跟着清单走：清空、去掉、合进上级文件夹以后不再标「待删」
    foreach ($x in @($ctl.MapList.Items)) { if ($x -is [MapRow] -and $x.Path) { $want = ($n -gt 0 -and $script:mapMarks.Contains((Get-MarkKey $x))); if ([bool]$x.Marked -ne $want) { $x.Marked = $want } } }
    $ctl.MapMarkBar.Visibility = if ($n -gt 0) { 'Visible' } else { 'Collapsed' }
    if ($n -eq 0) { return }
    $tot = [double]0; $byDrive = @{}
    foreach ($r in @($script:mapMarks.Values)) { $b = Get-MarkBytes $r; $tot += $b; $d = ([string]$r.Path).Substring(0, 2).ToUpperInvariant(); $byDrive[$d] = [double]$byDrive[$d] + $b }
    $parts = @(foreach ($d in @($byDrive.Keys | Sort-Object)) { $free = DriveFree ($d + '\'); (T "{0} 现在空闲 {1}，删完约 {2}") -f $d, (Fmt $free), (Fmt ($free + $byDrive[$d])) })
    $ctl.MapMarkText.Text = ((T "待删清单：{0} 项，共 {1}。") -f $n, (Fmt $tot)) + ($parts -join (T '；')) + (T '（放进回收站的，清空回收站后才腾出来）')
    $ctl.BtnMarkDelete.IsEnabled = -not $script:worker
}
function Show-MapMarks {
    if ($script:mapMarks.Count -eq 0) { return }
    $items = @(@($script:mapMarks.Values) | Sort-Object { -(Get-MarkBytes $_) } | Select-Object -First 60 | ForEach-Object { (T "{0}（{1}）") -f $_.Path, (Fmt (Get-MarkBytes $_)) })
    if ($script:mapMarks.Count -gt 60) { $items += ((T "……另有 {0} 项") -f ($script:mapMarks.Count - 60)) }
    $ans = Show-Sheet -Title ((T "待删清单（{0} 项）") -f $script:mapMarks.Count) -Text ($ctl.MapMarkText.Text + "`n`n" + (T '要去掉某一项：在列表里选中它，右键「从待删清单去掉」。')) -Items $items -Buttons @((T '关闭清单'), (T '清空清单'), (T '删除清单里的…')) -Primary (T '关闭清单') -Cancel (T '关闭清单')
    if ($ans -eq (T '清空清单')) { Clear-MapMarks } elseif ($ans -eq (T '删除清单里的…')) { Start-MapDelete @($script:mapMarks.Values) }
}
$ctl.BtnMarkShow.Add_Click({ Show-MapMarks })
$ctl.BtnMarkClear.Add_Click({ Clear-MapMarks })
$ctl.BtnMarkDelete.Add_Click({ if ($script:mapMarks.Count -gt 0) { Start-MapDelete @($script:mapMarks.Values) } })
$ctl.BtnMapMark.Add_Click({ $sel = @($ctl.MapList.SelectedItems); if (@($sel | Where-Object { -not $_.Marked }).Count -eq 0) { Remove-MapMarks $sel } else { [void](Add-MapMarks $sel) }; Update-MapSel })
$ctl.MmMark.Add_Click({ $rows = @($script:menuRows); if (@($rows | Where-Object { -not $_.Marked }).Count -eq 0) { Remove-MapMarks $rows } else { [void](Add-MapMarks $rows) }; Update-MapSel })
# ---------- 值得一看：名字一看就是缓存、依赖包、构建产物、虚拟环境、临时文件的大文件夹 ----------
$script:worthNames = @('node_modules', '.next', '.nuxt', '.parcel-cache', '.turbo', '.cache', 'cache', 'caches', 'cache2', 'Code Cache', 'GPUCache', 'ShaderCache', 'DXCache', 'GLCache',
    '_cacache', 'npm-cache', '.gradle', '.nuget', '.m2', '.venv', 'venv', 'target', 'obj', '__pycache__', 'Temp', 'tmp', 'CrashDumps', 'DerivedData', '.android', 'Windows.old')
function Get-WorthKind([string]$name) {
    switch -regex ($name) {
        '^(node_modules|\.nuget|\.m2|_cacache|npm-cache|\.gradle)$' { return (T '依赖包，要用时会重新下载') }
        '^(target|obj|\.next|\.nuxt|\.parcel-cache|\.turbo|DerivedData|__pycache__)$' { return (T '构建产物，重新编译会再生成') }
        '^(\.venv|venv)$' { return (T 'Python 虚拟环境，删了要重新建') }
        '^(Temp|tmp|CrashDumps)$' { return (T '临时文件和崩溃转储') }
        '^Windows\.old$' { return (T '旧系统，删了就不能退回去') }
        '^\.android$' { return (T '安卓开发工具的数据') }
        default { return (T '缓存，删了会自动重建') }
    }
}
function Show-MapWorth {
    $ctl.MapWorth.Children.Clear()
    $r = $script:mapRoot
    if (-not $r) { $ctl.MapWorthBox.Visibility = 'Collapsed'; return }
    $hits = @(); try { $hits = @([DiskMap]::Named($r, [string[]]$script:worthNames, [long]300MB, 40)) } catch {}
    $shown = 0
    foreach ($h in $hits) {
        if ($shown -ge 6) { break }
        $p = $h.FullPath()
        if (Get-DeleteBlock $p) { continue }
        if (Test-ChatPath $p) { continue }
        $par = Split-Path $p -Parent
        # target 要旁边有 Cargo.toml（Rust），obj 要旁边有工程文件（.NET）才算构建产物
        if ($h.Name -ieq 'target' -and -not (Test-Path -LiteralPath (Join-Path $par 'Cargo.toml'))) { continue }
        if ($h.Name -ieq 'obj' -and -not @(Get-ChildItem -LiteralPath $par -File -Filter '*.*proj' -ErrorAction SilentlyContinue).Count) { continue }
        $b = New-Object System.Windows.Controls.Button; $b.Style = $win.FindResource('Small'); $b.Margin = New-Object System.Windows.Thickness 0, 0, 8, 6; $b.Tag = $h
        $sp = New-Object System.Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'
        $t1 = New-Object System.Windows.Controls.TextBlock; $t1.Text = (Split-Path $par -Leaf) + '\' + $h.Name
        $t2 = New-Object System.Windows.Controls.TextBlock; $t2.Text = Fmt $(if ($r.HasDisk) { [double]$h.Disk } else { [double]$h.Size }); $t2.FontWeight = 'SemiBold'; $t2.Margin = New-Object System.Windows.Thickness 8, 0, 0, 0
        [void]$sp.Children.Add($t1); [void]$sp.Children.Add($t2); $b.Content = $sp
        $b.ToolTip = "{0}`n{1}" -f $p, (Get-WorthKind $h.Name)
        $b.Add_Click({
            $n = $this.Tag
            if ($script:mapView -ne 'dirs' -and $script:mapView -ne 'tree') { $ctl.MapViewDirs.IsChecked = $true }
            Show-MapLevel $n.Parent
            foreach ($x in @($ctl.MapList.Items)) { if ([object]::ReferenceEquals($x.Node, $n)) { $ctl.MapList.SelectedItem = $x; try { $ctl.MapList.ScrollIntoView($x) } catch {}; break } }
        })
        [void]$ctl.MapWorth.Children.Add($b); $shown++
    }
    $ctl.MapWorthBox.Visibility = if ($shown -gt 0) { 'Visible' } else { 'Collapsed' }
}
# 概览：这块盘用了多少，系统与软件、个人文件、缓存各占多少。只有扫的是整块盘时才有
$script:ovCache = @{}
function Show-MapOverview {
    $r = $script:mapRoot
    if (-not $r -or ($script:mapView -ne 'dirs' -and $script:mapView -ne 'tree' -and $script:mapView -ne 'types')) { $ctl.MapOverview.Visibility = 'Collapsed'; return }
    $drive = $r.FullPath()
    if ($drive.Length -ne 3 -or $drive[1] -ne ':') { $ctl.MapOverview.Visibility = 'Collapsed'; return }
    $u = Get-DriveUse $drive
    $total = $u.Total; $used = $u.Used; $free = $u.Free
    if ($total -le 0) { $ctl.MapOverview.Visibility = 'Collapsed'; return }
    $sz = { param($n) if ($n) { if ($r.HasDisk) { [double]$n.Disk } else { [double]$n.Size } } else { [double]0 } }
    $sys = [double]0
    foreach ($nm in 'Windows', 'Program Files', 'Program Files (x86)', 'ProgramData', 'Recovery', '$WinREAgent', 'Windows.old', 'PerfLogs') { $sys += & $sz ([DiskMap]::Find($r, (Join-Path $drive $nm))) }
    $users = & $sz ([DiskMap]::Find($r, (Join-Path $drive 'Users')))
    # 缓存：清理列表里「安全清理」那些目录在这棵树上的大小（只算系统盘；别的盘没有这些）
    $cache = [double]0
    $key = $drive.ToLowerInvariant() + '|' + $(if ($script:mapScanAt) { $script:mapScanAt.Ticks } else { 0 })
    if ($drive -ieq ($env:SystemDrive + '\')) {
        if ($script:ovCache.ContainsKey($key)) { $cache = $script:ovCache[$key] }
        else {
            foreach ($it in $catalog) {
                if ($it.Kind -ne 'cache' -or $it.Size -or $it.Custom -or -not $it.Paths -or ([string]$it.G) -ne $script:safeGroup) { continue }
                try { $cache += [double](Measure-Item $it $r) } catch {}
            }
            $script:ovCache[$key] = $cache
        }
    }
    $other = [math]::Max([double]0, $used - $sys - $users)
    $sys = [math]::Max([double]0, $sys - $cache * 0.3); $users = [math]::Max([double]0, $users - $cache * 0.7)   # 缓存大多在个人目录（AppData），少数在 Windows 和 ProgramData 里
    # 几类加起来不能比这块盘的已用空间还多：系统文件夹里的硬链接（WinSxS 等）在几个文件夹里各算一次，按比例缩回到已用空间
    $sum = $sys + $users + $cache + $other
    if ($sum -gt $used -and $sum -gt 0) { $f = $used / $sum; $sys *= $f; $users *= $f; $cache *= $f; $other *= $f }
    # 卡片不显示这块盘时才用得上的总量那一行
    $ctl.MapOvTitle.Text = ((T "{0} {1}") -f $drive.TrimEnd('\'), $(if ($drive -ieq ($env:SystemDrive + '\')) { (T '系统盘') } else { '' })) + '  ·  ' + ((T "剩 {0}") -f (Fmt $free))
    $ctl.MapOvUsed.Text = "{0} / {1}" -f (Fmt $used), (Fmt $total)
    $ctl.MapOvPct.Text = "{0:N0}%" -f $u.Pct
    Update-MapOvHead
    $parts = @(@((T '系统与软件'), $sys, '#3B82F6'), @((T '个人文件'), $users, '#E0A731'), @((T '可清理的缓存'), $cache, '#3FA37E'), @((T '其他'), $other, '#8E8E93'))
    for ($i = 0; $i -lt 4; $i++) { $ctl.MapOvBar.ColumnDefinitions[$i].Width = New-Object System.Windows.GridLength ([math]::Max([double]0, $parts[$i][1])), ([System.Windows.GridUnitType]::Star) }
    # 条的两头是圆的：圆角给有内容的第一段和最后一段，段与段之间留 1 像素的缝
    $on = @(for ($i = 0; $i -lt 4; $i++) { if ($parts[$i][1] -gt 0) { $i } })
    for ($i = 0; $i -lt 4; $i++) {
        $b = $ctl.MapOvBar.Children[$i]
        $first = ($on.Count -gt 0 -and $i -eq $on[0]); $last = ($on.Count -gt 0 -and $i -eq $on[-1])
        $b.CornerRadius = New-Object System.Windows.CornerRadius $(if ($first) { 5 } else { 0 }), $(if ($last) { 5 } else { 0 }), $(if ($last) { 5 } else { 0 }), $(if ($first) { 5 } else { 0 })
        $b.Margin = New-Object System.Windows.Thickness 0, 0, $(if ($last) { 0 } else { 1 }), 0
    }
    $ctl.MapOvLegend.Children.Clear()
    foreach ($p in $parts) {
        if ($p[1] -le 0) { continue }
        $sp = New-Object System.Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'; $sp.Margin = New-Object System.Windows.Thickness 0, 0, 22, 4
        $dot = New-Object System.Windows.Controls.Border; $dot.Width = 9; $dot.Height = 9; $dot.CornerRadius = New-Object System.Windows.CornerRadius 4.5; $dot.Background = Brush $p[2] 'b'; $dot.VerticalAlignment = 'Center'; $dot.Margin = New-Object System.Windows.Thickness 0, 0, 7, 0
        # 名称灰色，大小深色加粗：一眼看到数
        $tb = New-Object System.Windows.Controls.TextBlock; $tb.FontSize = 12; $tb.VerticalAlignment = 'Center'
        $r1 = New-Object System.Windows.Documents.Run ([string]$p[0]); $r1.Foreground = Brush '#6E6E73'
        $r2 = New-Object System.Windows.Documents.Run ('  ' + (Fmt $p[1])); $r2.Foreground = Brush '#1D1D1F'; $r2.FontWeight = 'SemiBold'
        [void]$tb.Inlines.Add($r1); [void]$tb.Inlines.Add($r2)
        [void]$sp.Children.Add($dot); [void]$sp.Children.Add($tb); [void]$ctl.MapOvLegend.Children.Add($sp)
    }
    $ctl.MapOverview.ToolTip = (T '按文件夹估算。系统与软件：Windows、Program Files、ProgramData 等；个人文件：Users；可清理的缓存：清理页「安全清理」里的那些目录；其他：页面文件、休眠文件、文件表等不在上面几类里的。几类加起来按这块盘的已用空间算：硬链接在几个文件夹里各算一次的，按比例缩回。')
    if ($script:worthKey -ne $key) { $script:worthKey = $key; Show-MapWorth }
    $ctl.MapOverview.Visibility = 'Visible'
}

# ---------- 方块图：每个方块的面积就是它占的空间（squarified treemap） ----------
# 输入从大到小排好的大小，返回每一项的 @(x, y, 宽, 高)
function Get-TreeRects([double[]]$sizes, [double]$x, [double]$y, [double]$w, [double]$h) {
    $n = $sizes.Count
    $rects = New-Object 'object[]' $n
    $total = [double]0; foreach ($s in $sizes) { $total += $s }
    if ($n -eq 0 -or $total -le 0 -or $w -le 0 -or $h -le 0) { return ,$rects }
    $scale = $w * $h / $total
    $areas = New-Object 'double[]' $n
    for ($k = 0; $k -lt $n; $k++) { $areas[$k] = [math]::Max([double]0.0001, $sizes[$k] * $scale) }
    $i = 0
    while ($i -lt $n -and $w -gt 0.5 -and $h -gt 0.5) {
        $side = [math]::Min($w, $h)
        $j = $i; $sum = [double]0; $worst = [double]::MaxValue
        while ($j -lt $n) {
            $s2 = $sum + $areas[$j]
            $wst = [math]::Max(($side * $side * $areas[$i]) / ($s2 * $s2), ($s2 * $s2) / ($side * $side * $areas[$j]))
            if ($j -gt $i -and $wst -gt $worst) { break }
            $worst = $wst; $sum = $s2; $j++
        }
        if ($w -ge $h) {
            $cw = $sum / $h; $yy = $y
            for ($k = $i; $k -lt $j; $k++) { $hh = $areas[$k] / $cw; $rects[$k] = @($x, $yy, $cw, $hh); $yy += $hh }
            $x += $cw; $w -= $cw
        } else {
            $rh = $sum / $w; $xx = $x
            for ($k = $i; $k -lt $j; $k++) { $ww = $areas[$k] / $rh; $rects[$k] = @($xx, $y, $ww, $rh); $xx += $ww }
            $y += $rh; $h -= $rh
        }
        $i = $j
    }
    return ,$rects
}
# 这一层要画的方块：最多 60 块，太小的合成一块「其他」
function Get-TreeItems($rows) {
    $items = @($rows | Where-Object { $_ -and $_.Size -gt 0 })
    $tot = [double]0; foreach ($r in $items) { $tot += [double]$r.Size }
    $show = New-Object System.Collections.ArrayList; $rest = [double]0; $restN = 0
    foreach ($r in $items) { if ($show.Count -lt 60 -and $tot -gt 0 -and ([double]$r.Size / $tot) -ge 0.002) { [void]$show.Add($r) } else { $rest += [double]$r.Size; $restN++ } }
    $sizes = @($show | ForEach-Object { [double]$_.Size }); if ($rest -gt 0) { $sizes += $rest }
    return @{ Show = $show; Sizes = [double[]]$sizes; Rest = $rest; RestN = $restN }
}
$script:treeColors = @('#2F6FDB', '#3B82F6', '#4C8DF6', '#2563EB', '#5A9BF0', '#3576E6')
# 方块的颜色是这个文件夹装的是哪一类东西（参考 disktree）：按名字认，认不出的用蓝色；能腾出来的（缓存、依赖包、临时文件）再加斜线
$script:treeKinds = [ordered]@{
    system = @((T '系统'), '#5A6B8C'); apps = @((T '软件和软件数据'), '#4F7FC4'); docs = @((T '文档和桌面'), '#8C6BC2'); media = @((T '照片、视频、音乐'), '#C07A3A')
    dev = @((T '代码和开发'), '#3E8E7E'); sync = @((T '同步盘'), '#3796C7'); games = @((T '游戏'), '#B05A8A'); cache = @((T '缓存和临时文件'), '#C9A227'); other = @((T '其他文件夹'), '#3B82F6'); file = @((T '文件'), '#8E99AD')
}
function Get-TreeKind($row) {
    if (-not $row.IsDir) { return 'file' }
    $n = ([string]$row.Name).ToLowerInvariant(); $p = ([string]$row.Path).ToLowerInvariant()
    if ($n -match '^(windows|program files|program files \(x86\)|programdata|\$winreagent|recovery|system volume information|perflogs|windows\.old|\$recycle\.bin|msocache|intel|amd|nvidia)$') { return $(if ($n -in 'windows.old', '$recycle.bin') { 'cache' } else { 'system' }) }
    if ($script:worthNames -contains $row.Name -or $n -match '^(temp|tmp|inetcache|crashdumps|logs?|\$recycle\.bin)$' -or $n -match 'cache') { return 'cache' }
    if ($n -match '^(onedrive|onedrive - .*|dropbox|icloud ?drive|google drive|baidunetdisk.*|baidunetdiskdownload|坚果云|nutstore.*)$') { return 'sync' }
    if ($n -match '^(steam|steamapps|steamlibrary|epic games|wegame|games|riot games|battle\.net|origin games|ea games|ubisoft.*|genshin impact.*|xboxgames)$') { return 'games' }
    if ($n -match '^(pictures|videos|music|photos|camera roll|dcim|movies|图片|视频|音乐|照片)$') { return 'media' }
    if ($n -match '^(documents|desktop|downloads|文档|桌面|下载)$') { return 'docs' }
    if ($n -match '^(\.git|src|source|sources|repos|projects|code|workspace|workspaces|github|gitlab|dev|\.vscode|\.cargo|\.rustup|\.conda|anaconda3|miniconda3|\.docker|docker)$') { return 'dev' }
    if ($n -eq 'appdata' -or $p -match '\\appdata(\\|$)' -or $n -match '^(local|roaming|locallow)$') { return 'apps' }
    return 'other'
}
$script:hatchCache = @{}
function Get-TreeBrush([string]$hex, [bool]$hatch) {
    $key = $hex + '|' + $hatch
    if ($script:hatchCache.ContainsKey($key)) { return $script:hatchCache[$key] }
    $base = Brush $hex 'b'
    if (-not $hatch) { $script:hatchCache[$key] = $base; return $base }
    $dg = New-Object System.Windows.Media.DrawingGroup
    [void]$dg.Children.Add((New-Object System.Windows.Media.GeometryDrawing $base, $null, (New-Object System.Windows.Media.RectangleGeometry (New-Object System.Windows.Rect 0, 0, 8, 8))))
    $pen = New-Object System.Windows.Media.Pen ((New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.Color]::FromArgb(90, 255, 255, 255)))), 1.6
    foreach ($ln in @(@(0, 8, 8, 0), @(-2, 2, 2, -2), @(6, 10, 10, 6))) { [void]$dg.Children.Add((New-Object System.Windows.Media.GeometryDrawing $null, $pen, (New-Object System.Windows.Media.LineGeometry (New-Object System.Windows.Point $ln[0], $ln[1]), (New-Object System.Windows.Point $ln[2], $ln[3])))) }
    $db = New-Object System.Windows.Media.DrawingBrush $dg
    $db.TileMode = 'Tile'; $db.Viewport = New-Object System.Windows.Rect 0, 0, 8, 8; $db.ViewportUnits = 'Absolute'; $db.Viewbox = New-Object System.Windows.Rect 0, 0, 8, 8; $db.ViewboxUnits = 'Absolute'
    $db.Freeze()
    $script:hatchCache[$key] = $db
    return $db
}
$script:treeSel = $null
function Draw-MapTree {
    $cv = $ctl.MapTree
    $cv.Children.Clear(); $script:treeSel = $null
    $w = [double]$cv.ActualWidth; $h = [double]$cv.ActualHeight
    if ($w -lt 40 -or $h -lt 40) { return }   # 还没排好版：等 SizeChanged 再画
    $ti = Get-TreeItems @($ctl.MapList.ItemsSource)
    if ($ti.Sizes.Count -eq 0) { return }
    $order = @(0..($ti.Sizes.Count - 1) | Sort-Object { $ti.Sizes[$_] } -Descending)
    $rects = Get-TreeRects ([double[]]@($order | ForEach-Object { $ti.Sizes[$_] })) 0 0 $w $h
    $clear = Brush '#00000000'
    $kindsUsed = @{}
    for ($q = 0; $q -lt $order.Count; $q++) {
        $i = $order[$q]
        $rc = $rects[$q]; if (-not $rc) { continue }
        $row = if ($i -lt $ti.Show.Count) { $ti.Show[$i] } else { $null }
        $b = New-Object System.Windows.Controls.Border
        $b.Width = [math]::Max([double]0, $rc[2] - 2); $b.Height = [math]::Max([double]0, $rc[3] - 2)
        [System.Windows.Controls.Canvas]::SetLeft($b, $rc[0] + 1); [System.Windows.Controls.Canvas]::SetTop($b, $rc[1] + 1)
        $b.CornerRadius = New-Object System.Windows.CornerRadius 3
        $b.BorderThickness = New-Object System.Windows.Thickness 2
        $b.BorderBrush = $clear
        if (-not $row) { $b.Background = Brush '#C7CCD6' 'b' }
        else {
            $kd = Get-TreeKind $row; $kindsUsed[$kd] = $true
            $hex = if ($kd -eq 'other') { $script:treeColors[$i % $script:treeColors.Count] } else { $script:treeKinds[$kd][1] }
            $b.Background = Get-TreeBrush $hex ($kd -eq 'cache')
        }
        $b.Tag = $row
        $b.ToolTip = if ($row) { "{0}`n{1}  ·  {2}`n{3}" -f $row.Name, $row.SizeText, $row.Pct, $row.Path } else { (T "其他 {0} 项，共 {1}") -f $ti.RestN, (Fmt $ti.Rest) }
        if ($b.Width -ge 46 -and $b.Height -ge 20) {
            $tb = New-Object System.Windows.Controls.TextBlock
            $tb.Margin = New-Object System.Windows.Thickness 6, 3, 6, 2
            $tb.Foreground = Brush '#FFFFFF'; $tb.FontSize = 12; $tb.TextTrimming = 'CharacterEllipsis'
            $nm = New-Object System.Windows.Documents.Run $(if ($row) { $row.Name } else { (T "其他 {0} 项") -f $ti.RestN })
            $nm.FontWeight = 'SemiBold'; [void]$tb.Inlines.Add($nm)
            if ($b.Height -ge 38) {
                [void]$tb.Inlines.Add((New-Object System.Windows.Documents.LineBreak))
                $sz = New-Object System.Windows.Documents.Run $(if ($row) { $row.SizeText } else { Fmt $ti.Rest })
                $sz.FontSize = 12; [void]$tb.Inlines.Add($sz)
            }
            $b.Child = $tb
        }
        if ($row) {
            $b.Cursor = [System.Windows.Input.Cursors]::Hand
            $b.Add_MouseEnter({ param($s, $e) $s.Opacity = 0.82 })
            $b.Add_MouseLeave({ param($s, $e) $s.Opacity = 1 })
            $b.Add_MouseLeftButtonDown({
                param($s, $e)
                $r = $s.Tag
                if ($e.ClickCount -ge 2) { if ($r.IsDir -and $r.Node) { Show-MapLevel $r.Node }; $e.Handled = $true; return }
                # 点方块 = 在下面的列表里选中这一行（按住 Ctrl 可以多选），列表滚到它那里；列表选中的变化再把方块描上边
                $ctrl = ([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control) -ne 0
                if ($ctrl) { if ($ctl.MapList.SelectedItems.Contains($r)) { $ctl.MapList.SelectedItems.Remove($r) } else { [void]$ctl.MapList.SelectedItems.Add($r) } }
                elseif (Test-CheckMode) { $script:treeFocus = $r; Sync-TreeSel }
                else { $ctl.MapList.SelectedItems.Clear(); $ctl.MapList.SelectedItem = $r }
                try { $ctl.MapList.ScrollIntoView($r) } catch {}
                $e.Handled = $true
            })
        }
        [void]$cv.Children.Add($b)
    }
    # 图例：这一层出现了哪几类
    $lg = $ctl.MapTreeLegend; $lg.Children.Clear()
    foreach ($k in $script:treeKinds.Keys) {
        if (-not $kindsUsed.ContainsKey($k)) { continue }
        $sp = New-Object System.Windows.Controls.StackPanel; $sp.Orientation = 'Horizontal'; $sp.Margin = New-Object System.Windows.Thickness 0, 2, 16, 2
        $sw = New-Object System.Windows.Controls.Border; $sw.Width = 12; $sw.Height = 12; $sw.CornerRadius = New-Object System.Windows.CornerRadius 3; $sw.Margin = New-Object System.Windows.Thickness 0, 0, 6, 0; $sw.VerticalAlignment = 'Center'
        $sw.Background = Get-TreeBrush $script:treeKinds[$k][1] ($k -eq 'cache')
        $tb = New-Object System.Windows.Controls.TextBlock; $tb.Text = $script:treeKinds[$k][0] + $(if ($k -eq 'cache') { (T '（带斜线：删了能腾出来）') } else { '' }); $tb.FontSize = 12; $tb.Foreground = Brush '#6E6E73'; $tb.VerticalAlignment = 'Center'
        [void]$sp.Children.Add($sw); [void]$sp.Children.Add($tb); [void]$lg.Children.Add($sp)
    }
    Sync-TreeSel
}
# 列表里选中了哪些，方块图上就给哪些描边（方块图和列表一起显示时两边联动）
function Sync-TreeSel {
    if ($script:mapView -ne 'tree') { return }
    $sel = @{}; foreach ($x in @($ctl.MapList.SelectedItems)) { $sel[[System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($x)] = $true }
    $on = Brush '#1D1D1F' 'd'; $off = Brush '#00000000'; $fo = Brush '#0071E3' 'd'
    foreach ($b in @($ctl.MapTree.Children)) {
        $r = $b.Tag
        $b.BorderBrush = if ($r -and $sel.ContainsKey([System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($r))) { $on } elseif ($r -and [object]::ReferenceEquals($r, $script:treeFocus)) { $fo } else { $off }
    }
}
$ctl.MapTree.Add_SizeChanged({ if ($script:mapView -eq 'tree') { Draw-MapTree } })
$ctl.MapList.Add_SelectionChanged({ if (-not $script:bulkSel) { Sync-TreeSel } })
# 找文件：在扫描时记下的 1 MB 以上的文件里，按大小、多久没改过、类型、名称、所在文件夹筛选
$script:mapTypes = @{
    video   = '.mp4 .mkv .avi .mov .wmv .flv .m4v .ts .m2ts .webm .mpg .mpeg .rmvb .rm .3gp .vob'
    archive = '.zip .rar .7z .tar .gz .tgz .bz2 .xz .zst .cab .msi .msp .msix .msixbundle .appx .appxbundle .apk .dmg'
    image   = '.iso .img .vhd .vhdx .avhdx .vmdk .vdi .qcow2 .wim .esd .gho'
    picture = '.jpg .jpeg .png .gif .bmp .tif .tiff .heic .webp .raw .cr2 .cr3 .nef .arw .dng .psd'
    music   = '.mp3 .flac .wav .aac .m4a .ogg .wma .ape .opus'
    doc     = '.pdf .doc .docx .xls .xlsx .ppt .pptx .txt .md .epub .mobi .csv .wps .et .dps'
    program = '.exe .dll .sys .ocx .pak .bin .vpk .pck .assets .bundle'
    log     = '.log .etl .dmp .mdmp .hdmp .tmp .temp .bak .old .cache .chk'
    code    = '.cs .js .ts .tsx .jsx .py .java .h .hpp .c .cpp .cc .go .rs .rb .php .json .xml .yml .yaml .map .obj .pdb .lib .o .class .pyc .ipynb .sql .ps1 .psm1 .sh .bat .cmd .swift .kt .scala .lock .toml'
}
$script:mapFindMax = 1000
# 各类文件的名字（和 FileCats 的顺序一样）
$script:catNames = @((T '其他类型'), (T '视频'), (T '图片'), (T '音乐'), (T '文档'), (T '压缩包和安装包'), (T '光盘映像和虚拟磁盘'), (T '程序和游戏数据'), (T '日志、转储和临时文件'), (T '代码和开发文件'))
$script:catKeys = @('', 'video', 'picture', 'music', 'doc', 'archive', 'image', 'program', 'log', 'code')
function Get-MapFilter {
    $min = [double]50MB; $t = $ctl.MapMinSize.SelectedItem; if ($t) { $min = [double]([string]$t.Tag) * 1MB }
    $days = 0; $t = $ctl.MapAge.SelectedItem; if ($t) { $days = [int]([string]$t.Tag) }
    $type = ''; $t = $ctl.MapType.SelectedItem; if ($t) { $type = [string]$t.Tag }
    $under = $null
    if ($ctl.MapUnder.IsChecked -and $script:mapCur -and -not [object]::ReferenceEquals($script:mapCur, $script:mapRoot)) { $under = $script:mapCur }
    $chat = $null
    if ($ctl.MapChat.IsChecked) { $chat = Get-MapChatNodes }
    return @{
        Chat = $chat
        Min = [long]$min
        Before = $(if ($days -gt 0) { (Get-Date).AddDays(-$days) } else { [DateTime]::MaxValue })
        Exts = $(if ($type -and $script:mapTypes.ContainsKey($type)) { $script:mapTypes[$type] } else { '' })
        Name = ([string]$ctl.MapName.Text).Trim()
        Under = $under
    }
}
# 聊天软件的聊天记录文件夹在这棵树上的位置（搬走了的是链接，里面没有东西）
function Get-MapChatNodes {
    $out = @{ Nodes = New-Object System.Collections.Generic.List[DmNode]; Names = New-Object System.Collections.Generic.List[string] }
    if (-not $script:mapRoot) { return $out }
    foreach ($c in $catalog) {
        if ($c.Tier -ne 'chat' -or -not $c.Paths) { continue }
        $hit = $false
        foreach ($p in $c.Paths) {
            if (-not $p) { continue }
            foreach ($it in @(Get-PathItems $p)) {
                if (-not $it.PSIsContainer) { continue }
                $n = [DiskMap]::Find($script:mapRoot, $it.FullName)
                if ($n -and -not $n.IsLink -and -not $out.Nodes.Contains($n)) { $out.Nodes.Add($n); $hit = $true }
            }
        }
        if ($hit) { $out.Names.Add([string]$c.N) }
    }
    return $out
}
function Show-MapFiles {
    $keep = Get-MapKeep 'files'
    $rows = New-Object System.Collections.Generic.List[MapRow]
    $f = Get-MapFilter
    if ($f.Chat) { $res = [DiskMap]::FindFilesIn($f.Min, $f.Before, $f.Exts, $f.Name, $f.Chat.Nodes.ToArray(), $script:mapFindMax) }
    else { $res = [DiskMap]::FindFiles($f.Min, $f.Before, $f.Exts, $f.Name, $f.Under, $script:mapFindMax) }
    $max = if ($res.Files.Count -gt 0) { [double]$res.Files[0].Size } else { 0 }
    $tot = if ($script:mapRoot) { [double]$script:mapRoot.Size } else { 0 }
    $dn = (Get-Flag 'MapDisk') -and $script:mapRoot -and $script:mapRoot.HasDisk
    # 所有者：只给列出来的这些文件查（每个账户只翻译一次，一千个文件不到一秒）
    $wantOwner = ''; $t = $ctl.MapOwner.SelectedItem; if ($t) { $wantOwner = [string]$t.Tag }
    $owners = @{}
    $files = @($res.Files)
    $sortBy = ''; $t = $ctl.MapSort.SelectedItem; if ($t) { $sortBy = [string]$t.Tag }
    if ($sortBy -eq 'new') { $files = @($files | Sort-Object { $_.Modified } -Descending) } elseif ($sortBy -eq 'old') { $files = @($files | Sort-Object { $_.Modified }) }
    foreach ($x in $files) {
        $p = $x.Path
        $ow = [FsTools]::Owner($p)
        if ($ow) { $owners[$ow] = $true }
        if ($wantOwner -and $ow -ne $wantOwner) { continue }
        $fm = (T "{0} · 修改于 {1:yyyy-MM-dd}") -f (Split-Path $p -Parent), $x.Modified
        if ($dn) { $fm += Get-SizeNote $p ([double]$x.Size) ([double]$x.Disk) $(if ($x.Shared) { [double]$x.Size } else { 0 }) }
        if ($ow) { $fm += (T " · 所有者 {0}") -f ($ow -replace '^.*\\', '') }
        $row = New-MapRow $x.Name $p $x.Size $max $tot $false $null $fm 'file'
        $row.When = '{0:yyyy-MM-dd HH:mm}' -f $x.Modified
        $row.Disk = [long]$x.Disk; $row.Shared = [bool]$x.Shared; $row.Owner = $ow
        # 聊天记录里的文件只看不删：要腾地方就整体搬家
        if ($f.Chat) { $row.Locked = $true; $row.LockTip = (T '聊天记录里的文件只能查看和打开位置；要腾地方，到「搬家管理」把整个聊天记录搬到其他盘') }
        [void]$rows.Add($row)
    }
    # 所有者下拉框：列出来的文件里有哪些账户
    $script:ownerFill = $true
    try {
        $cur = $wantOwner
        while ($ctl.MapOwner.Items.Count -gt 1) { $ctl.MapOwner.Items.RemoveAt(1) }
        foreach ($o in @($owners.Keys | Sort-Object)) { $it = New-Object System.Windows.Controls.ComboBoxItem; $it.Content = $o; $it.Tag = $o; [void]$ctl.MapOwner.Items.Add($it); if ($o -eq $cur) { $ctl.MapOwner.SelectedItem = $it } }
        if (-not $ctl.MapOwner.SelectedItem) { $ctl.MapOwner.SelectedIndex = 0 }
    } finally { $script:ownerFill = $false }
    $ctl.MapList.ItemsSource = $rows
    Restore-MapKeep $keep
    $head = (T "找到 {0:N0} 个文件，共 {1}") -f $res.Count, (Fmt $res.Bytes)
    if ($res.Count -gt $rows.Count) { $head += ((T "，下面列出最大的 {0:N0} 个") -f $rows.Count) }
    $ctl.MapPath.Text = $head
    $where = if ($f.Under) { $f.Under.FullPath() } elseif ($script:mapRoot) { $script:mapRoot.FullPath() } else { '' }
    $ctl.MapInfo.Text = (T "在 {0} 里找，只能找到扫描时记下的 1 MB 以上的文件") -f $where
    if ($wantOwner) { $ctl.MapInfo.Text += (T "；所有者只在列出来的这些文件里分") }
    if ($f.Chat) {
        $ctl.MapInfo.Text = if ($f.Chat.Names.Count -gt 0) { (T "在聊天记录里找（{0}）。这些文件只能查看和打开位置；要腾地方，可以到「搬家管理」把整个聊天记录搬到其他盘") -f ($f.Chat.Names -join (T '、')) }
                            else { (T '这块盘上没找到聊天软件的聊天记录文件夹（可能已经搬到其他盘了）') }
    }
    $ctl.MapUnder.ToolTip = if ($script:mapCur) { $script:mapCur.FullPath() } else { $null }
    $ctl.BtnMapUp.IsEnabled = $false
    $ctl.BtnMapAcct.Visibility = 'Collapsed'
    $ctl.EmptyMap.Visibility = if ($rows.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($rows.Count -eq 0) { $ctl.EmptyMapText.Text = (T '没有符合条件的文件，可以把条件放宽一些') }
    $ctl.BtnMapExport.IsEnabled = ($rows.Count -gt 0)
    $ctl.BtnMapReport.IsEnabled = $true
    Update-MapSel
}
function Refresh-MapFiles { if ($script:mapView -eq 'files' -and $script:mapRoot) { Show-MapFiles } }
$ctl.MapMinSize.Add_SelectionChanged({ Refresh-MapFiles })
$ctl.MapAge.Add_SelectionChanged({ Refresh-MapFiles })
$ctl.MapType.Add_SelectionChanged({ Refresh-MapFiles })
$ctl.MapSort.Add_SelectionChanged({ if ($script:sortCfg['MapList'] -and $script:sortCfg['MapList'].Prop) { Reset-ListSort 'MapList' '' $true }; Refresh-MapFiles })
$ctl.MapOwner.Add_SelectionChanged({ if (-not $script:ownerFill) { Refresh-MapFiles } })
$ctl.MapUnder.Add_Checked({ $ctl.MapChat.IsChecked = $false; Refresh-MapFiles })
$ctl.MapUnder.Add_Unchecked({ Refresh-MapFiles })
$ctl.MapChat.Add_Checked({ $ctl.MapUnder.IsChecked = $false; if ($script:mapView -ne 'files' -and $script:mapRoot) { $ctl.MapViewFiles.IsChecked = $true }; Refresh-MapFiles })
$ctl.MapChat.Add_Unchecked({ Refresh-MapFiles })
# 快速扫描（直接读文件表）开关：存在设置里，所有页面统计大小时都按它来
$ctl.MapFast.IsChecked = ((Get-Setting 'FastScan' '1') -ne '0')
[DiskMap]::MftOff = -not $ctl.MapFast.IsChecked
function Set-FastScan([bool]$on) {
    $ctl.MapFast.IsChecked = $on; $ctl.SetFast.IsChecked = $on
    [DiskMap]::MftOff = -not $on
    Set-Setting 'FastScan' $(if ($on) { '1' } else { '0' })
    UI-Log $(if ($on) { (T '已打开快速扫描：直接读文件表') } else { (T '已关闭快速扫描：以后逐个文件夹扫描') })
}
$ctl.MapFast.Add_Click({ Set-FastScan ([bool]$ctl.MapFast.IsChecked) })
# 名称：停下打字 0.4 秒后再找，免得每打一个字就刷新一次
$script:mapNameTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:mapNameTimer.Interval = [TimeSpan]::FromMilliseconds(400)
$script:mapNameTimer.Add_Tick({ $script:mapNameTimer.Stop(); Refresh-MapFiles })
$ctl.MapName.Add_TextChanged({ $script:mapNameTimer.Stop(); $script:mapNameTimer.Start() })

function Set-MapView([string]$v) {
    $script:mapView = $v
    $ctl.MapFilter.Visibility = if ($v -eq 'files') { 'Visible' } else { 'Collapsed' }
    $grow = ($v -eq 'grow'); $tree = ($v -eq 'tree')
    $ctl.MapGrowBar.Visibility = if ($grow) { 'Visible' } else { 'Collapsed' }
    $ctl.MapRecentBar.Visibility = if ($v -eq 'recent') { 'Visible' } else { 'Collapsed' }
    $ctl.MapGrow.Visibility = if ($grow) { 'Visible' } else { 'Collapsed' }
    $ctl.MapTreeBox.Visibility = if ($tree) { 'Visible' } else { 'Collapsed' }
    if ($v -ne 'dirs' -and -not $tree) { $ctl.MapCrumbs.Visibility = 'Collapsed'; $ctl.MapPath.Visibility = 'Visible' }
    # 方块图和列表一起显示：上面方块图，下面列表，点哪边另一边都跟着
    $ctl.MapGrid.RowDefinitions[1].Height = if ($tree) { New-Object System.Windows.GridLength 3, ([System.Windows.GridUnitType]::Star) } else { New-Object System.Windows.GridLength 0 }
    $ctl.MapGrid.RowDefinitions[2].Height = if ($tree) { New-Object System.Windows.GridLength 2, ([System.Windows.GridUnitType]::Star) } else { New-Object System.Windows.GridLength 1, ([System.Windows.GridUnitType]::Star) }
    $ctl.MapList.Visibility = if ($grow) { 'Collapsed' } else { 'Visible' }
    Update-HeadVis
    if (-not $script:mapRoot) { $ctl.MapOverview.Visibility = 'Collapsed'; return }
    if ($v -eq 'dirs' -or $tree) { Show-MapLevel $(if ($script:mapCur) { $script:mapCur } else { $script:mapRoot }) }
    elseif ($v -eq 'files') { Show-MapOverview; Show-MapFiles }
    elseif ($v -eq 'types') { Show-MapTypes }
    elseif ($v -eq 'recent') { Show-MapOverview; Show-MapRecent }
    else {
        $ctl.MapGrow.ItemsSource = $script:growRows
        $ctl.BtnMapUp.IsEnabled = $false
        $ctl.BtnMapAcct.Visibility = 'Collapsed'
        $has = $script:growRows -and $script:growRows.Count -gt 0
        $ctl.EmptyMap.Visibility = if ($has) { 'Collapsed' } else { 'Visible' }
        $ctl.EmptyMapText.Text = $script:growNote
        $ctl.MapPath.Text = if ($script:growSummary) { $script:growSummary } else { (T '和上次扫描相比') }
        $ctl.MapPath.ToolTip = $ctl.MapPath.Text
        $ctl.MapInfo.Text = $script:growNote + $(if ($has) { (T ' 双击一行可以跳到这个文件夹。') } else { '' })
        $ctl.MapOverview.Visibility = 'Collapsed'
        $ctl.BtnMapExport.IsEnabled = [bool]$has
        Update-MapSel
    }
}
$ctl.MapViewDirs.Add_Checked({ Set-MapView 'dirs' })
$ctl.MapViewTree.Add_Checked({ Set-MapView 'tree' })
$ctl.MapViewFiles.Add_Checked({ Set-MapView 'files' })
$ctl.MapViewGrow.Add_Checked({ Set-MapView 'grow' })
$ctl.MapViewTypes.Add_Checked({ Set-MapView 'types' })
$ctl.MapViewRecent.Add_Checked({ Set-MapView 'recent' })
$ctl.MapGrowBase.Add_SelectionChanged({ if ($script:mapRoot -and $script:mapView -eq 'grow' -and -not $script:growLoading) { try { Compare-Snapshot $script:mapRoot } catch { $script:growNote = (T '没能和上次比较') }; Set-MapView 'grow' } })
# 按类型：这块盘上每类文件多少个、多大（扫描时顺手数的，所有文件都算，不只 1 MB 以上的）
function Show-MapTypes {
    $r = $script:mapRoot
    $rows = New-Object System.Collections.Generic.List[MapRow]
    $ctl.BtnMapUp.IsEnabled = $false; $ctl.BtnMapAcct.Visibility = 'Collapsed'
    if ($r -and $r.TypeBytes) {
        $order = @(0..9 | Where-Object { $r.TypeCount[$_] -gt 0 } | Sort-Object { $r.TypeBytes[$_] } -Descending)
        $max = if ($order.Count -gt 0) { [double]$r.TypeBytes[$order[0]] } else { 0 }
        $tot = [double]0; foreach ($i in 0..9) { $tot += $r.TypeBytes[$i] }
        foreach ($i in $order) {
            $meta = (T "{0:N0} 个文件") -f $r.TypeCount[$i]
            if ($r.TypeDisk -and $r.TypeDisk[$i] -ge 0 -and ([double]$r.TypeBytes[$i] - [double]$r.TypeDisk[$i]) -ge 32MB -and $r.TypeDisk[$i] -lt $r.TypeBytes[$i] * 0.85) { $meta += (T " · 实际占 {0}") -f (Fmt ([double]$r.TypeDisk[$i])) }
            $meta += $(if ($i -eq 0) { (T ' · 没归到上面几类的扩展名') } else { (T ' · 双击看这一类最大的文件') })
            $row = New-MapRow $script:catNames[$i] ('type:' + $script:catKeys[$i]) $r.TypeBytes[$i] $max $tot $false $null $meta 'type'
            $row.FileCount = [long]$r.TypeCount[$i]
            [void]$rows.Add($row)
        }
    }
    $ctl.MapList.ItemsSource = $rows; $script:mapListKey = 'types'
    $ctl.MapPath.Text = (T '各类文件占多少')
    $ctl.MapInfo.Text = if ($r) { (T "{0} 上的全部 {1:N0} 个文件按扩展名分类{2}") -f $r.FullPath().TrimEnd('\'), $r.Files, $(if ($script:mapScanAt) { (T " · 扫描于 {0:HH:mm}") -f $script:mapScanAt } else { '' }) } else { '' }
    $ctl.EmptyMap.Visibility = if ($rows.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($rows.Count -eq 0) { $ctl.EmptyMapText.Text = (T '这次扫描没有按类型统计（可能是旧的扫描结果），再扫描一次就有了') }
    $ctl.BtnMapExport.IsEnabled = ($rows.Count -gt 0); $ctl.BtnMapReport.IsEnabled = [bool]$r
    Show-MapOverview
    Update-MapSel
}
# 最近改动：读变更日志，看这几天哪些文件夹里新建、改写的文件最多
$script:recentRows = $null; $script:recentNote = ''
function Show-MapRecent {
    $rows = New-Object System.Collections.Generic.List[MapRow]
    $ctl.BtnMapUp.IsEnabled = $false; $ctl.BtnMapAcct.Visibility = 'Collapsed'
    $list = $script:recentRows
    if ($list -and $list.Count -gt 0) {
        $max = [double]$list[0].Bytes; $tot = [double]0; foreach ($x in $list) { $tot += [double]$x.Bytes }
        foreach ($x in $list) {
            $top = -1; $tb = [long]0; for ($i = 0; $i -lt 10; $i++) { if ($x.ByCat[$i] -gt $tb) { $tb = $x.ByCat[$i]; $top = $i } }
            $meta = (T "{0:N0} 个文件新建或改写过") -f $x.Files
            if ($x.Deleted -gt 0) { $meta += (T "，{0:N0} 个删掉了") -f $x.Deleted }
            if ($top -ge 0 -and $tb -ge $x.Bytes * 0.5 -and $x.Bytes -gt 0) { $meta += (T " · 主要是{0}") -f $script:catNames[$top] }
            $meta += (T ' · 双击打开这个文件夹')
            $node = [DiskMap]::Find($script:mapRoot, $x.Path)
            $row = New-MapRow (Split-Path $x.Path -Leaf) $x.Path $x.Bytes $max 0 $false $null $meta 'recent'
            if (-not $row.Name) { $row.Name = $x.Path }
            $row.Node = $node; $row.FileCount = [long]$x.Files; $row.Pct = ''
            $row.SizeText = (T "现在共 {0}") -f (Fmt ([double]$x.Bytes))
            [void]$rows.Add($row)
        }
    }
    $ctl.MapList.ItemsSource = $rows; $script:mapListKey = 'recent'
    $ctl.MapPath.Text = (T '最近改动最多的文件夹')
    $ctl.MapInfo.Text = $script:recentNote
    $ctl.EmptyMap.Visibility = if ($rows.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($rows.Count -eq 0) { $ctl.EmptyMapText.Text = if ($script:recentNote) { $script:recentNote } else { (T '选一个时间段，点「查看」') } }
    $ctl.BtnMapExport.IsEnabled = ($rows.Count -gt 0); $ctl.BtnMapReport.IsEnabled = [bool]$script:mapRoot
    Update-MapSel
}
Register-BgJob 'recent' -Cancel look -ReadOnly -Done {
    End-Op (T '完成')
    $script:recentRows = $sync.RecentResult
    $n = [string]$sync.RecentNote
    $script:recentNote = switch -Wildcard ($n) {
        'no-index' { (T '这块盘的文件表不在内存里了，再扫描一次就可以') }
        'no-journal' { (T '这块盘没有开变更日志（USN Journal），Windows 一般只给系统盘开') }
        'refs' { (T '这块盘的变更日志是 ReFS 的格式，暂时不认') }
        'journal-from:*' { (T "按变更日志统计，最近 {0} 天。日志只保留到 {1:yyyy-MM-dd HH:mm}，更早的改动看不到。大小按文件现在的大小算，删掉的只计个数；只列改动最集中的文件夹") -f $sync.RecentDays, [DateTime]::FromFileTimeUtc([long]$n.Substring(13)).ToLocalTime() }
        default { (T "按变更日志统计，最近 {0} 天。大小按文件现在的大小算（日志里没有写了多少字节），删掉的只计个数；只列改动最集中的文件夹") -f $sync.RecentDays }
    }
    if ($script:mapView -eq 'recent') { Show-MapRecent }
}
function Start-MapRecent {
    if ($script:worker -or -not $script:mapRoot) { return }
    $days = 1; $t = $ctl.MapRecentDays.SelectedItem; if ($t) { $days = [int]([string]$t.Tag) }
    if ([string]$script:mapMethod -notlike 'mft*') { $script:recentRows = $null; $script:recentNote = (T '这块盘是逐个文件夹扫描的，没有读文件表，看不了变更日志。打开「快速扫描」再扫一次就可以'); Show-MapRecent; return }
    Use-BgJob 'recent'; $sync.RecentResult = $null; $sync.RecentNote = ''; $sync.RecentDays = $days
    Start-Op (T '读取变更日志') -NoCard; UI-Busy $true
    $ctl.EmptyMap.Visibility = 'Visible'; $ctl.EmptyMapText.Text = (T '正在读变更日志…'); $ctl.MapList.ItemsSource = $null
    Start-Worker @'
$note = ''
$since = [DateTime]::UtcNow.AddDays(-[double]$arg.Days).ToFileTimeUtc()
$sync.RecentResult = [DiskMap]::RecentDirs($arg.Root, $since, 60, [ref]$note)
$sync.RecentNote = $note
'@ @{ Root = $script:mapRoot.FullPath(); Days = $days }
}
$ctl.BtnMapRecent.Add_Click({ Start-MapRecent })
$ctl.MapRecentDays.Add_SelectionChanged({ if ($script:mapView -eq 'recent' -and $script:mapRoot -and -not $script:worker) { Start-MapRecent } })
$ctl.BtnMapUp.Add_Click({ Go-MapUp })
# 空间明细：已用空间都花在哪，为什么和按文件大小相加对不上（快速扫描读了文件表才有）
function Show-SpaceAcct {
    $r = $script:mapRoot
    if (-not $r -or -not $r.HasDisk) { return }
    $drive = $r.FullPath()
    $total = [double]0; $used = [double]0
    $du = Get-DriveUse $drive; $total = $du.Total; $used = $du.Used   # 和磁盘卡片上写的已用是同一个数
    $files = [double]$r.UniqueDisk; $mft = [double]$r.MftBytes
    $a = New-Object System.Collections.Generic.List[string]
    $a.Add(((T "· 文件实际占用 {0}：每个文件只算一次，有几个名字的（硬链接）也只算一份") -f (Fmt $files)))
    $svi = [DiskMap]::Find($r, (Join-Path $drive 'System Volume Information'))
    if ($svi -and $svi.Disk -ge 100MB) { $a.Add(((T "　其中系统还原点等（System Volume Information）{0}，在「省空间」里可以查看") -f (Fmt ([double]$svi.Disk)))) }
    $a.Add(((T "· 文件表（MFT）{0}：NTFS 记录每个文件信息的地方，文件越多越大，删了文件也不会变小") -f (Fmt $mft)))
    $rest = $used - $files - $mft
    if ($used -gt 0 -and $rest -ge 0) { $a.Add(((T "· 其他 {0}：NTFS 的日志和变更日志、文件夹的索引、Windows 给系统更新预留的空间（保留的存储）等，不是普通文件") -f (Fmt $rest))) }
    $b = New-Object System.Collections.Generic.List[string]
    $b.Add(((T "· 按文件大小相加（资源管理器的算法）是 {0}") -f (Fmt ([double]$r.Size))))
    if ($r.Linked -gt 0) { $b.Add(((T "· 硬链接：{0} 的文件不止一个名字（大多在 WinSxS 和 System32 里），按名字相加会重复算，盘上只有一份") -f (Fmt ([double]$r.Linked)))) }
    $d = [double]$r.UniqueSize - [double]$r.UniqueDisk
    if ($d -ge 1MB) { $b.Add(((T "· 压缩、稀疏和只在云端的文件：实际占用比文件大小合计少 {0}（已经扣掉了零头按整块分配多占的部分）") -f (Fmt $d))) }
    elseif ($d -le -1MB) { $b.Add(((T "· 文件按整块（簇，通常 4 KB）分配，零头也占一整块：实际占用比文件大小合计多 {0}") -f (Fmt (-$d)))) }
    $text = ((T "{0} 已用 {1}（共 {2}），其中：") -f $drive.TrimEnd('\'), (Fmt $used), (Fmt $total)) + "`n" + ($a -join "`n") + "`n`n" + (T '和「按文件大小相加」的差别：') + "`n" + ($b -join "`n")
    if ($script:mapScanAt) { $text += "`n`n" + ((T "按 {0:HH:mm} 扫描的结果。") -f $script:mapScanAt) }
    Show-Sheet -Title (T '空间明细') -Text $text | Out-Null
}
$ctl.BtnMapAcct.Add_Click({ Show-SpaceAcct })
$ctl.MapGrow.Add_MouseDoubleClick({
    $g = $ctl.MapGrow.SelectedItem
    if (-not $g -or -not $script:mapRoot) { return }
    $node = [DiskMap]::Find($script:mapRoot, [string]$g.Path)
    if (-not $node) { Show-Sheet -Title (T '这次扫描里没有这个文件夹') -Text ((T "{0}`n`n它可能已经被删掉、改了名，或者变得很小。") -f $g.Path) | Out-Null; return }
    $ctl.MapViewDirs.IsChecked = $true
    Show-MapLevel $node
})
# 双击文件夹往里点。在按下左键（第二下）时处理，不等 MouseDoubleClick：复选框模式下按下已经被拦住不让列表选中，
# 那样列表就收不到 MouseDoubleClick 了。双击的是鼠标下面那一行；在复选框上连点两下只是勾两次，右键双击、双击滚动条都不算
function Enter-MapRow($r) {
    if ($r -and $r.Kind -eq 'type') {
        $k = ([string]$r.Path).Substring(5)
        foreach ($it in $ctl.MapType.Items) { if ([string]$it.Tag -eq $k) { $ctl.MapType.SelectedItem = $it } }
        $ctl.MapUnder.IsChecked = $false; $ctl.MapChat.IsChecked = $false
        $ctl.MapViewFiles.IsChecked = $true
        return $true
    }
    if ($r -and $r.Kind -eq 'recent') {
        if ($r.Node) { $ctl.MapViewDirs.IsChecked = $true; Show-MapLevel $r.Node } else { Open-Location $r.Path }
        return $true
    }
    if (-not ($r -and $r.IsDir -and $r.Node)) { return $false }
    if ($script:mapView -ne 'dirs' -and $script:mapView -ne 'tree') { $ctl.MapViewDirs.IsChecked = $true }
    Show-MapLevel $r.Node
    return $true
}
function Update-MapSel {
    $nAll = $ctl.MapList.Items.Count; $nSel = $ctl.MapList.SelectedItems.Count
    $ctl.MapAll.IsEnabled = ($script:mapView -eq 'dirs' -or $script:mapView -eq 'files') -and $nAll -gt 0
    $ctl.MapAll.IsChecked = if ($script:mapView -eq 'grow' -or $nSel -eq 0) { $false } elseif ($nSel -ge $nAll) { $true } else { $null }
    $sel = if ($script:mapView -ne 'grow') { @($ctl.MapList.SelectedItems) } else { @() }
    $r = if ($sel.Count -eq 1) { $sel[0] } else { $null }
    $busy = [bool]$script:worker
    $del = @($sel | Where-Object { -not $_.Locked -and $_.Size -gt 0 })
    $ctl.BtnMapOpen.IsEnabled = [bool]$r -and -not $busy
    $ctl.BtnMapDelete.IsEnabled = ($del.Count -gt 0) -and -not $busy
    $ctl.BtnMapCompress.IsEnabled = [bool]$r -and $r.IsDir -and -not $busy -and -not (Get-CompressBlock $r.Path)
    $ctl.BtnMapMark.IsEnabled = ($del.Count -gt 0)
    $ctl.BtnMapMark.Content = if ($del.Count -gt 0 -and @($del | Where-Object { -not $_.Marked }).Count -eq 0) { (T '从待删清单去掉') } else { (T '加入待删清单') }
    if ($sel.Count -eq 0) {
        $ctl.MapSel.Text = if (Test-CheckMode) { (T '勾选行前面的方框来选中，可以勾一项或多项，再打开位置、压缩或删除；单击行的其他地方不会选中，双击文件夹往里点；按住鼠标上下拖可以一次勾上连着的几行。系统文件夹、软件安装文件夹、C 盘个人文件夹和搬家后的数据带小锁，不能在这里删。') }
                           else { (T '选中一行可以打开位置、压缩或删除；勾选前面的方框，或按住 Ctrl、Shift，可以选多项一起删；按住鼠标（左键或右键）上下拖可以一次选中连着的几行。系统文件夹、软件安装文件夹、C 盘个人文件夹和搬家后的数据带小锁，不能在这里删。') }
        return
    }
    if ($sel.Count -gt 1) {
        $tot = [double]0; foreach ($x in $sel) { $tot += [double]$x.Size }
        $t = (T "已选 {0} 项，共 {1}") -f $sel.Count, (Fmt $tot)
        if ($del.Count -lt $sel.Count) { $t += ((T "（其中 {0} 项带小锁或是链接，不会删）") -f ($sel.Count - $del.Count)) }
        if (Test-CheckMode) { $t += (T '。点行前面的方框取消某一项，按 Esc 全部取消') }
        $ctl.MapSel.Text = $t; return
    }
    $ctl.MapSel.Text = if ($r.Locked) { (T "{0}：不能在这里删（{1}）") -f $r.Name, $r.LockTip } else { "{0}  {1}" -f $r.Name, $r.SizeText }
}
$script:bulkSel = $false
$ctl.MapList.Add_SelectionChanged({ if (-not $script:bulkSel) { Update-MapSel } })
$ctl.MapAll.Add_Click({
    $lv = $ctl.MapList
    if ($lv.Items.Count -gt 0 -and $lv.SelectedItems.Count -ge $lv.Items.Count) { $lv.UnselectAll() } else { $lv.SelectAll() }
    Update-MapSel
})
# ---------- 右键菜单：和下面的按钮做一样的事 ----------
function Invoke-Btn($b) { if ($b -and $b.IsEnabled) { $b.RaiseEvent((New-Object System.Windows.RoutedEventArgs ([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent))) } }
# 右键菜单打开前：照选中的行设好每一项能不能点（返回 $false：没选中，不弹菜单）
# 右键点到的那一行：点在勾着的行上，菜单对全部勾着的行起作用；点在没勾的行上，只对这一行（复选框模式下也不把它勾上）
$script:menuRow = $null; $script:menuRows = @()
function Update-MapMenu {
    if ($script:mapView -eq 'grow') { return $false }
    $r = $script:menuRow
    $rows = @(if ($r -and -not $ctl.MapList.SelectedItems.Contains($r)) { $r } else { $ctl.MapList.SelectedItems })
    $script:menuRows = $rows
    if ($rows.Count -eq 0) { return $false }
    $busy = [bool]$script:worker
    $one = if ($rows.Count -eq 1) { $rows[0] } else { $null }
    $ctl.MmEnter.Visibility = if ($one -and $one.IsDir -and $one.Node) { 'Visible' } else { 'Collapsed' }
    $ctl.MmOpen.IsEnabled = [bool]$one -and -not $busy
    $ctl.MmCopy.IsEnabled = (@($rows | Where-Object { $_.Path }).Count -gt 0)
    $ctl.MmCompress.IsEnabled = [bool]$one -and $one.IsDir -and -not $busy -and -not (Get-CompressBlock $one.Path)
    $nd = @($rows | Where-Object { -not $_.Locked -and $_.Size -gt 0 }).Count
    $ctl.MmDelete.IsEnabled = ($nd -gt 0) -and -not $busy
    $ctl.MmDelete.Header = if ($nd -gt 1) { (T "删除选中的 {0} 项…") -f $nd } else { (T '删除…') }
    $mk = @($rows | Where-Object { -not $_.Locked -and $_.Size -gt 0 -and -not $_.IsSummary })
    $ctl.MmMark.IsEnabled = $mk.Count -gt 0
    $ctl.MmMark.Header = if ($mk.Count -gt 0 -and @($mk | Where-Object { -not $_.Marked }).Count -eq 0) { (T '从待删清单去掉') } else { (T '加入待删清单') }
    return $true
}
$ctl.MapList.Add_ContextMenuOpening({ param($s, $e) if (-not (Update-MapMenu)) { $e.Handled = $true } })
$ctl.MmEnter.Add_Click({ [void](Enter-MapRow @($script:menuRows)[0]) })
$ctl.MmOpen.Add_Click({ $r = @($script:menuRows)[0]; if ($r) { Open-MapRow $r } })
$ctl.MmCompress.Add_Click({ $r = @($script:menuRows)[0]; if ($r -and $r.IsDir) { Start-FolderCompress $r.Path } })
$ctl.MmDelete.Add_Click({ Start-MapDelete @($script:menuRows) })
$ctl.MmCopy.Add_Click({
    $ps = @(@($script:menuRows) | Where-Object { $_.Path } | ForEach-Object { [string]$_.Path })
    if ($ps.Count -gt 0) { try { [System.Windows.Clipboard]::SetText(($ps -join "`r`n")); $ctl.MapSel.Text = (T "已复制 {0} 个路径") -f $ps.Count } catch {} }
})
# ---------- 按住鼠标（左键或右键）上下拖：选中连着的几行（像在资源管理器里拉框）；右键拖的话松开后弹出右键菜单 ----------
# 按住 Ctrl 再拖：在原来选中的基础上加上这一段
function Find-Visual($root, [type]$t) {
    $q = New-Object System.Collections.Queue; $q.Enqueue($root)
    while ($q.Count -gt 0) {
        $v = $q.Dequeue()
        if ($v -is $t) { return $v }
        $n = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($v)
        for ($k = 0; $k -lt $n; $k++) { $q.Enqueue([System.Windows.Media.VisualTreeHelper]::GetChild($v, $k)) }
    }
    return $null
}
# 纵坐标 y 处是第几行（-1 不在任何一行上）。横坐标取中间，行和行之间的缝上下各挪一点再找
function Get-RowAt($lv, [double]$y) {
    $h = [double]$lv.ActualHeight; if ($h -le 4) { return -1 }
    $yy = [math]::Min([math]::Max($y, 2.0), $h - 2.0)
    foreach ($dy in 0, -3, 3) {
        $pt = New-Object System.Windows.Point ([math]::Max(30.0, [double]$lv.ActualWidth / 2)), ($yy + $dy)
        $hit = $lv.InputHitTest($pt)
        if ($hit -is [System.Windows.DependencyObject]) {
            $c = $null; try { $c = [System.Windows.Controls.ItemsControl]::ContainerFromElement($lv, $hit) } catch {}
            if ($c) { return $lv.ItemContainerGenerator.IndexFromContainer($c) }
        }
    }
    # 拖到了最后一行下面的空白处：算最后一行
    $n = $lv.Items.Count
    if ($n -gt 0) {
        $last = $lv.ItemContainerGenerator.ContainerFromIndex($n - 1)
        if ($last) { try { if ($y -ge $last.TranslatePoint((New-Object System.Windows.Point 0, $last.ActualHeight), $lv).Y) { return $n - 1 } } catch {} }
    }
    return -1
}
$script:rdrag = $null
$script:rdragTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:rdragTimer.Interval = [TimeSpan]::FromMilliseconds(50)
function Set-DragRange($d, [int]$to) {
    $lv = $d.Lv; $items = $lv.Items; $n = $items.Count
    if ($to -lt 0 -or $to -ge $n -or $to -eq $d.Cur -or $d.Anchor -ge $n) { return }
    $lo = [math]::Min([math]::Min($d.Anchor, $d.Cur), $to); $hi = [math]::Min($n - 1, [math]::Max([math]::Max($d.Anchor, $d.Cur), $to))
    $a = [math]::Min($d.Anchor, $to); $b = [math]::Max($d.Anchor, $to)
    $script:bulkSel = $true
    try {
        for ($i = $lo; $i -le $hi; $i++) {
            $it = $items[$i]
            $want = ($i -ge $a -and $i -le $b) -or ($d.Base -and $d.Base.Contains($it))
            $has = $lv.SelectedItems.Contains($it)
            if ($want -and -not $has) { [void]$lv.SelectedItems.Add($it) } elseif ($has -and -not $want) { [void]$lv.SelectedItems.Remove($it) }
        }
    } finally { $script:bulkSel = $false }
    $d.Cur = $to
    Update-MapSel
}
function Start-RowDrag($d) {
    $lv = $d.Lv
    if (-not $script:mapScroller) { $script:mapScroller = Find-Visual $lv ([System.Windows.Controls.ScrollViewer]) }
    # 鼠标交给列表里的滚动区，不交给列表本身：列表自己拿着鼠标时，右键拖会被它放掉，左键拖它会把选中改成鼠标下面的那一行
    $d.Cap = if ($script:mapScroller) { $script:mapScroller } else { $lv }
    $d.Moved = $true
    [void]$d.Cap.CaptureMouse()
    if ($d.Ctrl) { $d.Base = New-Object 'System.Collections.Generic.HashSet[object]'; foreach ($x in @($lv.SelectedItems)) { [void]$d.Base.Add($x) } }
    else {
        $script:bulkSel = $true
        try { $lv.SelectedItems.Clear(); [void]$lv.SelectedItems.Add($lv.Items[$d.Anchor]) } finally { $script:bulkSel = $false }
    }
    $script:rdragTimer.Start()
}
function Stop-RowDrag {
    $d = $script:rdrag; $script:rdrag = $null
    $script:rdragTimer.Stop()
    if ($d -and $d.Moved -and $d.Cap -and $d.Cap.IsMouseCaptured) { $d.Cap.ReleaseMouseCapture() }
}
function Get-DragButton($d) { if ($d.Button -eq 'Left') { [System.Windows.Input.Mouse]::LeftButton } else { [System.Windows.Input.Mouse]::RightButton } }
# 按下的地方在不在行前面的复选框上（在的话交给复选框，不拖选）
function Test-InCheckBox($lv, $el) {
    try {
        for ($v = $el; $v -and -not [object]::ReferenceEquals($v, $lv); $v = [System.Windows.Media.VisualTreeHelper]::GetParent($v)) {
            if ($v -is [System.Windows.Controls.CheckBox]) { return $true }
            if ($v -is [System.Windows.Controls.ListViewItem]) { return $false }
        }
    } catch {}
    return $false
}
# 复选框模式（设置里开着「项目复选框」）：只有点方框才选中、取消。单击行的其他地方不选，双击文件夹照常往里点；
# 按住鼠标上下拖是把拖过的行勾上（加在已勾的上面）；Ctrl 点照常加上或去掉一行；Shift 点是把上次勾的那一行到这一行都勾上；
# 键盘上下键只移动焦点，空格勾上或取消；Esc 全部取消
$script:tickAnchor = -1; $script:kbRow = -1; $script:lastPress = $null; $script:treeFocus = $null
function Test-CheckMode { $win.Resources['MapCkVis'] -eq [System.Windows.Visibility]::Visible -and ($script:mapView -eq 'dirs' -or $script:mapView -eq 'files' -or $script:mapView -eq 'tree') }
function Add-MapRange([int]$from, [int]$to) {
    $lv = $ctl.MapList; $n = $lv.Items.Count
    if ($to -lt 0 -or $to -ge $n) { return }
    if ($from -lt 0 -or $from -ge $n) { $from = $to }
    $script:bulkSel = $true
    try { for ($k = [math]::Min($from, $to); $k -le [math]::Max($from, $to); $k++) { $it = $lv.Items[$k]; if (-not $lv.SelectedItems.Contains($it)) { [void]$lv.SelectedItems.Add($it) } } }
    finally { $script:bulkSel = $false }
    $script:tickAnchor = $to
    Update-MapSel
}
# 按在第 i 行上（不是方框）：复选框模式下改成什么样。返回 Handled：不让列表自己去选；Add：接着拖的话加在已选的上面；NoDrag：不拖选
function Invoke-RowPress([int]$i, [string]$button, [bool]$shift, [bool]$ctrl) {
    if (-not (Test-CheckMode)) {
        if ($button -eq 'Left' -and $shift) { return @{ Handled = $false; Add = $false; NoDrag = $true } }   # Windows 列表自己会从上次点的那一行选到这里
        return @{ Handled = $false; Add = $ctrl; NoDrag = $false }
    }
    if ($ctrl) { $script:tickAnchor = $i; return @{ Handled = $false; Add = $true; NoDrag = $false } }   # Ctrl 点：照 Windows 列表加上或去掉这一行
    if ($button -eq 'Left' -and $shift) { Add-MapRange $script:tickAnchor $i; return @{ Handled = $true; Add = $true; NoDrag = $true } }
    return @{ Handled = $true; Add = $true; NoDrag = $false }      # 单击不选；拖到别的行才把拖过的勾上
}
# 点了方框：记下从哪一行接着用 Shift 勾
$ctl.MapList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    if (-not ($e.OriginalSource -is [System.Windows.Controls.CheckBox])) { return }
    $c = $null; try { $c = [System.Windows.Controls.ItemsControl]::ContainerFromElement($ctl.MapList, $e.OriginalSource) } catch {}
    if ($c) { $script:tickAnchor = $ctl.MapList.ItemContainerGenerator.IndexFromContainer($c) }
})
# 键盘：Esc 全部取消；复选框模式下上下键只移动焦点，空格勾上或取消
$ctl.MapList.Add_PreviewKeyDown({
    param($s, $e)
    if ($e.Key -eq [System.Windows.Input.Key]::Escape -and $s.SelectedItems.Count -gt 0) { $s.UnselectAll(); $e.Handled = $true; return }
    if (-not (Test-CheckMode)) { return }
    if ([System.Windows.Input.Keyboard]::Modifiers -band ([System.Windows.Input.ModifierKeys]::Control -bor [System.Windows.Input.ModifierKeys]::Shift -bor [System.Windows.Input.ModifierKeys]::Alt)) { return }
    $n = $s.Items.Count; if ($n -eq 0) { return }
    $cur = -1; $f = [System.Windows.Input.Keyboard]::FocusedElement
    if ($f -is [System.Windows.Controls.ListViewItem]) { $cur = $s.ItemContainerGenerator.IndexFromContainer($f) }
    elseif ($script:kbRow -ge 0 -and $script:kbRow -lt $n) { $cur = $script:kbRow }
    $k = $e.Key
    if ($k -eq [System.Windows.Input.Key]::Space) {
        if ($cur -ge 0) { $it = $s.Items[$cur]; if ($s.SelectedItems.Contains($it)) { [void]$s.SelectedItems.Remove($it) } else { [void]$s.SelectedItems.Add($it) }; $script:tickAnchor = $cur }
        $e.Handled = $true; return
    }
    $to = if ($k -eq [System.Windows.Input.Key]::Down) { $cur + 1 } elseif ($k -eq [System.Windows.Input.Key]::Up) { [math]::Max(0, $cur - 1) } elseif ($k -eq [System.Windows.Input.Key]::Home) { 0 } elseif ($k -eq [System.Windows.Input.Key]::End) { $n - 1 }
          elseif ($k -eq [System.Windows.Input.Key]::PageDown) { $cur + 10 } elseif ($k -eq [System.Windows.Input.Key]::PageUp) { [math]::Max(0, $cur - 10) } else { -1 }
    if ($to -lt 0) { return }
    $e.Handled = $true
    $to = [math]::Min($n - 1, $to)
    $s.ScrollIntoView($s.Items[$to]); $s.UpdateLayout()
    $c = $s.ItemContainerGenerator.ContainerFromIndex($to); if ($c) { [void]$c.Focus() }
    $script:kbRow = $to
})
# 按下：记下从哪一行开始；真正拖到别的行才算拖选
function Begin-RowDrag($s, $e, [string]$button) {
    Stop-RowDrag
    if (-not ($e.OriginalSource -is [System.Windows.DependencyObject])) { if ($button -eq 'Right') { $script:menuRow = $null }; return }
    if ($button -eq 'Left' -and (Test-InCheckBox $s $e.OriginalSource)) { return }
    $mods = [System.Windows.Input.Keyboard]::Modifiers
    $shift = ($mods -band [System.Windows.Input.ModifierKeys]::Shift) -ne 0
    $ctrl = ($mods -band [System.Windows.Input.ModifierKeys]::Control) -ne 0
    $c = $null; try { $c = [System.Windows.Controls.ItemsControl]::ContainerFromElement($s, $e.OriginalSource) } catch {}
    if ($button -eq 'Right') { $script:menuRow = if ($c) { $c.Content } else { $null } }
    if (-not $c) { return }
    if ($button -eq 'Left') {
        # 双击：Windows 给的点击次数，或者自己算（同一行、在系统设的双击时间内、鼠标没怎么动）
        $pt = $e.GetPosition($s); $row = $c.Content
        $lp = $script:lastPress
        $dbl = $e.ClickCount -ge 2 -or ($lp -and [object]::ReferenceEquals($lp.Row, $row) -and ($e.Timestamp - $lp.Ts) -ge 0 -and ($e.Timestamp - $lp.Ts) -le [System.Windows.Forms.SystemInformation]::DoubleClickTime -and
                                        [math]::Abs($pt.X - $lp.X) -le 6 -and [math]::Abs($pt.Y - $lp.Y) -le 6)
        $script:lastPress = if ($dbl) { $null } else { @{ Row = $row; Ts = $e.Timestamp; X = $pt.X; Y = $pt.Y } }
        if ($dbl) {
            if (Enter-MapRow $row) { $e.Handled = $true; return }
            if ($row -and $row.IsDir) { Write-LogFile ((T "空间地图：双击的「{0}」进不去（扫描结果里没有它的下一层）") -f $row.Name) }
            if (Test-CheckMode) { $e.Handled = $true; try { if (-not $s.IsKeyboardFocusWithin) { [void]$s.Focus() } } catch {} }
            return
        }
    }
    $i = $s.ItemContainerGenerator.IndexFromContainer($c)
    if ($i -lt 0) { return }
    $p = Invoke-RowPress $i $button $shift $ctrl
    # 不选中；键盘焦点给列表（不给这一行：给行的话列表会把它滚进视野，两下之间行就挪了位置，双击会点到别的行）
    if ($p.Handled) { $e.Handled = $true; $script:kbRow = $i; try { if (-not $s.IsKeyboardFocusWithin) { [void]$s.Focus() } } catch {} }
    if ($p.NoDrag) { return }
    $script:rdrag = @{ Lv = $s; Anchor = $i; Cur = $i; Moved = $false; Ctrl = [bool]$p.Add; Base = $null; Cap = $null; Button = $button }
}
$ctl.MapList.Add_PreviewMouseLeftButtonDown({ param($s, $e) Begin-RowDrag $s $e 'Left' })
$ctl.MapList.Add_PreviewMouseRightButtonDown({ param($s, $e) Begin-RowDrag $s $e 'Right' })
$ctl.MapList.Add_PreviewMouseMove({
    param($s, $e)
    $d = $script:rdrag
    if (-not $d) { return }
    $st = if ($d.Button -eq 'Left') { $e.LeftButton } else { $e.RightButton }
    if ($st -ne [System.Windows.Input.MouseButtonState]::Pressed) { Stop-RowDrag; return }
    $i = Get-RowAt $s ($e.GetPosition($s).Y)
    if (-not $d.Moved) { if ($i -lt 0 -or $i -eq $d.Anchor) { return }; Start-RowDrag $d }
    Set-DragRange $d $i
})
$ctl.MapList.Add_PreviewMouseLeftButtonUp({ if ($script:rdrag -and $script:rdrag.Button -eq 'Left') { Stop-RowDrag } })
$ctl.MapList.Add_PreviewMouseRightButtonUp({ if ($script:rdrag -and $script:rdrag.Button -eq 'Right') { Stop-RowDrag } })
# 拖选中鼠标被别处拿走了（比如切到别的窗口）：停下。列表把鼠标交出来时也会收到这个，那时不算
$ctl.MapList.Add_LostMouseCapture({ param($s, $e) $d = $script:rdrag; if ($d -and $d.Moved -and $d.Cap -and [object]::ReferenceEquals($e.OriginalSource, $d.Cap)) { $script:rdrag = $null; $script:rdragTimer.Stop() } })
# 拖到列表上面或下面：自动滚动，边滚边选
$script:rdragTimer.Add_Tick({
    $d = $script:rdrag
    if (-not $d -or -not $d.Moved) { $script:rdragTimer.Stop(); return }
    if ((Get-DragButton $d) -ne [System.Windows.Input.MouseButtonState]::Pressed) { Stop-RowDrag; return }
    $lv = $d.Lv; $y = [System.Windows.Input.Mouse]::GetPosition($lv).Y; $h = [double]$lv.ActualHeight
    if ($y -ge 0 -and $y -le $h) { return }
    $sv = $script:mapScroller; if (-not $sv) { return }
    $over = if ($y -lt 0) { -$y } else { $y - $h }
    $steps = [math]::Min(4, 1 + [int][math]::Floor($over / 30))
    for ($k = 0; $k -lt $steps; $k++) { if ($y -lt 0) { $sv.LineUp() } else { $sv.LineDown() } }
    $lv.UpdateLayout()
    Set-DragRange $d (Get-RowAt $lv $y)
})
function Csv-Line([object[]]$cells) {
    (@($cells | ForEach-Object { $s = [string]$_; if ($s -match '[",\r\n]') { '"' + $s.Replace('"', '""') + '"' } else { $s } }) -join ',')
}
# ---------- 导出报告：一个独立的网页，浏览器里按 Ctrl+P 可以存成 PDF ----------
function New-MapReport {
    $root = $script:mapRoot
    $H = { param($s) [System.Net.WebUtility]::HtmlEncode([string]$s) }
    $drive = $root.FullPath()
    $total = [double]0; $free = [double]0
    try { $di = New-Object System.IO.DriveInfo $drive; $total = [double]$di.TotalSize; $free = [double]$di.AvailableFreeSpace } catch {}
    $sb = New-Object System.Text.StringBuilder
    $add = { param($s) [void]$sb.Append($s) }
    # 网页里的坐标和宽度一律用小数点（有的系统设置里小数点是逗号，SVG 不认）
    $num = { param($v) ([double]$v).ToString('0.#', [Globalization.CultureInfo]::InvariantCulture) }
    $bar = { param($v, $max) $w = if ($max -gt 0) { [math]::Max(0.5, 100.0 * $v / $max) } else { 0 }; '<div class="bar"><i style="width:{0}%"></i></div>' -f (& $num $w) }
    $title = (T "空间报告：{0}") -f $drive
    & $add ('<!doctype html><html lang="{0}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{1}</title>' -f $(if ($script:Lang -eq 'en') { 'en' } else { 'zh-CN' }), (& $H $title))
    & $add @"
<style>
:root { --fg:#1d1d1f; --mute:#6e6e73; --line:#e5e5ea; --soft:#f5f5f7; --blue:#0071e3; }
* { box-sizing:border-box; }
body { margin:0; background:#fff; color:var(--fg); font:14px/1.55 "Segoe UI","Microsoft YaHei UI","PingFang SC",sans-serif; }
main { max-width:1040px; margin:0 auto; padding:32px 24px 48px; }
h1 { font-size:26px; margin:0 0 4px; }
h2 { font-size:17px; margin:34px 0 10px; }
.meta { color:var(--mute); margin:0 0 18px; }
.cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:10px; margin:14px 0 6px; }
.card { background:var(--soft); border-radius:10px; padding:12px 14px; }
.card b { display:block; font-size:20px; } .card span { color:var(--mute); font-size:12.5px; }
table { width:100%; border-collapse:collapse; }
th, td { text-align:left; padding:7px 8px; border-bottom:1px solid var(--line); vertical-align:middle; }
th { color:var(--mute); font-weight:600; font-size:12.5px; }
td.n, th.n { text-align:right; white-space:nowrap; }
td.p { word-break:break-all; color:var(--mute); font-size:12.5px; }
.bar { background:#eef0f4; border-radius:4px; height:8px; min-width:120px; } .bar i { display:block; height:8px; border-radius:4px; background:var(--blue); }
.up { color:#d70015; font-weight:600; } .down { color:#248a3d; font-weight:600; }
svg { width:100%; height:auto; display:block; border-radius:8px; }
.note { color:var(--mute); font-size:12.5px; margin-top:8px; }
footer { margin-top:40px; color:var(--mute); font-size:12px; border-top:1px solid var(--line); padding-top:12px; }
@media print { main { padding:0; } h2 { break-after:avoid; } tr { break-inside:avoid; } }
</style></head><body><main>
"@
    & $add ('<h1>{0}</h1>' -f (& $H $title))
    $when = if ($script:mapScanAt) { $script:mapScanAt } else { Get-Date }
    & $add ('<p class="meta">{0}</p>' -f (& $H ((T "扫描于 {0:yyyy-MM-dd HH:mm}，扫描到 {1:N0} 个文件") -f $when, $root.Files)))
    & $add '<div class="cards">'
    foreach ($c in @(@((T '磁盘容量'), $total), @((T '已用'), [math]::Max([double]0, $total - $free)), @((T '剩余'), $free), @((T '扫描到的文件一共'), [double]$root.Size))) {
        if ($c[1] -le 0) { continue }
        & $add ('<div class="card"><b>{0}</b><span>{1}</span></div>' -f (& $H (Fmt $c[1])), (& $H $c[0]))
    }
    & $add '</div>'

    # 方块图：第一层文件夹
    $kids = @($root.Kids | Where-Object { -not $_.IsLink -and $_.Size -gt 0 })
    if ($kids.Count -gt 0) {
        & $add ('<h2>{0}</h2>' -f (& $H (T '方块图：第一层文件夹')))
        $W = 1000; $Hh = 440
        $show = @($kids | Select-Object -First 40); $rest = [double]0; foreach ($k in @($kids | Select-Object -Skip 40)) { $rest += [double]$k.Size }
        $own = [double]$root.Own; if ($own -gt 0) { $rest += $own }
        $sizes = @($show | ForEach-Object { [double]$_.Size }); if ($rest -gt 0) { $sizes += $rest }
        $order = @(0..($sizes.Count - 1) | Sort-Object { $sizes[$_] } -Descending)
        $sorted = [double[]]@($order | ForEach-Object { $sizes[$_] })
        $rects = Get-TreeRects $sorted 0 0 $W $Hh
        & $add ('<svg viewBox="0 0 {0} {1}" role="img" aria-label="{2}">' -f $W, $Hh, (& $H (T '方块图：第一层文件夹')))
        for ($q = 0; $q -lt $order.Count; $q++) {
            $i = $order[$q]; $rc = $rects[$q]; if (-not $rc) { continue }
            $isRest = ($i -ge $show.Count)
            $name = if ($isRest) { (T '其他') } else { $show[$i].Name }
            $fill = if ($isRest) { '#c7ccd6' } else { $script:treeColors[$q % $script:treeColors.Count] }
            & $add ('<g><title>{0}  {1}</title><rect x="{2}" y="{3}" width="{4}" height="{5}" rx="3" fill="{6}" stroke="#fff" stroke-width="2"/>' -f (& $H $name), (& $H (Fmt $sorted[$q])), (& $num $rc[0]), (& $num $rc[1]), (& $num $rc[2]), (& $num $rc[3]), $fill)
            if ($rc[2] -gt 70 -and $rc[3] -gt 30) {
                # 估算文字宽度：中日韩文字约 13 像素，其他约 7.5 像素
                $room = $rc[2] - 14; $wsum = 0.0; $cut = $name.Length
                for ($c = 0; $c -lt $name.Length; $c++) { $wsum += $(if ([int][char]$name[$c] -ge 0x2E80) { 13 } else { 7.5 }); if ($wsum -gt $room) { $cut = [math]::Max(1, $c - 1); break } }
                $label = if ($cut -lt $name.Length) { $name.Substring(0, $cut) + '…' } else { $name }
                & $add ('<text x="{0}" y="{1}" fill="#fff" font-size="13" font-weight="600">{2}</text>' -f (& $num ($rc[0] + 7)), (& $num ($rc[1] + 18)), (& $H $label))
                if ($rc[3] -gt 44) { & $add ('<text x="{0}" y="{1}" fill="#fff" font-size="12" opacity=".9">{2}</text>' -f (& $num ($rc[0] + 7)), (& $num ($rc[1] + 35)), (& $H (Fmt $sorted[$q]))) }
            }
            & $add '</g>'
        }
        & $add '</svg>'

        & $add ('<h2>{0}</h2><table><tr><th>{1}</th><th class="n">{2}</th><th class="n">{3}</th><th>{4}</th><th class="n">{5}</th><th class="n">{6}</th></tr>' -f (& $H (T '最占空间的文件夹')), (& $H (T '文件夹')), (& $H (T '大小')), (& $H (T '占比')), '', (& $H (T '文件数')), (& $H (T '最近修改')))
        $max = [double]$kids[0].Size
        foreach ($k in @($kids | Select-Object -First 30)) {
            $w2 = if ($k.LastWrite -gt 0) { try { [DateTime]::FromFileTime($k.LastWrite).ToString('yyyy-MM-dd') } catch { '' } } else { '' }
            & $add ('<tr><td>{0}</td><td class="n">{1}</td><td class="n">{2:0.0}%</td><td>{3}</td><td class="n">{4:N0}</td><td class="n">{5}</td></tr>' -f (& $H $k.Name), (& $H (Fmt $k.Size)), (100.0 * $k.Size / [math]::Max(1, [double]$root.Size)), (& $bar ([double]$k.Size) $max), $k.Files, $w2)
        }
        & $add '</table>'

        # 再往下一层：第二层里最大的
        $g2 = New-Object System.Collections.ArrayList
        foreach ($k in $kids) { foreach ($c in $k.Kids) { if (-not $c.IsLink -and $c.Size -gt 0) { [void]$g2.Add($c) } } }
        $g2s = @($g2 | Sort-Object { [double]$_.Size } -Descending | Select-Object -First 25)
        if ($g2s.Count -gt 0) {
            & $add ('<h2>{0}</h2><table><tr><th>{1}</th><th class="n">{2}</th><th>{3}</th></tr>' -f (& $H (T '再往下一层：最大的文件夹')), (& $H (T '路径')), (& $H (T '大小')), '')
            $max = [double]$g2s[0].Size
            foreach ($c in $g2s) { & $add ('<tr><td class="p">{0}</td><td class="n">{1}</td><td>{2}</td></tr>' -f (& $H $c.FullPath()), (& $H (Fmt $c.Size)), (& $bar ([double]$c.Size) $max)) }
            & $add '</table>'
        }
    }

    # 最大的文件
    $bf = [DiskMap]::FindFiles(1MB, [DateTime]::MaxValue, '', '', $null, 30)
    if ($bf.Files.Count -gt 0) {
        & $add ('<h2>{0}</h2><table><tr><th>{1}</th><th class="n">{2}</th><th class="n">{3}</th></tr>' -f (& $H (T '最大的 30 个文件')), (& $H (T '路径')), (& $H (T '大小')), (& $H (T '最近修改')))
        foreach ($f in $bf.Files) { & $add ('<tr><td class="p">{0}</td><td class="n">{1}</td><td class="n">{2:yyyy-MM-dd}</td></tr>' -f (& $H $f.Path), (& $H (Fmt $f.Size)), $f.Modified) }
        & $add '</table>'
    }

    # 按类型统计：扫描时数过全部文件就用那个，否则只有 1 MB 以上的
    $tr = $script:mapRoot
    if ($tr -and $tr.TypeBytes) {
        $order = @(0..9 | Where-Object { $tr.TypeCount[$_] -gt 0 } | Sort-Object { $tr.TypeBytes[$_] } -Descending)
        if ($order.Count -gt 0) {
            & $add ('<h2>{0}</h2><table><tr><th>{1}</th><th class="n">{2}</th><th class="n">{3}</th><th>{4}</th></tr>' -f (& $H (T '各类文件占多少')), (& $H (T '类型')), (& $H (T '文件数')), (& $H (T '大小')), '')
            $max = [double]$tr.TypeBytes[$order[0]]
            foreach ($i in $order) { & $add ('<tr><td>{0}</td><td class="n">{1:N0}</td><td class="n">{2}</td><td>{3}</td></tr>' -f (& $H $script:catNames[$i]), $tr.TypeCount[$i], (& $H (Fmt ([double]$tr.TypeBytes[$i]))), (& $bar ([double]$tr.TypeBytes[$i]) $max)) }
            & $add '</table>'
        }
    }
    $ext = if ($tr -and $tr.TypeBytes) { @{} } else { [DiskMap]::ExtTotals() }
    if ($ext.Count -gt 0) {
        $names = [ordered]@{ video = (T '视频'); archive = (T '压缩包和安装包'); image = (T '光盘映像和虚拟磁盘'); picture = (T '图片'); music = (T '音乐'); doc = (T '文档'); program = (T '程序和游戏数据'); log = (T '日志、转储和临时文件'); other = (T '其他类型') }
        $of = @{}; foreach ($k in $script:mapTypes.Keys) { foreach ($e in ($script:mapTypes[$k] -split ' ')) { if ($e) { $of[$e.ToLowerInvariant()] = $k } } }
        $sum = @{}; foreach ($k in $names.Keys) { $sum[$k] = @([long]0, [double]0) }
        foreach ($kv in $ext.GetEnumerator()) { $g = $of[([string]$kv.Key).ToLowerInvariant()]; if (-not $g) { $g = 'other' }; $sum[$g][0] += $kv.Value[0]; $sum[$g][1] += [double]$kv.Value[1] }
        $rows = @($names.Keys | Where-Object { $sum[$_][1] -gt 0 } | Sort-Object { $sum[$_][1] } -Descending)
        if ($rows.Count -gt 0) {
            & $add ('<h2>{0}</h2><table><tr><th>{1}</th><th class="n">{2}</th><th class="n">{3}</th><th>{4}</th></tr>' -f (& $H (T '各类文件占多少')), (& $H (T '类型')), (& $H (T '文件数')), (& $H (T '大小')), '')
            $max = [double]$sum[$rows[0]][1]
            foreach ($k in $rows) { & $add ('<tr><td>{0}</td><td class="n">{1:N0}</td><td class="n">{2}</td><td>{3}</td></tr>' -f (& $H $names[$k]), $sum[$k][0], (& $H (Fmt $sum[$k][1])), (& $bar $sum[$k][1] $max)) }
            & $add '</table>'
            & $add ('<p class="note">{0}</p>' -f (& $H (T '只统计扫描时记下的 1 MB 以上的文件。')))
        }
    }

    # 和上次比
    if ($script:growRows -and $script:growRows.Count -gt 0) {
        & $add ('<h2>{0}</h2><table><tr><th>{1}</th><th class="n">{2}</th><th class="n">{3}</th><th class="n">{4}</th></tr>' -f (& $H (T '和上次扫描相比')), (& $H (T '文件夹')), (& $H (T '上次')), (& $H (T '这次')), (& $H (T '变化')))
        foreach ($g in @($script:growRows | Select-Object -First 30)) {
            $cls = if ($g.NowBytes -ge $g.BeforeBytes) { 'up' } else { 'down' }
            & $add ('<tr><td class="p">{0}</td><td class="n">{1}</td><td class="n">{2}</td><td class="n {3}">{4}</td></tr>' -f (& $H $g.Path), (& $H $g.Before), (& $H $g.Now), $cls, (& $H $g.Change))
        }
        & $add '</table>'
        if ($script:growNote) { & $add ('<p class="note">{0}</p>' -f (& $H $script:growNote)) }
    }
    & $add ('<footer>{0}</footer></main></body></html>' -f (& $H ((T "由腾挪 ClearC {0} 生成，{1:yyyy-MM-dd HH:mm}。报告里只有文件夹和文件的名字、大小，不含文件内容。") -f $script:AppVersion, (Get-Date))))
    return $sb.ToString()
}
$ctl.BtnMapReport.Add_Click({
    if (-not $script:mapRoot) { Show-Sheet -Title (T '还没有扫描') -Text (T '先扫描一块盘，再导出报告。') | Out-Null; return }
    $dlg = New-Object Microsoft.Win32.SaveFileDialog
    $dlg.Filter = (T '网页报告') + '|*.html'
    $dlg.FileName = '{0}-{1}-{2:yyyyMMdd-HHmm}.html' -f (T '空间报告'), $script:mapRoot.FullPath().Substring(0, 1), (Get-Date)
    try { $dlg.InitialDirectory = [Environment]::GetFolderPath('Desktop') } catch {}
    if (-not $dlg.ShowDialog($win)) { return }
    $win.Cursor = [System.Windows.Input.Cursors]::Wait
    try { $html = New-MapReport; [IO.File]::WriteAllText($dlg.FileName, $html, (New-Object Text.UTF8Encoding $true)) }
    catch { $win.Cursor = $null; Show-Sheet -Kind warn -Title (T '没能保存') -Text (Get-FriendlyError $_) | Out-Null; return }
    finally { $win.Cursor = $null }
    UI-Log ((T "空间地图：报告已保存到 {0}") -f $dlg.FileName)
    $ans = Show-Sheet -Kind done -Title (T '报告已保存') -Text ((T "{0}`n`n用浏览器打开就能看；想要 PDF，在浏览器里按 Ctrl+P，打印机选「另存为 PDF」。") -f $dlg.FileName) -Buttons @((T '打开所在位置'), (T '打开报告')) -Primary (T '打开报告') -Cancel (T '打开所在位置')
    if ($ans -eq (T '打开报告')) { if (-not (Open-AsUser $dlg.FileName)) { Open-Location $dlg.FileName } }
    elseif ($ans -eq (T '打开所在位置')) { Open-Location $dlg.FileName }
})
$ctl.BtnMapExport.Add_Click({
    $v = $script:mapView
    $list = @(if ($v -eq 'grow') { $script:growRows } else { $ctl.MapList.ItemsSource })
    if (-not $script:mapRoot -or $list.Count -eq 0) { Show-Sheet -Title (T '没有可以导出的内容') -Text (T '先扫描一块盘，再导出看到的列表。') | Out-Null; return }
    $what = switch ($v) { 'files' { (T '找文件') } 'grow' { (T '和上次比') } default { (T '文件夹') } }
    $dlg = New-Object Microsoft.Win32.SaveFileDialog
    $dlg.Filter = (T 'CSV 文件（可以用 Excel 打开）') + '|*.csv'
    $dlg.FileName = '{0}-{1}-{2}-{3:yyyyMMdd-HHmm}.csv' -f (T '空间地图'), $script:mapRoot.FullPath().Substring(0, 1), $what, (Get-Date)
    try { $dlg.InitialDirectory = [Environment]::GetFolderPath('Desktop') } catch {}
    if (-not $dlg.ShowDialog($win)) { return }
    $lines = New-Object System.Collections.Generic.List[string]
    if ($v -eq 'grow') {
        $lines.Add((Csv-Line @((T '文件夹'), (T '上次（字节）'), (T '这次（字节）'), (T '变化（字节）'), (T '上次'), (T '这次'), (T '变化'))))
        foreach ($g in $list) { $lines.Add((Csv-Line @($g.Path, [long]$g.BeforeBytes, [long]$g.NowBytes, [long]($g.NowBytes - $g.BeforeBytes), $g.Before, $g.Now, $g.Change))) }
    } else {
        $lines.Add((Csv-Line @((T '名称'), (T '路径'), (T '类型'), (T '大小（字节）'), (T '大小'), (T '文件数'), (T '最近修改'))))
        foreach ($r in $list) {
            if ($r.IsSummary) { continue }
            $k = if ($r.Kind -eq 'type') { (T '类型') } elseif ($r.Kind -eq 'recent') { (T '最近改动') } elseif ($r.IsDir) { (T '文件夹') } elseif ($r.Node -and $r.Node.IsLink) { (T '链接') } else { (T '文件') }
            $lines.Add((Csv-Line @($r.Name, $r.Path, $k, [long]$r.Size, $r.SizeText, $(if ($r.IsDir) { $r.FileCount } else { '' }), $r.When)))
        }
    }
    try { [IO.File]::WriteAllLines($dlg.FileName, $lines.ToArray(), (New-Object Text.UTF8Encoding $true)) }
    catch { Show-Sheet -Kind warn -Title (T '没能保存') -Text (Get-FriendlyError $_) | Out-Null; return }
    UI-Log ((T "空间地图：已导出 {0} 行到 {1}") -f $list.Count, $dlg.FileName)
    $ans = Show-Sheet -Kind done -Title (T '已导出') -Text ((T "{0:N0} 行，已保存到：`n{1}") -f $list.Count, $dlg.FileName) -Buttons @((T '打开所在位置'), (T '好')) -Primary (T '好') -Cancel (T '好')
    if ($ans -eq (T '打开所在位置')) { Open-Location $dlg.FileName }
})
function Open-MapRow($r) { if ($r.IsSummary) { if ($script:mapCur) { Open-Location $script:mapCur.FullPath() } } else { Open-Location $r.Path } }
$ctl.BtnMapOpen.Add_Click({ $r = $ctl.MapList.SelectedItem; if ($r) { Open-MapRow $r } })

# 和上次比：每次扫描存一份快照（带日期，每块盘最多留 40 份），和选定的那一份对比，列出变化最大的文件夹，
# 并用一句话说清多出来的空间主要在哪（Docker、浏览器缓存、某个文件夹……）
function Read-Snapshot([string]$file) {
    $old = @{}; $oldAt = ''; $oldHow = 'walk'; $used = [double]-1
    foreach ($l in [IO.File]::ReadAllLines($file, [Text.Encoding]::UTF8)) {
        if ($l.StartsWith('#method=')) { $oldHow = $l.Substring(8).Trim(); continue }
        if ($l.StartsWith('#used=')) { $used = [double]$l.Substring(6).Trim(); continue }
        if ($l.StartsWith('#')) { $oldAt = $l.TrimStart('#').Trim(); continue }
        $a = $l.Split("`t"); if ($a.Count -eq 2) { $old[$a[0].ToLowerInvariant()] = [double]$a[1] }
    }
    return @{ Map = $old; At = $oldAt; How = $oldHow; Used = $used }
}
# 选「和哪次比」：上一次，或者 N 天前最近的一份（没那么早的就拿最早的）
function Pick-Snapshot([string]$letter, [int]$days) {
    $latest = Join-Path $script:snapDir "$letter-latest.txt"
    if ($days -le 0) { return $(if (Test-Path -LiteralPath $latest) { $latest } else { '' }) }
    $files = @(Get-ChildItem -LiteralPath $script:snapDir -Filter "$letter-2*.txt" -ErrorAction SilentlyContinue | Sort-Object Name)
    if ($files.Count -eq 0) { return $(if (Test-Path -LiteralPath $latest) { $latest } else { '' }) }
    $cut = (Get-Date).AddDays(-$days)
    $pick = $null
    foreach ($f in $files) {
        $t = $null; try { $t = [DateTime]::ParseExact($f.BaseName.Substring(2), 'yyyyMMdd-HHmm', $null) } catch { continue }
        if ($t -le $cut) { $pick = $f } else { break }
    }
    if (-not $pick) { $pick = $files[0] }
    return $pick.FullName
}
function Update-Growth($root) {
    $letter = $root.FullPath().Substring(0, 1).ToUpper()
    New-Item -ItemType Directory -Path $script:snapDir -Force | Out-Null
    $latest = Join-Path $script:snapDir "$letter-latest.txt"
    $snap = [DiskMap]::Snapshot($root, 4, 100MB)
    $script:curSnap = $snap
    # 先和上一次比（界面上默认选的就是它），再把这次存起来
    Compare-Snapshot $root
    $out = New-Object System.Collections.Generic.List[string]
    $out.Add(('#method=' + $(if ([string]$script:mapMethod -like 'mft*') { 'mft' } else { 'walk' })))   # 放在日期前面：旧版本只认最后一个 # 行当日期
    $used = [double]-1; try { $di = New-Object System.IO.DriveInfo ($root.FullPath()); $used = [double]($di.TotalSize - $di.TotalFreeSpace) } catch {}
    if ($used -ge 0) { $out.Add('#used=' + [long]$used) }
    $out.Add(("# {0:yyyy-MM-dd HH:mm}" -f (Get-Date)))
    foreach ($l in $snap) { $out.Add($l) }
    if (Test-Path -LiteralPath $latest) { Copy-Item -LiteralPath $latest -Destination (Join-Path $script:snapDir "$letter-previous.txt") -Force -ErrorAction SilentlyContinue }
    [IO.File]::WriteAllLines($latest, $out.ToArray(), (New-Object Text.UTF8Encoding $false))
    # 带日期的一份：一天最多留一份（同一天的覆盖），总共最多 40 份
    $dated = Join-Path $script:snapDir ("{0}-{1:yyyyMMdd-HHmm}.txt" -f $letter, (Get-Date))
    foreach ($f in @(Get-ChildItem -LiteralPath $script:snapDir -Filter ("{0}-{1:yyyyMMdd}-*.txt" -f $letter, (Get-Date)) -ErrorAction SilentlyContinue)) { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue }
    Copy-Item -LiteralPath $latest -Destination $dated -Force -ErrorAction SilentlyContinue
    $all = @(Get-ChildItem -LiteralPath $script:snapDir -Filter "$letter-2*.txt" -ErrorAction SilentlyContinue | Sort-Object Name)
    if ($all.Count -gt 40) { foreach ($f in @($all | Select-Object -First ($all.Count - 40))) { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue } }
}
# 多出来（或少掉）的空间主要在哪：从变化最大的文件夹里挑互不包含的几个，认得出的（Docker、WSL、浏览器缓存、Windows 更新……）写名字
function Explain-Growth($items, [double]$totalDelta) {
    $known = @(
        @('\docker\', (T 'Docker 数据')), @('docker-desktop', (T 'Docker 数据')), @('\ext4.vhdx', (T 'WSL 发行版')), @('\packages\canonicalgrouplimited', (T 'WSL 发行版')),
        @('\softwaredistribution', (T 'Windows 更新')), @('\windows.old', 'Windows.old'), @('\$recycle.bin', (T '回收站')), @('\winsxs', (T '组件存储（WinSxS）')),
        @('\user data\', (T '浏览器缓存和数据')), @('\cache', (T '缓存')), @('\temp', (T '临时文件')), @('\steamapps', (T 'Steam 游戏')), @('\appdata\local\packages', (T '应用商店软件')),
        @('\onedrive', 'OneDrive'), @('\xwechat_files', (T '微信数据')), @('\wechat files', (T '微信数据')), @('\tencent files', (T 'QQ 数据')), @('\minidump', (T '蓝屏转储')), @('\memory.dmp', (T '蓝屏转储')),
        @('\node_modules', 'node_modules'), @('\.nuget', (T 'NuGet 包')), @('\jetbrains', (T 'JetBrains 缓存')), @('\videos', (T '视频')), @('\downloads', (T '下载'))
    )
    $sign = if ($totalDelta -ge 0) { 1 } else { -1 }
    $cands = @($items | Where-Object { $_.D * $sign -gt 0 } | Sort-Object { $_.D * $sign } -Descending)
    $picked = New-Object System.Collections.ArrayList
    foreach ($c in $cands) {
        if ($picked.Count -ge 4) { break }
        $p = ([string]$c.P).TrimEnd('\').ToLowerInvariant()
        $dup = $false
        foreach ($q in $picked) { $qp = ([string]$q.P).TrimEnd('\').ToLowerInvariant(); if ($p.StartsWith($qp + '\') -or $qp.StartsWith($p + '\') -or $p -eq $qp) { $dup = $true; break } }
        if ($dup) { continue }
        if ([math]::Abs($c.D) -lt [math]::Max(200MB, [math]::Abs($totalDelta) * 0.08)) { break }
        [void]$picked.Add($c)
    }
    $parts = New-Object System.Collections.Generic.List[string]
    $acc = [double]0
    foreach ($c in $picked) {
        $p = ([string]$c.P).ToLowerInvariant() + '\'
        $name = $null; foreach ($k in $known) { if ($p -like ('*' + $k[0] + '*')) { $name = $k[1]; break } }
        $label = if ($name) { "{0}（{1}）" -f $name, (Shorten ([string]$c.P)) } else { Shorten ([string]$c.P) }
        $parts.Add(("{0} {1}{2}" -f $label, $(if ($c.D -gt 0) { '+' } else { '−' }), (Fmt ([math]::Abs($c.D)))))
        $acc += $c.D
    }
    $rest = $totalDelta - $acc
    if ($parts.Count -gt 0 -and [math]::Abs($rest) -ge 100MB) { $parts.Add(((T "其余 {0}{1}") -f $(if ($rest -gt 0) { '+' } else { '−' }), (Fmt ([math]::Abs($rest))))) }
    return ($parts -join (T '，'))
}
function Compare-Snapshot($root) {
    $script:growRows = New-Object 'System.Collections.ObjectModel.ObservableCollection[GrowRow]'
    $script:growSummary = ''
    $letter = $root.FullPath().Substring(0, 1).ToUpper()
    $days = 0; $t = $ctl.MapGrowBase.SelectedItem; if ($t) { $days = [int]([string]$t.Tag) }
    $file = Pick-Snapshot $letter $days
    $old = @{}; $oldAt = ''; $oldHow = 'walk'; $oldUsed = [double]-1
    if ($file -and (Test-Path -LiteralPath $file)) { $s = Read-Snapshot $file; $old = $s.Map; $oldAt = $s.At; $oldHow = $s.How; $oldUsed = $s.Used }
    $snap = $script:curSnap
    if (-not $snap) { $snap = [DiskMap]::Snapshot($root, 4, 100MB); $script:curSnap = $snap }
    $script:prevSnap = $old
    if ($old.Count -gt 0) {
        $list = New-Object System.Collections.ArrayList
        $seen = @{}
        foreach ($l in $snap) {
            $a = $l.Split("`t"); $k = $a[0].ToLowerInvariant(); $now = [double]$a[1]; $seen[$k] = $true
            $before = if ($old.ContainsKey($k)) { $old[$k] } else { [double]0 }
            $d = $now - $before
            if ([math]::Abs($d) -ge 100MB) { [void]$list.Add(@{ P = $a[0]; B = $before; N = $now; D = $d; Had = $old.ContainsKey($k) }) }
        }
        foreach ($k in $old.Keys) { if (-not $seen.ContainsKey($k) -and $old[$k] -ge 200MB) { [void]$list.Add(@{ P = $k; B = $old[$k]; N = [double]0; D = -$old[$k]; Had = $true }) } }
        # 一句话：已用空间变了多少，主要在哪
        $usedNow = [double]-1; try { $di = New-Object System.IO.DriveInfo ($root.FullPath()); $usedNow = [double]($di.TotalSize - $di.TotalFreeSpace) } catch {}
        $span = ''; try { $t0 = [DateTime]::ParseExact($oldAt, 'yyyy-MM-dd HH:mm', $null); $span = FmtSpan ((Get-Date) - $t0) } catch {}
        $delta = if ($oldUsed -ge 0 -and $usedNow -ge 0) { $usedNow - $oldUsed } else { [double]$root.Size - [double](($old.Values | Measure-Object -Maximum).Maximum) }
        if ($oldUsed -ge 0 -and $usedNow -ge 0) {
            $head = if ($span) { (T "过去 {0}，已用空间{1}{2}") -f $span, $(if ($delta -ge 0) { (T '增加 ') } else { (T '减少 ') }), (Fmt ([math]::Abs($delta))) } else { (T "和 {0} 相比，已用空间{1}{2}") -f $oldAt, $(if ($delta -ge 0) { (T '增加 ') } else { (T '减少 ') }), (Fmt ([math]::Abs($delta))) }
            $why = Explain-Growth $list $delta
            $script:growSummary = $(if ($why) { "{0}{1}{2}" -f $head, (T '，其中 '), $why } else { $head }) + (T '。')
        }
        foreach ($x in @($list | Sort-Object { $_.D } -Descending | Select-Object -First 60)) {
            $g = New-Object GrowRow
            $g.Path = $x.P
            $g.Before = if ($x.Had) { Fmt $x.B } else { (T '不到 100 MB') }
            $g.Now = if ($x.N -gt 0) { Fmt $x.N } else { (T '不到 100 MB') }
            $g.Change = $(if ($x.D -gt 0) { '+' } else { '−' }) + (Fmt ([math]::Abs($x.D)))
            $g.ChangeBrush = if ($x.D -gt 0) { '#D70015' } else { '#1D7A35' }
            $g.BeforeBytes = [double]$x.B; $g.NowBytes = [double]$x.N
            $script:growRows.Add($g)
        }
        $script:growNote = if ($script:growRows.Count -gt 0) { ((T "上次扫描在 {0}。红色是变大的，绿色是变小的（只列变化超过 100 MB 的文件夹）") -f $oldAt) } else { ((T "和上次（{0}）相比，没有文件夹变化超过 100 MB") -f $oldAt) }
        # 读文件表能看到逐个扫描进不去的文件夹（比如 System Volume Information），两种方式的结果放在一起比会有出入
        $newHow = if ([string]$script:mapMethod -like 'mft*') { 'mft' } else { 'walk' }
        if ($oldHow -ne $newHow) {
            $script:growNote += $(if ($newHow -eq 'mft') { (T '。这次是直接读文件表，原来进不去的文件夹（比如 System Volume Information）也算进来了，这些文件夹看起来变大不一定是真的变大') } else { (T '。这次是逐个文件夹扫描的，进不去的文件夹没算进来，这些文件夹看起来变小不一定是真的变小') })
        }
    } else { $script:growNote = (T '这是第一次扫描这块盘。下次再扫描，就能看到哪些文件夹变大了') }
    if ($days -gt 0 -and $file) { $script:growNote = ((T "和 {0} 的快照比。") -f (Split-Path $file -Leaf)) + $script:growNote }
}

# 删除：移到回收站或永久删除，都要先勾选确认
$ctl.BtnMapDelete.Add_Click({ Start-MapDelete @($ctl.MapList.SelectedItems) })
Register-BgJob 'mapdel' -Cancel dupdel -Done {
    $res = $sync.MapDel
    $okSet = @{}; if ($res) { foreach ($p in $res.Ok) { $okSet[([string]$p).ToLowerInvariant()] = $true } }
    foreach ($r in @($script:mapDelRows)) {
        if (-not $okSet.ContainsKey(([string]$r.Path).ToLowerInvariant())) { continue }
        if ($r.Node) { [DiskMap]::Detach($r.Node) }
        else {
            $pn = [DiskMap]::Find($script:mapRoot, (Split-Path $r.Path -Parent))
            if ($pn) { [DiskMap]::DropFile($pn, $r.Size, $r.Disk, [bool]$r.Shared) }
            [DiskMap]::ForgetFile($r.Path)
        }
    }
    $nOk = $okSet.Count; $fails = @(); if ($res) { $fails = @($res.Fail) }
    $one = (@($script:mapDelRows).Count -eq 1)
    $txt = if ($sync.WasCancelled) { (T "已中途取消，删除了 {0} 项") -f $nOk } elseif ($fails.Count -eq 0) { $(if ($one) { (T "已删除 {0}") -f @($script:mapDelRows)[0].Name } else { (T "已删除 {0} 项") -f $nOk }) } elseif ($nOk -eq 0) { (T '没有删掉') } else { (T "删除了 {0} 项，{1} 项没删掉") -f $nOk, $fails.Count }
    # 实际多出来多少空间（删前删后各问一次 Windows）；删掉的从待删清单里拿掉
    $gain = @(foreach ($d in @($script:mapDelFree.Keys)) { $g = (DriveFree ($d + '\')) - [double]$script:mapDelFree[$d]; if ($g -ge 10MB) { (T "{0} 多出 {1}") -f $d, (Fmt $g) } })
    if ($gain.Count -gt 0) { $txt += (T '，') + ($gain -join (T '，')) }
    foreach ($k in @($okSet.Keys)) { $kk = $k.TrimEnd(''); if ($script:mapMarks.Contains($kk)) { $script:mapMarks.Remove($kk) } }
    Update-MapMarks
    End-Op $txt
    if ($nOk -gt 0) { if ($script:mapView -eq 'files') { Show-MapFiles } elseif ($script:mapView -ne 'grow') { Show-MapLevel $script:mapCur } }
    if ($fails.Count -gt 0) {
        $script:pendingDialog = @{ Title = $(if ($nOk -eq 0) { (T '没有删掉') } else { (T '有的没有删掉') }); Kind = 'warn'; Items = @($fails | Select-Object -First 20)
            Text = (T '下面这些没有删掉。正被别的程序打开的文件，关掉那个程序后再删一次。') }
    }
}
# 删除空间地图里的几行（下面的按钮删选中的；右键菜单删右键点到的）
function Start-MapDelete($sel) {
    if ($script:worker) { return }
    $sel = @($sel)
    $rows = @($sel | Where-Object { -not $_.Locked -and $_.Size -gt 0 })
    if ($rows.Count -eq 0) { return }
    foreach ($r in $rows) { $why = Get-DeleteBlock $r.Path; if ($why) { Show-Sheet -Kind warn -Title (T '这一项不能删') -Text ("{0}`n`n{1}" -f $r.Path, $why) | Out-Null; return } }
    # 读文件表能看到没有权限打开的文件夹：打不开的不删（看不到里面有什么）
    foreach ($r in @($rows | Where-Object { $_.IsDir })) {
        $lp = [string]$r.Path; if ($lp.Length -ge 248 -and -not $lp.StartsWith('\\')) { $lp = '\\?\' + $lp }
        $ok = $true; try { $en = [IO.Directory]::EnumerateFileSystemEntries($lp).GetEnumerator(); [void]$en.MoveNext(); $en.Dispose() } catch { $ok = $false }
        if (-not $ok) { Show-Sheet -Kind warn -Title (T '这一项不能删') -Text ("{0}`n`n{1}" -f $r.Path, (T '没有权限打开这个文件夹，看不到里面有什么，不删。')) | Out-Null; return }
    }
    $bytes = [double]0; foreach ($r in $rows) { $bytes += [double]$r.Size }
    # 快速扫描时知道实际占用和硬链接：说清楚真正能腾出多少
    $real = ''
    if ($script:mapRoot -and $script:mapRoot.HasDisk -and (Get-Flag 'MapDisk')) {
        $dk = [double]0; $sh = [double]0; $known = $true
        foreach ($r in $rows) {
            if ($r.Disk -lt 0) { $known = $false; break }
            $dk += [double]$r.Disk
            if ($r.Node) { $sh += [math]::Min([double]$r.Node.Shared, [double]$r.Node.Disk) }
            elseif ($r.Shared) { $sh += [double]$r.Disk }
        }
        if ($known) {
            if ($sh -ge 32MB) { $real += ((T "`n`n按快速扫描的结果，实际能腾出 {0} 到 {1}：其中 {2} 是硬链接，同一份文件在别处还有名字，那些名字还在就不会腾出空间。") -f (Fmt ([math]::Max([double]0, $dk - $sh))), (Fmt $dk), (Fmt $sh)) }
            elseif (($bytes - $dk) -ge 32MB -and $dk -lt $bytes * 0.85) { $real += ((T "`n`n按快速扫描的结果，这些实际只占 {0}（压缩、稀疏或只在云端的文件比文件大小占得少），删掉腾出的是这么多。") -f (Fmt $dk)) }
        }
    }
    $how = (T "「移到回收站」可以恢复，但要清空回收站后才真正腾出空间；「永久删除」马上腾出空间，删了就找不回来。")
    # 是 git 仓库的文件夹：里面没提交、没推送的改动删了就没了（参考 disktree）
    $git = @($rows | Where-Object { $_.IsDir -and ((Test-Path -LiteralPath (Join-Path ([string]$_.Path) '.git')) -or $_.Name -ieq '.git') })
    if ($git.Count -gt 0) { $real += ((T "`n`n注意：其中 {0} 个是 git 仓库（{1}）。没提交、没推送到远程的改动删了就找不回来，先确认都推送过。") -f $git.Count, ((@($git | Select-Object -First 3 | ForEach-Object { $_.Name })) -join (T '、'))) }
    $items = $null
    if ($rows.Count -eq 1) {
        $r = $rows[0]
        $kind = if ($r.IsDir) { (T '文件夹') } else { (T '文件') }
        $title = (T "删除这个{0}（{1}）？") -f $kind, $r.SizeText
        $text = ((T "{0}`n`n「移到回收站」可以恢复，但要清空回收站后才真正腾出空间；「永久删除」马上腾出空间，删了就找不回来。") -f $r.Path) + $real
    } else {
        $title = (T "删除选中的 {0} 项（{1}）？") -f $rows.Count, (Fmt $bytes)
        $text = $how + $real
        if ($sel.Count -gt $rows.Count) { $text += ((T "`n`n另有 {0} 项带小锁或是链接，不会删。") -f ($sel.Count - $rows.Count)) }
        $items = @($rows | Select-Object -First 40 | ForEach-Object { (T "{0}（{1}）") -f $_.Path, $_.SizeText })
        if ($rows.Count -gt 40) { $items += ((T "……另有 {0} 项") -f ($rows.Count - 40)) }
    }
    $ans = Show-Sheet -Kind danger -Title $title -Text $text -Items $items `
        -Confirm (T '我已确认这些资料不再需要，删除不会给我带来损失；因删除造成的后果由我自己承担。') -Buttons @((T '取消'), (T '永久删除'), (T '移到回收站')) -Destructive (T '永久删除') -Primary (T '移到回收站') -Cancel (T '取消')
    if ($ans -ne (T '移到回收站') -and $ans -ne (T '永久删除')) { return }
    Use-BgJob 'mapdel'; $sync.MapDel = $null
    $script:mapDelRows = $rows
    $script:mapDelFree = @{}; foreach ($d in @($rows | ForEach-Object { ([string]$_.Path).Substring(0, 2).ToUpperInvariant() } | Select-Object -Unique)) { $script:mapDelFree[$d] = DriveFree ($d + '\') }
    Start-Op $(if ($rows.Count -eq 1) { (T "删除 {0}") -f $rows[0].Name } else { (T "删除 {0} 项") -f $rows.Count })
    UI-Busy $true
    Start-Worker @'
$res = @{ Ok = New-Object System.Collections.ArrayList; Fail = New-Object System.Collections.ArrayList }
$how = if ($arg.Recycle) { (T '空间地图：移到回收站') } else { (T '空间地图：永久删除') }
$i = 0
foreach ($x in $arg.Items) {
    if (Stopping) { break }
    $i++
    $p = [string]$x.Path
    SetP @{ Steps = $arg.Items.Count; Step = $i; StepName = (Split-Path $p -Leaf); SubKind = 'action'; SubStart = (Get-Date); Detail = $p }
    # 删之前再查一次（个人文件夹、系统位置、软件安装文件夹、搬家后的数据、链接一律不删），删完核对、写操作日志：都在 Invoke-SafeRemove 里
    $bytes = if ($arg.Recycle -and $x.IsDir) { try { [double][FsTools]::OnDiskTree($p) } catch { [double]$x.Size } } else { [double]$x.Size }
    $r = Invoke-SafeRemove -Path $p -Scope pick -How $(if ($arg.Recycle) { 'recycle' } else { 'delete' }) -Bytes $bytes -What $how -Detail (GB $x.Size)
    if ($r.Ok) { [void]$res.Ok.Add($p) }
    elseif ($r.Stage -eq 'recycle') { [void]$res.Fail.Add(((T "{0}：{1}。要删的话选「永久删除」") -f $p, $r.Why)) }
    else { [void]$res.Fail.Add(((T "{0}：{1}") -f $p, $r.Why)) }
}
$sync.MapDel = $res
'@ @{ Items = @($rows | ForEach-Object { @{ Path = [string]$_.Path; IsDir = [bool]$_.IsDir; Size = [double]$_.Size } }); Recycle = ($ans -eq (T '移到回收站')) }
}

Register-BgJob 'fcompress' -Cancel fcompress -Done {
    $x = $sync.FcResult
    if ($x) {
        $saved = [math]::Max([double]0, $x.Before - $x.After)
        End-Op ($(if ($x.Cancelled) { (T "已中途取消，省了 {0}") } else { (T "完成，省了 {0}") }) -f (Fmt $saved))
        $ctl.SaveFcState.Text = (T "上次压缩：{0}，实际占用 {1} → {2}，省了 {3}") -f $x.Path, (Fmt $x.Before), (Fmt $x.After), (Fmt $saved)
        $script:pendingDialog = @{ Title = $(if ($x.Cancelled) { (T '压缩已中途取消') } else { (T '压缩完成') }); Kind = 'done'; Text = ((T "{0}`n`n实际占用 {1} → {2}，省了 {3}。文件照常使用。") -f $x.Path, (Fmt $x.Before), (Fmt $x.After), (Fmt $saved)) + $(if ($x.Cancelled) { (T "`n`n已经压缩的文件保持压缩，剩下的没压缩。想压缩剩下的，再压缩一次这个文件夹就好。") } else { '' }) }
    } else { End-Op (T '没有完成') }
}
# 压缩文件夹（NTFS）：空间地图和「省空间」页共用
function Start-FolderCompress([string]$path) {
    if ($script:worker) { return }
    $why = Get-CompressBlock $path
    if ($why) { Show-Sheet -Kind warn -Title (T '这个文件夹不适合这样压缩') -Text $why | Out-Null; return }
    $ans = Show-Sheet -Title (T '压缩这个文件夹？') -Text ((T "{0}`n`n用 Windows 自带的 NTFS 压缩：文件照常打开、照常修改，只是占的空间变小。文档、代码、日志通常能省一半；照片、视频、压缩包几乎省不了。文件多的话要几分钟。") -f $path) -Buttons @((T '取消'), (T '压缩')) -Primary (T '压缩') -Cancel (T '取消')
    if ($ans -ne (T '压缩')) { return }
    Use-BgJob 'fcompress'; $sync.FcResult = $null
    Start-Op (T '压缩文件夹')
    UI-Busy $true
    Start-Worker @'
$p = $arg.Path; $cx = $false
SetP @{ Steps = 2; Step = 1; StepName = (T '统计压缩前的实际占用'); SubKind = 'action'; SubStart = (Get-Date); Detail = $p }
$before = [double][FsTools]::OnDiskTree($p)
SetP @{ Step = 2; StepName = (T '压缩'); SubStart = (Get-Date); Detail = ((T "正在压缩 {0}") -f $p) }
if (-not (Test-Path -LiteralPath $p -PathType Container)) { Log ((T "  文件夹不在了：{0}") -f $p) }
else {
    $inside = $false
    try { Set-Location -LiteralPath $p -ErrorAction Stop; $inside = ((Get-Location).ProviderPath.TrimEnd('\') -ieq $p.TrimEnd('\')) } catch { Log ((T "  进不去：{0}") -f $p) }
    if ($inside) {
        $rc = Invoke-Tool "$sys32\compact.exe" @('/c', '/s', '/a', '/i', '/q', '*') $p
        if ($rc.Cancelled) { $cx = $true; Log ((T "  已中途取消：{0}") -f $p) }
        # 虚拟磁盘文件压缩后会变慢、甚至出错，压完再把它们解压回去（中途取消了也要做，这一步不能中断）
        Set-CanCancel $false
        & "$sys32\compact.exe" /u /s /a /i /q '*.vhd' '*.vhdx' '*.avhdx' 2>&1 | Out-Null
        Set-CanCancel $true
    }
}
try { [Environment]::CurrentDirectory = $env:SystemRoot; Set-Location -LiteralPath $env:SystemRoot } catch {}
$after = [double][FsTools]::OnDiskTree($p)
OpLog '压缩' $(if ($cx) { (T '压缩文件夹（NTFS），中途取消') } else { (T '压缩文件夹（NTFS）') }) $p ((T "实际占用 {0} → {1}") -f (GB $before), (GB $after))
$sync.FcResult = @{ Path = $p; Before = $before; After = $after; Cancelled = $cx }
'@ @{ Path = $path }
}
$ctl.BtnMapCompress.Add_Click({ $r = $ctl.MapList.SelectedItem; if ($r -and $r.IsDir) { Start-FolderCompress $r.Path } })

# ------------------------------------------------------------
# 搬家管理
# ------------------------------------------------------------
$script:moveRows = $null
Register-BgJob 'movesize' -ReadOnly -Done {
    $t = $sync.MoveTotal
    if ($t -and $script:moveRows) { Set-DoneInfo ((T "共 {0} 个文件夹，其中 {1} 个正常，已经帮 C 盘腾出约 {2}。") -f $script:moveRows.Count, $t.Count, (Fmt $t.Bytes)) }
    if ($script:candPending) { $script:runAfterCand = $true }
}
function Load-Moves {
    $script:movedTargets = $null
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[MoveRow]'
    foreach ($rec in (Get-MoveRecords)) {
        $st = Get-MoveState $rec
        if ($st.State -eq 'gone') { continue }
        $r = New-Object MoveRow
        $r.Name = $rec.Name; $r.Src = $rec.Src; $r.Dst = $rec.Dst; $r.State = $st.State
        $r.Status = $st.Text; $r.StatusBrush = $st.Brush
        $r.CanBack = ($st.State -eq 'ok'); $r.CanDrop = ($st.State -eq 'pending')
        $r.CanFix = (($st.State -eq 'broken' -and $st.Fix) -or $st.State -eq 'nosrc'); $r.FixTarget = [string]$st.Fix
        if (-not (Test-Path -LiteralPath $r.Dst)) { $r.SizeText = '—' }
        $col.Add($r)
    }
    $script:moveRows = $col
    $ctl.MovesList.ItemsSource = $col
    $ctl.EmptyMoves.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    Set-NavCount 'MovesTabDone' $col.Count
    Set-DoneInfo $(if ($col.Count -gt 0) { (T "共 {0} 个文件夹，正在统计大小…") -f $col.Count } else { (T '还没有搬过文件夹。') })
    if ($col.Count -gt 0 -and -not $script:worker) {
        Use-BgJob 'movesize'
        UI-Busy $true
        Start-Worker @'
$tot = [double]0; $n = 0
foreach ($r in $arg.Rows) {
    if (-not (Test-Path -LiteralPath $r.Dst)) { continue }
    $b = Est-Bytes $r.Dst (Get-DriveTree $r.Dst)   # 目标盘的文件表读一次，所有搬走的文件夹都从里面查
    $r.Size = [long]$b; $r.SizeText = GB $b
    if ($r.State -eq 'ok') { $tot += $b; $n++ }
}
$sync.MoveTotal = @{ Bytes = $tot; Count = $n }
'@ @{ Rows = @($col) }
    }
    elseif ($script:candPending -and -not $script:worker) { Start-CandScan }
}
# ---------- 可以搬的：C 盘上还没搬的聊天记录、装在 C 盘的软件、其他大文件夹 ----------
$script:candRows = $null; $script:candList = $null; $script:candScanned = $false; $script:candPending = $false; $script:runAfterCand = $false
$script:movesTab = 'cand'; $script:candInfo = ''; $script:doneInfo = ''; $script:storeChat = @(); $script:candSeen = -1
function Set-DoneInfo([string]$t) { $script:doneInfo = $t; if ($script:movesTab -eq 'done') { $ctl.MovesInfo.Text = $t } }
function Set-CandInfo([string]$t) { $script:candInfo = $t; if ($script:movesTab -eq 'cand') { $ctl.MovesInfo.Text = $t } }
function Set-MovesTab([string]$t) {
    $script:movesTab = $t
    $c = ($t -eq 'cand')
    $ctl.CandList.Visibility = if ($c) { 'Visible' } else { 'Collapsed' }
    $ctl.EmptyCand.Visibility = if ($c -and -not ($script:candRows -and $script:candRows.Count -gt 0)) { 'Visible' } else { 'Collapsed' }
    $ctl.MovesCard.Visibility = if ($c) { 'Collapsed' } else { 'Visible' }
    Update-HeadVis
    $ctl.CandBar.Visibility = if ($c) { 'Visible' } else { 'Collapsed' }
    $ctl.CandStore.Visibility = if ($c -and @($script:storeChat).Count -gt 0) { 'Visible' } else { 'Collapsed' }
    $ctl.MovesInfo.Text = if ($c) { $script:candInfo } else { $script:doneInfo }
    # 别处搬过、搬回过东西以后，切回来时重新看一遍
    if ($c -and -not $script:candScanned -and -not $script:worker -and $ctl.PageMoves.Visibility -eq 'Visible') { Start-CandScan }
}
# 目录上的数字
function Set-NavCount([string]$name, [int]$n) {
    $ctl[$name + 'N'].Text = [string]$n
    $ctl[$name + 'B'].Visibility = if ($n -gt 0) { 'Visible' } else { 'Collapsed' }
}
# 「可以搬的」下面一次只看一类：聊天记录、装在 C 盘的软件、其他可搬的文件夹、不适合搬的软件（空 = 全部）
$script:candGroup = ''
function Set-CandGroup([string]$g) {
    $script:candGroup = $g
    $cfg = $script:sortCfg['CandList']
    if ($cfg) { $cfg.Filter = if ($g) { [Predicate[object]]{ param($o) [string]$o.Group -eq $script:candGroup } } else { $null } }
    Apply-ListSort 'CandList'
    $ctl.BtnCandAll.IsEnabled = ($g -ne 'other' -and $g -ne 'blocked')
    if ($script:movesTab -ne 'cand') { Set-MovesTab 'cand' }
}
$ctl.MovesTabCand.Add_Checked({ Set-CandGroup '' })
foreach ($n in 'MNavChat', 'MNavApp', 'MNavOther', 'MNavBlocked') { $ctl[$n].Add_Checked({ Set-CandGroup ([string]$this.Tag) }) }
$ctl.MovesTabDone.Add_Checked({ Set-MovesTab 'done' })

Register-BgJob 'movescan' -Cancel look -ReadOnly -Done {
    End-Op $(if ($sync.WasCancelled) { (T '已中途取消') } else { (T '完成') })
    if ($sync.WasCancelled -or $null -eq $sync.CandResult) {
        $script:candScanned = $false
        $ctl.EmptyCandText.Text = (T '已取消。点右上角「刷新」重新看。')
        Set-CandInfo (T '已取消，没有看完。')
        if ($script:movesTab -eq 'cand') { $ctl.EmptyCand.Visibility = 'Visible' }
    } else {
        $script:storeChat = @($sync.CandStore)
        $ctl.CandStoreText.Text = if ($script:storeChat.Count -gt 0) { (T "{0} 是从应用商店装的，由 Windows 管理，本工具不搬。可以在 Windows 设置 → 应用 → 已安装的应用 里点它右边的「…」→「移动」，连同数据换到其他盘（要这个应用支持）。") -f ($script:storeChat -join (T '、')) } else { '' }
        Build-CandRows $sync.CandResult
        Set-MovesTab $script:movesTab
    }
}
function Start-CandScan {
    if ($script:worker) { return }
    $script:candPending = $false; $script:candScanned = $true
    $ctl.CandList.ItemsSource = $null; $script:candRows = $null
    $ctl.EmptyCandText.Text = (T '正在看 C 盘上还有什么能搬…')
    if ($script:movesTab -eq 'cand') { $ctl.EmptyCand.Visibility = 'Visible' }
    Set-CandInfo (T '正在看 C 盘上还有什么能搬，统计大小要一会儿…')
    foreach ($k in 'MovesTabCand', 'MNavChat', 'MNavApp', 'MNavOther', 'MNavBlocked') { Set-NavCount $k 0 }
    Use-BgJob 'movescan'; $sync.CandResult = $null; $sync.CandStore = $null
    Start-Op (T '看看 C 盘上还有什么能搬') -NoCard
    UI-Busy $true
    Start-Worker @'
$out = New-Object System.Collections.ArrayList
Start-Phases
# 系统服务和驱动（WMI）、已装的软件、应用商店里的聊天软件：另外开后台同时读，这边先统计聊天记录这些
$par = Start-Parallel ([ordered]@{ svc = 'Get-ServicePaths'; apps = 'Get-InstalledApps -NoStore'; store = 'Get-StoreChatApps' }) 3
$cat = @(Get-Catalog | Where-Object { ($_.Kind -eq 'move' -or $_.Kind -eq 'flex') -and $_.Paths })
Mark-Phase 'catalog'
# 上次搬了一半的（目标盘上已经有副本），这次再搬只补差异
$partial = @{}
foreach ($root in (All-MoveRoots)) { foreach ($pr in (Read-MoveMapPairs $root)) { $partial[([string]$pr[0]).TrimEnd('\').ToLowerInvariant()] = $true } }
$catKeys = @()
$steps = $cat.Count + 3; $step = 1
SetP @{ Steps = $steps; Step = 1; StepName = (T '读取 C 盘的文件表') }
$tree = Get-SysTree
Mark-Phase 'MFT'
foreach ($c in $cat) {
    if (Stopping) { break }
    $step++
    SetP @{ Steps = $steps; Step = $step; StepName = $c.N; SubKind = 'measure'; SubStart = (Get-Date); Detail = (T '统计大小') }
    $paths = @(); $bytes = [double]0; $isPartial = $false
    foreach ($p in $c.Paths) {
        if (-not $p) { continue }
        $catKeys += $p.TrimEnd('\').ToLowerInvariant()
        if (-not $p.StartsWith("$env:SystemDrive\", [StringComparison]::OrdinalIgnoreCase)) { continue }   # 比如「文档」已经改到 D 盘
        if (-not (Test-Path -LiteralPath $p -PathType Container)) { continue }
        if ($c.NoOneDrive -and $p -like '*OneDrive*') { continue }
        if ((IsLink $p) -or (Get-LinkedAncestor $p)) { continue }
        $b = Est-Bytes $p $tree
        if (Stopping) { break }
        $paths += $p; $bytes += $b
        if ($partial.ContainsKey($p.TrimEnd('\').ToLowerInvariant())) { $isPartial = $true }
    }
    if ($sync.WasCancelled) { break }
    if (-not $paths -or $bytes -lt 1MB) { continue }
    [void]$out.Add(@{ Type = 'cat'; Idx = $c.Idx; Name = $c.N; G = $c.G; Paths = $paths; Bytes = $bytes; Note = $c.Note; Apps = @($c.Apps); Partial = $isPartial; Measured = $true })
}
if (-not $sync.WasCancelled) {
    $step++
    SetP @{ Step = $step; StepName = (T '读取装在 C 盘的软件'); SubKind = 'action'; SubStart = (Get-Date); Detail = (T '读取已安装的软件和系统服务') }
    Mark-Phase 'chat and other folders'
    $got = Wait-Parallel $par
    Mark-Phase 'wait for services, apps, Store'
    if ($script:phList) { foreach ($k in @($got.Keys)) { [void]$script:phList.Add(@{ N = "$k (alongside)"; Ms = [double]$got[$k].Ms }) } }
    $apps = if ($got.ContainsKey('apps')) { $got.apps.V } else { Get-InstalledApps -NoStore }
    $svc = if ($got.ContainsKey('svc')) { $got.svc.V } else { Get-ServicePaths }
    $sd = $env:SystemDrive
    $onC = @($apps | Where-Object { $_.Location -and $_.Location.StartsWith("$sd\", [StringComparison]::OrdinalIgnoreCase) })
    $step++; $n = 0; $seenLoc = @{}
    foreach ($a in $onC) {
        if (Stopping) { break }
        $n++
        $loc = ([string]$a.Location).TrimEnd('\')
        if ($seenLoc.ContainsKey($loc.ToLowerInvariant())) { continue }   # 注册表里同一个文件夹登记了两次
        $seenLoc[$loc.ToLowerInvariant()] = $true
        if (-not (Test-Path -LiteralPath $loc -PathType Container)) { continue }
        if ((IsLink $loc) -or (Get-LinkedAncestor $loc)) { continue }
        # 和「聊天记录」等项目是同一个文件夹（或互相包含）的，只列一次
        $lk = $loc.ToLowerInvariant(); $dup = $false
        foreach ($k in $catKeys) { if ($lk -eq $k -or $lk.StartsWith($k + '\') -or $k.StartsWith($lk + '\')) { $dup = $true; break } }
        if ($dup) { continue }
        SetP @{ StepName = ((T "检查软件：{0}") -f $a.Name); SubKind = 'measure'; SubStart = (Get-Date); Detail = ((T "{0} / {1}") -f $n, $onC.Count) }
        $why = Get-AppMoveBlock $a $apps $svc
        $bytes = [double]$a.Est; $measured = $false
        if (-not $why) { $bytes = Est-Bytes $loc $tree; $measured = $true; if (Stopping) { break } }
        if ($bytes -lt 1MB) { continue }
        [void]$out.Add(@{ Type = 'app'; Idx = 0; Name = $a.Name; Location = $loc; Paths = @($loc); Bytes = $bytes; Publisher = $a.Publisher; Version = $a.Version
            Block = $why; Partial = $partial.ContainsKey($lk); Measured = $measured })
    }
    Mark-Phase 'apps on C:'
    if (-not $sync.WasCancelled) { $sync.CandStore = if ($got.ContainsKey('store')) { @($got.store.V) } else { Get-StoreChatApps } }
} else { [void](Wait-Parallel $par) }
End-Phases
$sync.CandResult = $out
'@ $null
}

function Build-CandRows($list) {
    $script:candList = $list
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[CandRow]'
    $gText = @{
        app     = (T '装在 C 盘的软件（整个安装文件夹搬走，快捷方式、卸载和自动更新照常可用，不用重装）')
        blocked = (T '不适合搬的软件（原因写在每一项下面；不用的可以到「软件管理」里卸载）')
    }
    $order = @{ chat = 0; app = 1; other = 2; blocked = 3 }
    $chatG = $null
    foreach ($c in $catalog) { if ($c.Apps) { $chatG = $c.G; break } }
    $items = @()
    foreach ($x in @($list)) {
        $g = if ($x.Type -eq 'app') { if ($x.Block) { 'blocked' } else { 'app' } } elseif ($x.G -eq $chatG) { 'chat' } else { 'other' }
        if ($g -eq 'blocked' -and [double]$x.Bytes -lt 100MB) { continue }
        $items += [pscustomobject]@{ O = $order[$g]; B = [double]$x.Bytes; G = $g; X = $x }
    }
    $seen = @{}
    foreach ($e in @($items | Sort-Object @{ Expression = 'O' }, @{ Expression = 'B'; Descending = $true })) {
        $g = $e.G; $x = $e.X
        $r = New-Object CandRow
        $r.Type = $x.Type; $r.Idx = [int]$x.Idx; $r.Name = $x.Name; $r.Size = [long]$x.Bytes
        $r.Key = if ($x.Type -eq 'app') { 'a:' + $x.Location.ToLowerInvariant() } else { 'c:' + $x.Idx }
        $r.SizeText = $(if ($x.Measured) { '' } else { (T '约 ') }) + (Fmt ([double]$x.Bytes))
        $r.PathText = (@($x.Paths) -join (T '；'))
        $r.Location = if ($x.Type -eq 'app') { $x.Location } else { [string]@($x.Paths)[0] }
        $r.Apps = [string[]]@($x.Apps)
        $r.CanMove = ($g -ne 'blocked'); $r.Partial = [bool]$x.Partial
        if ($x.Type -eq 'app') {
            $meta = @(); if ($x.Publisher) { $meta += $x.Publisher }; if ($x.Version) { $meta += ((T '版本 ') + $x.Version) }
            $r.Note = if ($x.Block) { [string]$x.Block } else { $meta -join ' · ' }
        } else { $r.Note = [string]$x.Note }
        if ($x.Partial -and $r.CanMove) { $r.Status = (T '上次已经复制过一部分，这次只补有变化的文件'); $r.StatusBrush = '#0A6ED1' }
        $gt = if ($g -eq 'chat' -or $g -eq 'other') { T ([string]$x.G) } else { $gText[$g] }
        $gp = $gt.Split([char]0xFF08, 2); if ($gp.Count -lt 2) { $gp = $gt.Split([char]'(', 2) }
        $r.Group = $g; $r.GroupOrder = [int]$order[$g]; $r.GroupTitle = $gp[0].Trim()
        $r.GroupNote = if ($gp.Count -gt 1) { $gp[1].TrimEnd([char]0xFF09).TrimEnd(')') } else { '' }
        $r.First = -not $seen.ContainsKey($g); $seen[$g] = $true
        $col.Add($r)
    }
    $script:candRows = $col
    $ctl.CandList.ItemsSource = $col
    $view = [System.Windows.Data.CollectionViewSource]::GetDefaultView($col)
    $view.GroupDescriptions.Clear()
    $view.GroupDescriptions.Add((New-Object System.Windows.Data.PropertyGroupDescription 'Group'))
    Update-CandInfo
}
function Update-CandInfo {
    $rows = @(); if ($script:candRows) { $rows = @($script:candRows | Where-Object { $_.CanMove }) }
    $tot = [double]0; foreach ($r in $rows) { $tot += [double]$r.Size }
    $nChat = @($rows | Where-Object { $_.Group -eq 'chat' }).Count; $nApp = @($rows | Where-Object { $_.Group -eq 'app' }).Count; $nOther = @($rows | Where-Object { $_.Group -eq 'other' }).Count
    $parts = @()
    if ($nChat) { $parts += ((T "聊天记录 {0} 项") -f $nChat) }
    if ($nApp) { $parts += ((T "软件 {0} 个") -f $nApp) }
    if ($nOther) { $parts += ((T "其他文件夹 {0} 项") -f $nOther) }
    if ($rows.Count -gt 0) {
        Set-CandInfo ((T "C 盘上还能搬走约 {0}：{1}。勾选后点右下角「搬到其他盘」。") -f (Fmt $tot), ($parts -join (T '、')))
    } else {
        Set-CandInfo (T 'C 盘上没找到还能搬的东西。')
    }
    Set-NavCount 'MovesTabCand' $rows.Count
    $all = @(); if ($script:candRows) { $all = @($script:candRows) }
    foreach ($p in @(@('MNavChat', 'chat'), @('MNavApp', 'app'), @('MNavOther', 'other'), @('MNavBlocked', 'blocked'))) {
        $c = @($all | Where-Object { $_.Group -eq $p[1] }).Count
        Set-NavCount $p[0] $c
        # 这一类没有东西就不列（正在看的那一类除外）
        $ctl[$p[0]].Visibility = if ($c -gt 0 -or $script:candGroup -eq $p[1]) { 'Visible' } else { 'Collapsed' }
    }
    $has = $script:candRows -and $script:candRows.Count -gt 0
    $ctl.EmptyCandText.Text = (T 'C 盘上没找到还能搬的东西：聊天记录和软件要么已经搬走，要么不在 C 盘。')
    if ($script:movesTab -eq 'cand') { $ctl.EmptyCand.Visibility = if ($has) { 'Collapsed' } else { 'Visible' } }
    Update-CandSel
}
function Update-CandSel {
    $sel = @(); if ($script:candRows) { $sel = @($script:candRows | Where-Object { $_.Checked -and $_.CanMove }) }
    $tot = [double]0; foreach ($r in $sel) { $tot += [double]$r.Size }
    $ctl.CandSel.Text = if ($sel.Count -gt 0) { (T "已选 {0} 项，约 {1}。") -f $sel.Count, (Fmt $tot) } else { (T '勾选要搬的项目。') }
    $ctl.BtnCandMove.IsEnabled = ($sel.Count -gt 0) -and -not $script:worker -and [bool](Get-Dest)
}
# 全选：聊天记录和软件（正在看其中一类时只选这一类）；「其他可搬的文件夹」要看清说明自己勾
$ctl.BtnCandAll.Add_Click({ if ($script:candRows) { foreach ($r in $script:candRows) { if ($r.CanMove -and $r.Group -ne 'other' -and (-not $script:candGroup -or $r.Group -eq $script:candGroup)) { $r.Checked = $true } } }; Update-CandSel })
$ctl.BtnCandNone.Add_Click({ if ($script:candRows) { foreach ($r in $script:candRows) { $r.Checked = $false } }; Update-CandSel })
$ctl.BtnCandStore.Add_Click({ [void](Open-AsUser 'ms-settings:appsfeatures') })
$ctl.CandList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $b = $e.OriginalSource
    if (-not ($b -is [System.Windows.Controls.Button]) -or -not ($b.Tag -is [CandRow])) { return }
    if ($b.Name -eq 'CandOpen') { Open-Location $b.Tag.Location }
})
# 按住鼠标左键上下拖：拖过的行一起勾上（从没勾的行开始拖）或一起取消（从勾着的行开始拖），像在资源管理器里拉框；
# 按在方框、「打开」按钮、滚动条上照常用；拖到列表上面或下面会自动滚动；不能搬的行不动
$script:cdrag = $null
$script:cdragTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:cdragTimer.Interval = [TimeSpan]::FromMilliseconds(50)
# 纵坐标 y 处是哪一行（返回这一行的数据；分组标题、空白处返回 $null）
function Get-CandRowAt([double]$y) {
    $lv = $ctl.CandList; $h = [double]$lv.ActualHeight; if ($h -le 4) { return $null }
    $yy = [math]::Min([math]::Max($y, 2.0), $h - 2.0)
    foreach ($dy in 0, -4, 4) {
        $hit = $lv.InputHitTest((New-Object System.Windows.Point ([math]::Max(40.0, [double]$lv.ActualWidth / 2)), ($yy + $dy)))
        if ($hit -is [System.Windows.DependencyObject]) {
            $c = $null; try { $c = [System.Windows.Controls.ItemsControl]::ContainerFromElement($lv, $hit) } catch {}
            if ($c -is [System.Windows.Controls.ListViewItem]) { return $c.Content }
        }
    }
    return $null
}
function Get-CandIndex($items, $row) { for ($k = 0; $k -lt $items.Count; $k++) { if ([object]::ReferenceEquals($items[$k], $row)) { return $k } }; return -1 }
function Set-CandRange($d, $row) {
    if (-not $row) { return }
    $i = Get-CandIndex $d.Items $row
    if ($i -lt 0 -or $i -eq $d.Cur) { return }
    $a = [math]::Min($d.Anchor, $i); $b = [math]::Max($d.Anchor, $i)
    for ($k = 0; $k -lt $d.Items.Count; $k++) {
        $r = $d.Items[$k]; if (-not $r.CanMove) { continue }
        $want = if ($k -ge $a -and $k -le $b) { [bool]$d.Want } else { [bool]$d.Snap[$k] }
        if ([bool]$r.Checked -ne $want) { $r.Checked = $want }
    }
    $d.Cur = $i
    Update-CandSel
}
function Stop-CandDrag {
    $d = $script:cdrag; $script:cdrag = $null
    $script:cdragTimer.Stop()
    if ($d -and $d.Cap -and $d.Cap.IsMouseCaptured) { $d.Cap.ReleaseMouseCapture() }
}
$ctl.CandList.Add_PreviewMouseLeftButtonDown({
    param($s, $e)
    Stop-CandDrag
    $src = $e.OriginalSource
    if ($src -isnot [System.Windows.DependencyObject]) { return }
    try {
        for ($v = $src; $v -and -not [object]::ReferenceEquals($v, $s); $v = [System.Windows.Media.VisualTreeHelper]::GetParent($v)) {
            if ($v -is [System.Windows.Controls.Primitives.ButtonBase] -or $v -is [System.Windows.Controls.Primitives.ScrollBar]) { return }   # 方框、按钮、滚动条照常用
            if ($v -is [System.Windows.Controls.ListViewItem]) { break }
        }
    } catch { return }
    $c = $null; try { $c = [System.Windows.Controls.ItemsControl]::ContainerFromElement($s, $src) } catch {}
    if ($c -isnot [System.Windows.Controls.ListViewItem]) { return }
    $r = $c.Content; if (-not $r -or -not $r.CanMove) { return }
    $items = [object[]]@($s.Items)
    $script:cdrag = @{ Items = $items; Anchor = (Get-CandIndex $items $r); Cur = (Get-CandIndex $items $r); Moved = $false; Want = -not [bool]$r.Checked; Snap = $null; Cap = $null }
})
$ctl.CandList.Add_PreviewMouseMove({
    param($s, $e)
    $d = $script:cdrag
    if (-not $d) { return }
    if ($e.LeftButton -ne [System.Windows.Input.MouseButtonState]::Pressed) { Stop-CandDrag; return }
    $r = Get-CandRowAt ($e.GetPosition($s).Y)
    if (-not $d.Moved) {
        if (-not $r -or (Get-CandIndex $d.Items $r) -eq $d.Anchor) { return }
        $d.Moved = $true
        $d.Snap = [bool[]]@($d.Items | ForEach-Object { [bool]$_.Checked })
        # 鼠标交给列表里的滚动区：拖到列表外面也收得到；起点这一行先跟着变
        $d.Cap = Find-Visual $s ([System.Windows.Controls.ScrollViewer]); if (-not $d.Cap) { $d.Cap = $s }
        [void]$d.Cap.CaptureMouse()
        $a = $d.Items[$d.Anchor]; if ([bool]$a.Checked -ne [bool]$d.Want) { $a.Checked = [bool]$d.Want }
        $script:cdragTimer.Start()
    }
    Set-CandRange $d $r
})
$ctl.CandList.Add_PreviewMouseLeftButtonUp({ if ($script:cdrag) { Stop-CandDrag } })
$ctl.CandList.Add_LostMouseCapture({ param($s, $e) $d = $script:cdrag; if ($d -and $d.Moved -and $d.Cap -and [object]::ReferenceEquals($e.OriginalSource, $d.Cap)) { $script:cdrag = $null; $script:cdragTimer.Stop() } })
$script:cdragTimer.Add_Tick({
    $d = $script:cdrag
    if (-not $d -or -not $d.Moved) { $script:cdragTimer.Stop(); return }
    if ([System.Windows.Input.Mouse]::LeftButton -ne [System.Windows.Input.MouseButtonState]::Pressed) { Stop-CandDrag; return }
    $lv = $ctl.CandList; $y = [System.Windows.Input.Mouse]::GetPosition($lv).Y; $h = [double]$lv.ActualHeight
    if ($y -ge 0 -and $y -le $h) { return }
    $sv = $d.Cap; if ($sv -isnot [System.Windows.Controls.ScrollViewer]) { return }
    $over = if ($y -lt 0) { -$y } else { $y - $h }
    $steps = [math]::Min(4, 1 + [int][math]::Floor($over / 30))
    for ($k = 0; $k -lt $steps; $k++) { if ($y -lt 0) { $sv.LineUp() } else { $sv.LineDown() } }
    $lv.UpdateLayout()
    Set-CandRange $d (Get-CandRowAt $y)
})
$ctl.BtnCandMove.Add_Click({ Start-MoveMany })

Register-BgJob 'movemany' -Cancel movemany -Moves -Done {
    $x = $sync.MmRes
    $after = [double](FreeC); $freed = [math]::Max([double]0, [double]($after - $script:mmFreeC0))
    $cx = [bool]$sync.WasCancelled
    $cardWasOpen = ($ctl.Overlay.Visibility -eq 'Visible')
    $head = (T "C 盘剩余：{0} → {1}，腾出了 {2}") -f (GB $script:mmFreeC0), (GB $after), (GB $freed)
    if ($cx) { $head = (T '已中途取消：还没开始的项目都没做，已经做完的不会撤销。') + "`n" + $head }
    $waitNote = ''
    if ([int]$sync.WaitCount -gt 0) { $waitNote = (T "有 {0} 个文件夹已经复制好，但原文件夹还被别的程序占着，没换成链接。彻底退出相关的软件（包括右下角托盘图标）后再搬一次，会接着用复制好的副本，很快完成。") -f [int]$sync.WaitCount; $head += "`n" + $waitNote }
    End-Op ($(if ($cx) { (T "已中途取消，腾出 {0}") } else { (T "完成，腾出 {0}") }) -f (GB $freed)) -KeepCard -headline $head -reportLines (Plan-Lines)
    # 搬好的从「可以搬的」里去掉，其余的保留这次的结果
    if ($x -and $x.Done -and $x.Done.Count -gt 0 -and $script:candList) {
        $gone = @{}; foreach ($k in $x.Done) { $gone[[string]$k] = $true }
        $keep = @($script:candList | Where-Object { $k = if ($_.Type -eq 'app') { 'a:' + ([string]$_.Location).ToLowerInvariant() } else { 'c:' + $_.Idx }; -not $gone.ContainsKey($k) })
        Build-CandRows $keep
        $script:candSeen = -1
    }
    if (-not $cardWasOpen) {
        $lines = @(); if ($x -and $x.Summary) { $lines = @($x.Summary) }
        $script:pendingDialog = @{ Title = $(if ($cx) { (T '已中途取消') } else { (T '搬家完成') }); Kind = $(if ($waitNote -or $cx) { 'warn' } else { 'done' }); Items = @($lines | Select-Object -First 22); Text = $head }
    }
    try { [System.Media.SystemSounds]::Asterisk.Play() } catch {}
    $script:pageLoaded.apps = $false
    $script:runAfterMoves = $true
    Fill-DestChoices
}
# 勾选的一起搬：先确认（列出每一项、要关掉的软件），再逐项复制、核对、换成链接
function Start-MoveMany {
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    $sel = @(); if ($script:candRows) { $sel = @($script:candRows | Where-Object { $_.Checked -and $_.CanMove }) }
    if ($sel.Count -eq 0) { return }
    $dest = Get-Dest
    if (-not $dest) { Show-Sheet -Kind warn -Title (T '没有可用的搬家目标') -Text (T '这台电脑没有 C 盘以外的硬盘，或者还没选搬家目标。') | Out-Null; return }
    $total = [double]0; $need = [double]0; foreach ($r in $sel) { $total += [double]$r.Size; if (-not $r.Partial) { $need += [double]$r.Size } }
    $free = DriveFree ($dest.Substring(0, 2))
    if ($free -gt 0 -and $free -lt $need + 1GB) {
        Show-Sheet -Kind warn -Title (T '目标盘放不下') -Text ((T "选中的一共约 {0}，{1} 只剩 {2}。少选几项，或者换一块空间更大的盘。") -f (Fmt $total), $dest.Substring(0, 2), (Fmt $free)) | Out-Null; return
    }
    # 给资源管理器装了右键菜单之类组件的软件，文件夹一直被占着，搬不了
    $exMods = @(); foreach ($p in @(Get-Process -Name explorer -ErrorAction SilentlyContinue)) { try { foreach ($m in $p.Modules) { $exMods += [string]$m.FileName } } catch {} }
    $blocked = @()
    foreach ($r in @($sel | Where-Object { $_.Type -eq 'app' })) {
        $pre = $r.Location.TrimEnd('\') + '\'
        if (@($exMods | Where-Object { $_.StartsWith($pre, [StringComparison]::OrdinalIgnoreCase) }).Count -gt 0) { $blocked += $r }
    }
    foreach ($r in $blocked) { $r.Checked = $false; $r.Status = (T '不适合搬：它给资源管理器装了右键菜单之类的组件，文件夹一直被占着'); $r.StatusBrush = '#B25000' }
    if ($blocked.Count -gt 0) { $sel = @($sel | Where-Object { $blocked -notcontains $_ }) }
    if ($sel.Count -eq 0) { Show-Sheet -Kind warn -Title (T '选中的软件不适合搬') -Text (T '它们给资源管理器装了右键菜单之类的组件，桌面和文件夹窗口一直开着这些文件，文件夹被占着，搬不了。') | Out-Null; return }
    $total = [double]0; foreach ($r in $sel) { $total += [double]$r.Size }
    # 要先关掉的软件
    $cat0 = @{}; foreach ($c in $catalog) { $cat0[$c.Idx] = $c }
    $need = @($sel | Where-Object { $_.Type -eq 'cat' } | ForEach-Object { @($cat0[$_.Idx].Apps) } | Where-Object { $_ } | Select-Object -Unique)
    $pv = @($sel | ForEach-Object { if ($_.Type -eq 'app') { @{ Kill = @(); KillDirs = @(); Paths = @($_.Location) } } else { $cat0[$_.Idx] } })
    $cp = Get-ClosePlan $pv $need
    $who = $cp.Text
    $text = (T "把下面 {0} 项搬到 {1}，一共约 {2}。每一项都先复制、核对两边一致，再把 C 盘上的原位置换成链接，删掉 C 盘上的那份；软件照常使用，以后可以在「已经搬走的」里搬回 C 盘。") -f $sel.Count, $dest, (Fmt $total)
    if ($who) { $text += ((T "`n`n{0} 正在运行，搬之前会替你关掉（包括屏幕右下角托盘里的）。没保存的内容请先保存。") -f $who) }
    $text += (T "`n`n要注意：目标盘要一直接着；不要删除、改名或移动目标盘上的 CDriveMoved 文件夹。")
    $enc = Get-EncryptionWarning $dest; if ($enc) { $text += "`n`n" + $enc }
    $pw = Get-PowerNote $total; if ($pw) { $text += "`n`n" + $pw }
    $items = @($sel | ForEach-Object { (T "{0}（{1}）") -f $_.Name, $_.SizeText })
    $btn = if ($who) { (T '关掉并搬走') } else { (T '搬到其他盘') }
    if ((Show-Sheet -Title ((T "把 {0} 项搬到其他盘？") -f $sel.Count) -Text $text -Items $items -Buttons @((T '取消'), $btn) -Primary $btn -Cancel (T '取消')) -ne $btn) { return }
    if ($script:worker) { return }
    $plan = @(); foreach ($r in $sel) { $plan += @{ Key = $r.Key; Type = $r.Type; Idx = $r.Idx; Name = $r.Name; Location = $r.Location; Bytes = [double]$r.Size; Note = $r.Note } }
    $allowed = @($cp.Names)
    $sync.Status = [hashtable]::Synchronized(@{}); $sync.StatusVer = 0; $script:statusSeen = -1; $script:candSeen = -1; $sync.WaitCount = 0
    foreach ($r in $sel) { $r.Status = (T '等待'); $r.StatusBrush = '#6E6E73' }
    $script:runPlan = @($plan | ForEach-Object { @{ Idx = $_.Key; Name = $_.Name } })
    $script:mmFreeC0 = [double](FreeC)
    Use-BgJob 'movemany'; $sync.MmRes = $null
    Start-Op ((T "搬 {0} 项到其他盘") -f $plan.Count); UI-Busy $true
    UI-Log ((T "搬家目标：{0}") -f $dest)
    Start-Worker @'
$dest = $arg.Dest
New-Item -ItemType Directory -Path $dest -Force | Out-Null
$cat = @{}; foreach ($it in (Get-Catalog)) { $cat[$it.Idx] = $it }
$summary = New-Object System.Collections.ArrayList
$doneKeys = New-Object System.Collections.ArrayList
$handled = @{}; $moved = [double]0; $i = 0
foreach ($p in $arg.Plan) {
    if (Stopping) { break }
    $i++
    SetP @{ Steps = $arg.Plan.Count; Step = $i; StepName = $p.Name; StepIdx = $p.Key; StepNote = $p.Note; MoveItem = $false
            SubKind = 'none'; SubDone = [double]0; SubTotal = [double]$p.Bytes; SubStart = (Get-Date); Detail = '' }
    SetStatus $p.Key (T '进行中…') 'run'
    Log ("[{0}] {1}" -f (T '搬到其他盘'), $p.Name)
    $res = @{ Done = 0; Fail = 0; Wait = 0; Moved = [double]0; Dest = @(); Msgs = @() }
    try {
        if ($p.Type -eq 'app') {
            $item = @{ N = $p.Name; Paths = @($p.Location); Apps = @(); Kill = @(); KillDirs = @()
                BusyHint = (T '还有程序开着里面的文件。请退出这个软件（包括屏幕右下角托盘里的图标），关掉打开着这个文件夹的窗口，再搬一次；已经复制好的部分下次直接用，很快') }
            $item.Restrict = $true; $item.Allowed = @($arg.Allowed)
            Invoke-AppMove $item $dest $res
        } else {
            $it = $cat[[int]$p.Idx]; $it.Restrict = $true; $it.Allowed = @($arg.Allowed)
            Invoke-Move $it $dest $res
        }
        if ($res.Wait -gt 0) { $sync.WaitCount = [int]$sync.WaitCount + $res.Wait }
        $rt = Move-ResultText $res; $t = $rt[0]; $k = $rt[1]
    } catch { $t = (T "出错：") + $_.Exception.Message; $k = 'fail'; Log "  $t" }
    SetStatus $p.Key $t $k
    $mark = switch ($k) { 'ok' { '✓' } 'warn' { '!' } 'fail' { '✗' } default { '·' } }
    [void]$summary.Add(((T "{0} {1}：{2}") -f $mark, $p.Name, $t))
    $handled[$p.Key] = $true
    if ($res.Done -gt 0) { $moved += [double]$res.Moved; if ($k -eq 'ok') { [void]$doneKeys.Add($p.Key) } }
}
if ($sync.WasCancelled) {
    foreach ($p in $arg.Plan) {
        if ($handled.ContainsKey($p.Key)) { continue }
        SetStatus $p.Key (T '已取消，没有处理') 'skip'
        [void]$summary.Add(((T "{0} {1}：{2}") -f '·', $p.Name, (T '已取消，没有处理')))
    }
}
$sync.MmRes = @{ Summary = $summary; Done = $doneKeys; Moved = $moved }
'@ @{ Plan = $plan; Dest = $dest; Allowed = $allowed }
}

$ctl.BtnMovesRefresh.Add_Click({ if (-not $script:worker) { $script:candPending = $true; Load-Moves } })
Register-BgJob 'moveback' -Cancel moveback -Moves -Done {
    $script:candScanned = $false; if ($ctl.PageMoves.Visibility -eq 'Visible') { $script:candPending = $true }
    $x = $sync.MoveRes
    $ok = $x -and $x.Ok
    $back = ($sync.Mode -eq 'moveback')
    $cx = $x -and $x.Cancelled -and -not $ok
    End-Op $(if ($ok) { (T '完成') } elseif ($cx) { (T '已取消') } else { (T '没有完成') })
    if ($ok) { $script:pendingDialog = @{ Title = $(if ($back) { (T '已搬回 C 盘') } else { (T '多余的副本已删除') }); Kind = 'done'; Text = $(if ($x.Msg) { $x.Msg } elseif ($back) { (T "搬回了 {0}，软件照常使用。") -f (Fmt $x.Bytes) } else { (T "腾出了 {0}。") -f (Fmt $x.Bytes) }) } }
    else { $script:pendingDialog = @{ Title = $(if ($cx) { (T '已取消') } else { (T '没有完成') }); Kind = $(if ($cx) { 'info' } else { 'warn' }); Text = $(if ($x) { $x.Msg } else { '' }) } }
    $script:runAfterMoves = $true
    Fill-DestChoices
}
Register-BgJob 'movedrop' -Done (Get-BgJob 'moveback').Done
$ctl.MovesList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param($s, $e)
    $b = $e.OriginalSource
    if (-not ($b -is [System.Windows.Controls.Button]) -or -not ($b.Tag -is [MoveRow])) { return }
    $r = $b.Tag
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    switch ($b.Name) {
        'MvOpen' { if (Test-Path -LiteralPath $r.Dst) { Open-Location $r.Dst } else { Open-Location $r.Src } }
        'MvFix' {
            $t = if ($r.FixTarget) { $r.FixTarget } else { $r.Dst }
            if ((Show-Sheet -Title (T '修复链接？') -Text ((T "让 C 盘上的 {0} 重新指向 {1}。修好后软件就能照常找到数据。") -f $r.Src, $t) -Buttons @((T '取消'), (T '修复')) -Primary (T '修复') -Cancel (T '取消')) -ne (T '修复')) { return }
            $res = @{}; Invoke-FixLink $r.Src $t $res
            if ($res.Ok) { Show-Sheet -Kind done -Title (T '链接已修复') -Text ("{0} → {1}" -f $r.Src, $t) | Out-Null } else { Show-Sheet -Kind warn -Title (T '没修好') -Text $res.Msg | Out-Null }
            Load-Moves
        }
        'MvDrop' {
            $ans = Show-Sheet -Kind danger -Title ((T "删除多余的副本（{0}）？") -f $r.SizeText) `
                -Text ((T "C 盘上的原文件夹 {0} 还在，软件用的是它；目标盘上的 {1} 是上次没搬完留下的副本。删掉它可以腾出目标盘的空间，C 盘不受影响。") -f $r.Src, $r.Dst) `
                -Confirm (T '我已确认 C 盘上的原文件夹还在，删掉这份副本不会给我带来损失。') -Buttons @((T '取消'), (T '删除副本')) -Primary (T '删除副本') -Cancel (T '取消')
            if ($ans -ne (T '删除副本')) { return }
            Use-BgJob 'movedrop'; $sync.MoveRes = $null
            Start-Op (T '删除多余的副本'); UI-Busy $true
            Start-Worker @'
SetP @{ Steps = 1; Step = 1; StepName = $arg.Rec.Dst; SubKind = 'action'; SubStart = (Get-Date) }
$res = @{}; Invoke-DropCopy $arg.Rec $res; $sync.MoveRes = $res
'@ @{ Rec = @{ Src = $r.Src; Dst = $r.Dst } }
        }
        'MvBack' {
            $free = [double](FreeC)
            $text = (T "把 {0} 复制回 C 盘的 {1}，核对一致后拆掉链接、换回真正的文件夹，最后删除目标盘上的那份。`n`nC 盘现在剩 {2}，这个文件夹约 {3}。") -f $r.Dst, $r.Src, (GB $free), $r.SizeText
            if ((Show-Sheet -Title ((T "把「{0}」搬回 C 盘？") -f $r.Name) -Text $text -Buttons @((T '取消'), (T '搬回')) -Primary (T '搬回') -Cancel (T '取消')) -ne (T '搬回')) { return }
            $rec = @{ Src = $r.Src; Dst = $r.Dst; Idx = 0 }; $apps = @()
            foreach ($c in $catalog) { if (@($c.Paths) -contains $r.Src) { $rec.Idx = $c.Idx; $apps = @($c.Apps) } }
            $cItem = @{ Kill = @(); KillDirs = @() }; foreach ($c in $catalog) { if ($c.Idx -eq $rec.Idx -and $rec.Idx) { $cItem = $c } }
            $cp = Get-ClosePlan @(@{ Kill = @($cItem.Kill); KillDirs = @($cItem.KillDirs); Paths = @($r.Src, $r.Dst) }) $apps
            $rec.Restrict = $true; $rec.Allowed = @($cp.Names)
            $inside = @($cp.Names)
            if ($inside.Count -gt 0 -and $cp.Text) { $inside = @($cp.Text) }
            if (-not $apps -and $inside.Count -gt 0) {
                $who = $inside -join (T '、')
                if ((Show-Sheet -Kind warn -Title ((T "需要先退出{0}") -f $who) -Text ((T "{0} 正在从这个文件夹运行，不退出的话没法搬回。点「退出并继续」会替你关掉它们（没保存的内容请先保存）。") -f $who) -Buttons @((T '取消'), (T '退出并继续')) -Primary (T '退出并继续') -Cancel (T '取消')) -ne (T '退出并继续')) { return }
            }
            if ($apps) {
                $busy = Get-BusyApps $apps
                if ($busy.Count -gt 0 -or $cp.Names.Count -gt 0) {
                    $who = $cp.Text
                    if ((Show-Sheet -Kind warn -Title ((T "需要先退出{0}") -f $who) -Text ((T "{0} 正在使用这个文件夹，不退出的话没法搬回。点「退出并继续」会替你关掉它们。") -f $who) -Buttons @((T '取消'), (T '退出并继续')) -Primary (T '退出并继续') -Cancel (T '取消')) -ne (T '退出并继续')) { return }
                }
            }
            Use-BgJob 'moveback'; $sync.MoveRes = $null
            Start-Op ((T "搬回 C 盘：{0}") -f $r.Name); UI-Busy $true
            Start-Worker @'
SetP @{ Steps = 1; Step = 1; StepName = $arg.Rec.Src }
$res = @{}; Invoke-MoveBack $arg.Rec $res; $sync.MoveRes = $res
'@ @{ Rec = $rec }
        }
    }
})

# ------------------------------------------------------------
# 省空间
# ------------------------------------------------------------
# ------------------------------------------------------------
# 系统健康：硬件、开机、蓝屏、活动监控、事件
# ------------------------------------------------------------
$script:healthData = $null
function Load-Health {
    $ctl.HealthNote.Text = if ($script:healthData) { (T '正在后台刷新，下面先显示上次读到的…') } else { (T '正在读取硬件、事件日志和转储文件，要几秒…') }
    $ctl.BtnHealthRefresh.IsEnabled = $false
    $ok = Start-BgEngine 'health' 'Get-HealthAll' $null {
        param($r, $err)
        $ctl.BtnHealthRefresh.IsEnabled = $true
        if (-not $r) { $ctl.HealthNote.Text = (T '没能读取：') + $err; return }
        $script:healthData = $r
        Show-Health $r
        Show-Verdicts $r
        Show-Fixes $r.Power
    }
    if (-not $ok) { $ctl.BtnHealthRefresh.IsEnabled = $true }
}
$ctl.BtnHealthRefresh.Add_Click({ Load-Health })
# 档位颜色：绿正常、橙留意、红有问题、灰读不到
$script:hcGreen = @('#1D7A35', '#E5F4E9'); $script:hcAmber = @('#995700', '#FFF1DB'); $script:hcRed = @('#C0101C', '#FDEBEC'); $script:hcGrey = @('#6E6E73', '#F0F0F3'); $script:hcBlue = @('#0A5BC4', '#E3EEFF')
function New-Chip([string]$text, $tier) { $c = New-Object HealthChip; $c.Text = $text; $c.Fg = $tier[0]; $c.Bg = $tier[1]; return $c }
function New-HealthCard([string]$title, [string]$sub, $tier) { $c = New-Object HealthCard; $c.Title = $title; $c.Sub = $sub; $c.Stripe = $tier[0]; $c.BarBrush = $tier[0]; return $c }
function Tier-Worst($a, $b) { $rank = @{ ($script:hcGrey[0]) = 0; ($script:hcGreen[0]) = 1; ($script:hcBlue[0]) = 1; ($script:hcAmber[0]) = 2; ($script:hcRed[0]) = 3 }; if ($rank[$b[0]] -gt $rank[$a[0]]) { $b } else { $a } }
# 空间地图上每块盘一张卡片：卡片一起排满这一排（每张至少 280、最多 560），盘多了就换行
$win.Resources['DcCardW'] = [double]300
function Update-DcCardW {
    $w = [double]$ctl.MapHealth.ActualWidth; if ($w -lt 100) { return }
    $n = @($ctl.MapHealth.ItemsSource).Count; if ($n -lt 1) { $n = 1 }
    $cols = [math]::Max(1, [math]::Min($n, [math]::Floor(($w + 1) / (280 + 12))))
    $cw = [math]::Min([double]560, [math]::Floor($w / $cols) - 12)
    if ([math]::Abs([double]$win.Resources['DcCardW'] - $cw) -lt 1) { return }
    $win.Resources['DcCardW'] = [double]$cw
    # 用量条的长度跟着卡片宽度变
    foreach ($c in @($ctl.MapHealth.ItemsSource)) { if ($c) { $c.BarW = [math]::Round(($cw - 34) * [double]$c.UsedPct / 100.0) } }
    try { $ctl.MapHealth.Items.Refresh() } catch {}
}
$ctl.MapHealth.Add_SizeChanged({ param($s, $e) if ($e.WidthChanged) { Update-DcCardW } })
# 硬件卡片的宽度跟着这一页的宽度走：每张至少 270，一排能放几张放几张，正好排满（最大化时右边不留空白，也不用往下拉很长）
$win.Resources['HcCardW'] = [double]290
# 卡片上的用量条按百分比画：卡片多宽，满格就多长
function Set-CardBar($card, [double]$pct) {
    $card.HasBar = $true; $card.BarPct = $pct
    $card.BarW = [math]::Max(2, ([double]$win.Resources['HcCardW'] - 33) * $pct / 100.0)
}
$ctl.HealthCards.Add_SizeChanged({
    param($s, $e)
    $w = [double]$s.ActualWidth; if ($w -lt 100) { return }
    $cols = [math]::Max(1, [math]::Floor(($w + 1) / (270 + 12)))
    $cw = [math]::Floor($w / $cols) - 12
    if ([math]::Abs([double]$win.Resources['HcCardW'] - $cw) -lt 1) { return }
    $win.Resources['HcCardW'] = [double]$cw
    $any = $false
    foreach ($c in @($ctl.HealthCards.ItemsSource)) { if ($c -and $c.HasBar) { $c.BarW = [math]::Max(2, ($cw - 33) * [double]$c.BarPct / 100.0); $any = $true } }
    if ($any) { try { $ctl.HealthCards.Items.Refresh() } catch {} }
})
# 事件的说明文字：一行一行合起来，太长的截到 300 字（完整的在鼠标提示里）
function Shorten-Note([string]$t) {
    if (-not $t) { return '' }
    $t = ($t -replace '\s*[\r\n]+\s*', ' ').Trim()
    if ($t.Length -gt 300) { $t = $t.Substring(0, 300) + '…' }
    return $t
}
function Show-Health($r) {
    $ctl.HealthNote.Text = (T "读取于 {0:HH:mm}，用了 {1:N0} 秒。读取只看不改；修复的按钮点了会先说明要改什么。") -f $r.At, $r.Secs
    $bad = @($r.Verdicts | Where-Object { $_.Level -eq 'red' })
    if ($bad.Count -gt 0 -and $ctl.HTabCrash.Visibility -eq 'Visible') { $ctl.HealthNote.Text += ' ' + ((T '发现 {0} 个要注意的问题：「{1}」，详情和修法在「蓝屏和崩溃」里。') -f $bad.Count, ((@($bad | ForEach-Object { $_.Title })) -join (T '」「'))) }
    $cards = New-Object 'System.Collections.ObjectModel.ObservableCollection[HealthCard]'
    # CPU
    $c = $r.Cpu
    if ($c.Ok) {
        $tier = $script:hcGreen
        $card = New-HealthCard (T 'CPU') $c.Name $tier
        if ($c.Load -ge 0) { $card.Chips.Add((New-Chip ((T "负载 {0}%") -f $c.Load) $(if ($c.Load -ge 90) { $script:hcAmber } else { $script:hcGreen }))); Set-CardBar $card $c.Load }
        if ($c.MaxMHz -gt 0) { $card.Chips.Add((New-Chip ("{0:N1} / {1:N1} GHz" -f ($c.MHz / 1000), ($c.MaxMHz / 1000)) $script:hcBlue)) }
        if ($c.Perf -ge 0) { $t2 = if ($c.Throttle) { $script:hcRed } elseif ($c.Perf -lt 90) { $script:hcAmber } else { $script:hcGreen }; $card.Chips.Add((New-Chip ((T "性能 {0}%") -f $c.Perf) $t2)); $tier = Tier-Worst $tier $t2 }
        if ($c.Temp -ne $null) { $t2 = if ($c.Temp -ge 90) { $script:hcRed } elseif ($c.Temp -ge 75) { $script:hcAmber } else { $script:hcGreen }; $card.Chips.Add((New-Chip ("{0} °C" -f $c.Temp) $t2)); $tier = Tier-Worst $tier $t2; if ($c.TempNote) { $card.Lines.Add($c.TempNote) } }
        else { $card.Chips.Add((New-Chip (T '温度读不到') $script:hcGrey)); $card.Lines.Add($c.TempWhy) }
        $card.Lines.Add(((T "{0} 核 {1} 线程") -f $c.Cores, $c.Threads) + $(if ($c.Throttle) { (T '。性能计数器持续低于标称频率：可能是散热或电源限制在降频') } else { '' }))
        $card.Stripe = $tier[0]; $card.BarBrush = $tier[0]
        $cards.Add($card)
    } else { $card = New-HealthCard (T 'CPU') (T '读不到') $script:hcGrey; $card.Lines.Add($c.Why); $cards.Add($card) }
    # 内存
    $m = $r.Mem
    if ($m.Ok) {
        $tier = switch ($m.Pressure) { 'high' { $script:hcRed } 'mid' { $script:hcAmber } default { $script:hcGreen } }
        $card = New-HealthCard (T '内存') ((T "{0} 已用 {1}，可用 {2}") -f (Fmt $m.Total), (Fmt ($m.Total - $m.Free)), (Fmt $m.Free)) $tier
        Set-CardBar $card $m.UsedPct
        $card.Chips.Add((New-Chip ((T "已用 {0}%") -f $m.UsedPct) $(if ($m.UsedPct -ge 92) { $script:hcRed } elseif ($m.UsedPct -ge 80) { $script:hcAmber } else { $script:hcGreen })))
        $card.Chips.Add((New-Chip ((T "提交 {0}%") -f $m.CommitPct) $(if ($m.CommitPct -ge 90) { $script:hcRed } elseif ($m.CommitPct -ge 75) { $script:hcAmber } else { $script:hcGreen })))
        if ($m.HardFaults -ge 0) { $card.Chips.Add((New-Chip ((T "硬错误 {0}/秒") -f $m.HardFaults) $(if ($m.HardFaults -ge 100) { $script:hcRed } elseif ($m.HardFaults -ge 20) { $script:hcAmber } else { $script:hcGreen }))) }
        if ($m.Whea -gt 0) { $card.Chips.Add((New-Chip ((T "WHEA 内存错误 {0} 次") -f $m.Whea) $script:hcRed)) }
        $card.Lines.Add(((T "提交 {0} / 上限 {1}（物理内存加页面文件）。") -f (Fmt $m.Commit), (Fmt $m.CommitLimit)) + $(switch ($m.Pressure) { 'high' { (T '内存很紧张：程序在频繁换到页面文件，会明显变慢') } 'mid' { (T '内存偏紧') } default { (T '内存够用') } }))
        if ($m.Whea -gt 0) { $card.Lines.Add((T '最近 30 天 Windows 记录过内存硬件错误（WHEA）：建议跑一次 Windows 内存诊断（mdsched）')) }
        $cards.Add($card)
    } else { $card = New-HealthCard (T '内存') (T '读不到') $script:hcGrey; $card.Lines.Add($m.Why); $cards.Add($card) }
    # 磁盘
    foreach ($d in @($r.Disks)) {
        $tier = $script:hcGreen
        $sub = if ($d.Model) { [string]$d.Model } else { (T '型号读不到') }
        $card = New-HealthCard ((T "磁盘 {0}") -f $d.Drive) $sub $tier
        try { $du = Get-DriveUse ($d.Drive + '\'); if (-not $du.Ok) { throw 'no size' }; $pct = [int][math]::Round($du.Pct); Set-CardBar $card $pct; $card.Chips.Add((New-Chip ((T "已用 {0}%") -f $pct) $(if ($pct -ge 95) { $script:hcRed } elseif ($pct -ge 85) { $script:hcAmber } else { $script:hcGreen }))) } catch {}
        if ($d.Ok) {
            $h = [string]$d.Health
            $t2 = if ($h -match 'Healthy|正常|OK') { $script:hcGreen } elseif ($h) { $script:hcRed } else { $script:hcGrey }
            $card.Chips.Add((New-Chip $(if ($h) { $h } else { (T '健康状态读不到') }) $t2)); $tier = Tier-Worst $tier $t2
            if ($d.Temp -ne $null -and [int]$d.Temp -gt 0) { $t2 = if ([int]$d.Temp -ge 60) { $script:hcRed } elseif ([int]$d.Temp -ge 45) { $script:hcAmber } else { $script:hcGreen }; $card.Chips.Add((New-Chip ("{0} °C" -f $d.Temp) $t2)); $tier = Tier-Worst $tier $t2 } else { $card.Chips.Add((New-Chip (T '温度读不到') $script:hcGrey)) }
            if ($d.Wear -ne $null -and [int]$d.Wear -ge 0) { $t2 = if ([int]$d.Wear -ge 50) { $script:hcRed } elseif ([int]$d.Wear -ge 10) { $script:hcAmber } else { $script:hcGreen }; $card.Chips.Add((New-Chip ((T "磨损 {0}%") -f $d.Wear) $t2)); $tier = Tier-Worst $tier $t2 }
            if ($d.ReadErrors -ne $null -and [long]$d.ReadErrors -gt 0) { $card.Chips.Add((New-Chip ((T "读错误 {0}") -f $d.ReadErrors) $script:hcRed)); $tier = $script:hcRed }
            if ($d.Hours -ne $null -and [long]$d.Hours -gt 0) { $card.Lines.Add((T "通电 {0:N0} 小时") -f $d.Hours) }
            if ($d.Media) { $card.Lines.Add([string]$d.Media) }
        } else { $card.Chips.Add((New-Chip (T 'SMART 读不到') $script:hcGrey)); $card.Lines.Add((T '这块盘不报告 SMART（USB 硬盘盒、RAID 和部分虚拟机常见）')) }
        $card.Stripe = $tier[0]; $card.BarBrush = $tier[0]
        $cards.Add($card)
    }
    # 电池
    $b = $r.Battery
    if ($b.Present) {
        $tier = $script:hcGreen
        $card = New-HealthCard (T '电池') $b.Status $tier
        if ($b.Charge -ge 0) { Set-CardBar $card $b.Charge; $card.Chips.Add((New-Chip ((T "电量 {0}%") -f $b.Charge) $script:hcBlue)) }
        if ($b.Design -gt 0 -and $b.Full -gt 0) {
            $pct = [int][math]::Round(100.0 * $b.Full / $b.Design)
            $t2 = if ($pct -lt 60) { $script:hcRed } elseif ($pct -lt 80) { $script:hcAmber } else { $script:hcGreen }
            $card.Chips.Add((New-Chip ((T "健康 {0}%") -f $pct) $t2)); $tier = $t2
            $card.Lines.Add((T "设计容量 {0:N0} mWh，现在充满 {1:N0} mWh") -f $b.Design, $b.Full)
        } else { $card.Chips.Add((New-Chip (T '损耗读不到') $script:hcGrey)); if ($b.Why) { $card.Lines.Add($b.Why) } }
        if ($b.Cycles -ge 0) { $card.Chips.Add((New-Chip ((T "循环 {0} 次") -f $b.Cycles) $script:hcBlue)) } else { $card.Lines.Add((T '循环次数：电池没有报告')) }
        $card.Stripe = $tier[0]; $card.BarBrush = $tier[0]
        $cards.Add($card)
    } else { $card = New-HealthCard (T '电池') (T '没有电池（台式机）') $script:hcGrey; $cards.Add($card) }
    # 显卡
    foreach ($g in @($r.Gpu)) {
        if (-not $g.Ok) { $card = New-HealthCard (T '显卡') (T '读不到') $script:hcGrey; $card.Lines.Add($g.Why); $cards.Add($card); continue }
        $card = New-HealthCard (T '显卡') $g.Name $script:hcGreen
        if ($g.Util -ge 0) { Set-CardBar $card $g.Util; $card.Chips.Add((New-Chip ((T "占用 {0}%") -f $g.Util) $(if ($g.Util -ge 95) { $script:hcAmber } else { $script:hcGreen }))) }
        if ($g.Vram -gt 0) { $card.Chips.Add((New-Chip ($(if ($g.VramUsed -ge 0) { (T "显存 {0} / {1}") -f (Fmt $g.VramUsed), (Fmt $g.Vram) } else { (T "显存 {0}") -f (Fmt $g.Vram) })) $script:hcBlue)) }
        $card.Chips.Add((New-Chip (T '温度读不到') $script:hcGrey))
        $card.Lines.Add($g.TempWhy)
        if ($g.Driver) { $card.Lines.Add(((T "驱动 {0}") -f $g.Driver) + $(if ($g.DriverDate) { ("（{0:yyyy-MM-dd}）" -f $g.DriverDate) } else { '' })) }
        $cards.Add($card)
    }
    # Windows
    $w = $r.Win
    $tier = if ($w.BadDevices.Count -gt 0) { $script:hcAmber } else { $script:hcGreen }
    $card = New-HealthCard 'Windows' $(if ($w.Release) { (T "{0} {1}（{2}.{3}）") -f $w.Product, $w.Release, $w.BuildNo, $w.Ubr } else { (T "版本 {0}") -f $w.Build }) $tier
    if ($w.BuildNo -gt 0 -and $w.BuildNo -lt 19045 -and [string]$w.Product -notmatch 'Server|LTSC|LTSB') { $card.Chips.Add((New-Chip (T '版本太旧') $script:hcAmber)); $tier = Tier-Worst $tier $script:hcAmber }
    if ($r.Clock -and $r.Clock.Wrong) { $card.Chips.Add((New-Chip (T '时间可能不准') $script:hcAmber)); $card.Lines.Add(((T '有系统文件的修改时间比现在还晚 {0} 天：时钟被往回调过，或者主板电池没电了') -f $r.Clock.AheadDays)); $tier = Tier-Worst $tier $script:hcAmber }
    if ($w.Uptime) { $card.Chips.Add((New-Chip ((T "开机 {0}") -f (FmtSpan $w.Uptime)) $(if ($w.Uptime.TotalDays -ge 14) { $script:hcAmber } else { $script:hcBlue }))) }
    if ($w.PendingReboot) { $card.Chips.Add((New-Chip (T '等待重启') $script:hcAmber)); $tier = Tier-Worst $tier $script:hcAmber }
    if ($w.LastUpdate) { $card.Chips.Add((New-Chip ((T "更新 {0:yyyy-MM-dd}") -f $w.LastUpdate) $(if (((Get-Date) - $w.LastUpdate).TotalDays -gt 60) { $script:hcAmber } else { $script:hcGreen }))) }
    $card.Chips.Add((New-Chip ($(if ($w.BadDevices.Count -gt 0) { (T "{0} 个设备有问题") -f $w.BadDevices.Count } else { (T '设备都正常') })) $(if ($w.BadDevices.Count -gt 0) { $script:hcAmber } else { $script:hcGreen })))
    foreach ($bd in @($w.BadDevices | Select-Object -First 4)) { $card.Lines.Add(("{0}：{1}" -f $bd.Name, $bd.Note)) }
    if ($w.Uptime -and $w.Uptime.TotalDays -ge 14) { $card.Lines.Add((T '两周没重启了（快速启动的「关机」不算重启）。很多莫名其妙的慢和卡，重启一次就好')) }
    $card.Stripe = $tier[0]; $card.BarBrush = $tier[0]
    $cards.Add($card)
    $ctl.HealthCards.ItemsSource = $cards
    # 开机
    $bt = $r.Boot
    $slow = New-Object 'System.Collections.ObjectModel.ObservableCollection[NoteRow]'
    if ($bt.Ok) {
        $ctl.HealthBootText.Text = (T "最近一次开机（{0:yyyy-MM-dd HH:mm}）用了 {1:N0} 秒：到桌面 {2:N0} 秒，桌面出来后开机程序又忙了 {3:N0} 秒才安静下来。") -f $bt.At, ($bt.BootMs / 1000), ($bt.MainMs / 1000), ($bt.PostMs / 1000)
        if ($bt.History.Count -ge 3) { $avg = ($bt.History | ForEach-Object { $_.BootMs } | Measure-Object -Average).Average; $ctl.HealthBootText.Text += (T "最近 {0} 次平均 {1:N0} 秒。") -f $bt.History.Count, ($avg / 1000) }
        if ($bt.BootMs -gt 120000) { $ctl.HealthBootText.Text += (T '超过两分钟算慢的。') }
        foreach ($s in @($bt.Slow)) { $n = New-Object NoteRow; $n.Head = $s.Name; $n.Sub = [string]$s.Path; $n.Path = $s.Path; $n.Body = (T "拖慢 {0:N0} 秒，{1} 次") -f ($s.DegradeMs / 1000), $s.Times; $slow.Add($n) }
        if ($slow.Count -eq 0) { $ctl.HealthBootText.Text += (T '最近 30 天 Windows 没有点名拖慢开机的程序。') }
    } else { $ctl.HealthBootText.Text = $bt.Why }
    $ctl.HealthSlow.ItemsSource = $slow
    # 蓝屏
    $cr = $r.Crash
    $dumps = New-Object 'System.Collections.ObjectModel.ObservableCollection[DumpRow]'
    foreach ($d in @($cr.Dumps)) {
        $row = New-Object DumpRow
        $row.When = '{0:yyyy-MM-dd HH:mm}' -f $d.Time; $row.File = $d.File
        $row.Code = if ($d.Ok) { ('0x{0:X} {1}' -f $d.Code, $d.CodeName).Trim() } else { (T '没解析出来') }
        $xp = Get-DumpExplain $d
        $row.Plain = $xp.Plain + (T '。') + $(if ($d.Ok -and $xp.Kind -ne 'other') { (T '常见原因：') + $xp.Causes + (T '。') } elseif ($d.Ok) { $xp.Causes + (T '。') } else { '' })
        $row.Suspect = ''; $row.SuspectBrush = '#C0101C'
        if ($d.Suspect -and $d.SuspectFrom -eq 'address' -and -not $d.SuspectMs) { $row.Suspect = (T "可能是 {0}") -f $d.Suspect }
        elseif ($d.Suspect) { $row.Suspect = (T "可能和 {0} 有关") -f $d.Suspect; $row.SuspectBrush = '#995700' }
        elseif ($xp.Kind -eq 'storage') { $row.Suspect = (T '读盘失败'); $row.SuspectBrush = '#C0101C' }
        $det = @($xp.Detail)
        if ($d.Ok) { $det += (T "参数 {0}") -f ($d.Params -join ' ') }
        if ($d.Stack.Count -gt 0) { $det += (T "栈上的驱动：{0}") -f (($d.Stack | Select-Object -First 6) -join ', ') }
        if ($d.Ok) { $det += (T "出事时加载了 {0} 个驱动") -f $d.Drivers }
        if ($d.Error) { $det += $d.Error }
        $det += (T "{0}，{1}") -f $d.Name, (Fmt $d.Size)
        $row.Detail = $det -join (T '。')
        $dumps.Add($row)
    }
    $ctl.HealthDumps.ItemsSource = $dumps
    $ctl.HealthCrashText.Text = if ($dumps.Count -gt 0) { (T "{0} 里有 {1} 个转储文件（最近的 10 个）。") -f $cr.DumpDir, $dumps.Count } else { (T "没有转储文件：最近没有蓝屏，或者蓝屏时没来得及写出转储。") }
    if ($cr.MemoryDmp) { $ctl.HealthCrashText.Text += (T "另有完整转储 MEMORY.DMP（{0}，{1:yyyy-MM-dd}），在「省空间」里可以改成只存小转储。") -f (Fmt $cr.MemoryDmp.Size), $cr.MemoryDmp.Time }
    $evs = New-Object 'System.Collections.ObjectModel.ObservableCollection[NoteRow]'
    foreach ($x in @($cr.Events)) { $n = New-Object NoteRow; $n.Head = ("{0}（{1}）" -f $x.What, $x.Source); $n.Sub = Shorten-Note ([string]$x.Sample); $n.Path = $x.Sample; $n.Body = (T "{0} 次，最近 {1:MM-dd HH:mm}") -f $x.Count, $x.Last; $evs.Add($n) }
    if ($evs.Count -eq 0) { $n = New-Object NoteRow; $n.Head = (T '没有意外关机、硬件错误和磁盘错误的记录'); $evs.Add($n) }
    $ctl.HealthEvents.ItemsSource = $evs
    $drs = New-Object 'System.Collections.ObjectModel.ObservableCollection[NoteRow]'
    foreach ($x in @($cr.Drivers | Select-Object -First 12)) { $n = New-Object NoteRow; $n.Head = ("{0} {1} {2}" -f $x.Provider, $x.Name, $x.Version).Trim(); $n.Sub = [string]$x.Device; $n.Path = $x.Device; $n.Body = '{0:MM-dd HH:mm}' -f $x.When; $drs.Add($n) }
    if ($drs.Count -eq 0) { $n = New-Object NoteRow; $n.Head = (T '最近 30 天没有装过驱动'); $drs.Add($n) }
    $ctl.HealthDrivers.ItemsSource = $drs
    # 小选项卡上写明有几条，不点进去也知道
    $ctl.CTabDumpsN.Text = [string]$dumps.Count; $ctl.CTabDumpsB.Visibility = if ($dumps.Count -gt 0) { 'Visible' } else { 'Collapsed' }
    $nEv = @($cr.Events).Count + @($cr.Drivers).Count
    $ctl.CTabEventsN.Text = [string]$nEv; $ctl.CTabEventsB.Visibility = if ($nEv -gt 0) { 'Visible' } else { 'Collapsed' }
    # Windows 事件
    $errs = New-Object 'System.Collections.ObjectModel.ObservableCollection[NoteRow]'
    foreach ($x in @($w.Errors)) { $n = New-Object NoteRow; $n.Head = [string]$x.Source; $n.Sub = Shorten-Note ([string]$x.Sample); $n.Path = $x.Sample; $n.Body = (T "{0} 次，最近 {1:MM-dd HH:mm}") -f $x.Count, $x.Last; $errs.Add($n) }
    $ctl.HealthErrors.ItemsSource = $errs
    $ctl.HealthWinText.Text = if ($w.ErrorCount -gt 0) { (T "最近 7 天系统日志里有 {0} 条严重或错误事件，来源最多的几个：") -f $w.ErrorCount } else { (T '最近 7 天系统日志里没有严重或错误事件。') }
}
$ctl.HealthDumps.AddHandler([System.Windows.Controls.Button]::ClickEvent, [System.Windows.RoutedEventHandler]{ param($s, $e) $b = $e.OriginalSource; if ($b -is [System.Windows.Controls.Button] -and $b.Tag -is [DumpRow]) { Open-Location $b.Tag.File } })
# 「蓝屏和崩溃」里的三个小选项卡
$script:crashTabs = [ordered]@{ verdict = @('CTabVerdict', 'CrashViewVerdict'); dumps = @('CTabDumps', 'CrashViewDumps'); events = @('CTabEvents', 'CrashViewEvents') }
function Select-CrashTab([string]$k) {
    if (-not $script:crashTabs.Contains($k)) { $k = 'verdict' }
    foreach ($t in $script:crashTabs.Keys) { $ctl[$script:crashTabs[$t][1]].Visibility = $(if ($t -eq $k) { 'Visible' } else { 'Collapsed' }) }
    $rb = $ctl[$script:crashTabs[$k][0]]; if (-not $rb.IsChecked) { $rb.IsChecked = $true }
    $script:crashTab = $k
}
foreach ($t in $script:crashTabs.Keys) { $rb = $ctl[$script:crashTabs[$t][0]]; $rb.Tag = $t; $rb.Add_Checked({ Select-CrashTab ([string]$this.Tag) }) }
# ---------- 选项卡：点哪一项只显示哪一项 ----------
$script:healthTabs = [ordered]@{ hw = @('HTabHw', 'HealthViewHw'); boot = @('HTabBoot', 'HealthViewBoot'); crash = @('HTabCrash', 'HealthViewCrash'); fix = @('HTabFix', 'HealthViewFix'); mon = @('HTabMon', 'HealthViewMon'); events = @('HTabEvents', 'HealthViewEvents') }
$script:healthTab = Get-Setting 'HealthTab' 'hw'; $script:htabQuiet = $false
function Select-HealthTab([string]$k) {
    if (-not $script:healthTabs.Contains($k) -or $ctl[$script:healthTabs[$k][0]].Visibility -ne 'Visible') { $k = 'hw' }
    foreach ($t in $script:healthTabs.Keys) { $ctl[$script:healthTabs[$t][1]].Visibility = $(if ($t -eq $k) { 'Visible' } else { 'Collapsed' }) }
    $rb = $ctl[$script:healthTabs[$k][0]]
    if (-not $rb.IsChecked) { $script:htabQuiet = $true; try { $rb.IsChecked = $true } finally { $script:htabQuiet = $false } }
    $script:healthTab = $k
}
foreach ($t in $script:healthTabs.Keys) {
    $rb = $ctl[$script:healthTabs[$t][0]]; $rb.Tag = $t
    $rb.Add_Checked({ if ($script:htabQuiet) { return }; Select-HealthTab ([string]$this.Tag); Set-Setting 'HealthTab' $script:healthTab })
}
# ---------- 诊断结论和常见问题修复 ----------
$script:fixCat = $null
function Get-FixCat { if (-not $script:fixCat) { $script:fixCat = Get-FixCatalog }; return $script:fixCat }
# 一步修复在界面上的样子：标签写明只看 / 会改动 / 要重启；硬盘省电、快速启动按现在的状态换说法
function New-FixStepRow([string]$id, $st) {
    $s = (Get-FixCat).Steps[$id]
    $row = New-Object FixStepRow; $row.Id = $id; $row.Name = $s.Name; $row.Desc = $s.Desc; $row.Enabled = $true
    $tier = $script:hcGrey; $tag = ''
    switch ($s.Kind) {
        'check' { $tag = (T '只看'); $tier = $script:hcGreen }
        'fix' { if ($s.Reboot) { $tag = (T '要重启'); $tier = $script:hcRed } elseif ($s.Harmless) { $tag = (T '马上生效'); $tier = $script:hcBlue } else { $tag = (T '会改动'); $tier = $script:hcAmber } }
        'open' { $tag = (T '打开工具') }
        'go' { $tag = (T '跳转') }
        'special' { $tag = (T '可恢复'); $tier = $script:hcAmber }
    }
    switch ($id) {
        'diagpack' { $tag = (T '只读'); $tier = $script:hcGreen }
        'diskpowerundo' { $tag = (T '恢复'); $tier = $script:hcBlue; $row.Enabled = [bool]($st -and $st.DiskFix); if (-not $row.Enabled) { $row.Desc = $s.Desc + (T '（现在没改过，不用恢复）') } }
        'diskpower' { if ($st -and $st.DiskFix) { $row.Name = (T '已关闭硬盘省电'); $row.Enabled = $false; $tag = (T '已改') } }
        'faststartup' {
            if ($st -and $st.FastStartup -eq 'off') { $row.Name = (T '打开快速启动…'); $row.Desc = (T '快速启动现在是关着的。打开后「关机」变成半休眠，开机快几秒；关机变重启、唤醒失败的问题可能会回来') }
            elseif ($st -and $st.FastStartup -eq 'na') { $row.Name = (T '没有快速启动'); $row.Enabled = $false; $row.Desc = (T '休眠关着，所以没有快速启动，不用管'); $tag = (T '不用改'); $tier = $script:hcGrey }
        }
    }
    $row.Tag = $tag; $row.TagFg = $tier[0]; $row.TagBg = $tier[1]
    # 卡片上：标题是这一步做什么，按钮上写动作；点了会先问一下的，按钮后面带省略号
    $row.Title = ([string]$row.Name).TrimEnd([char]0x2026)
    $ask = ([string]$row.Name).EndsWith([string][char]0x2026)
    $act = switch ($s.Kind) { 'open' { T '打开' } 'go' { T '查看' } default { T '运行' } }
    switch ($id) { 'diagpack' { $act = (T '导出') } 'vendor' { $act = (T '打开') } 'ahciguide' { $act = (T '查看步骤') } 'diskpowerundo' { $act = (T '恢复') } }
    $row.Act = if (-not $row.Enabled) { $tag } elseif ($ask) { $act + [char]0x2026 } else { $act }
    return $row
}
function New-FixBtn([string]$id, $st) {
    if (-not (Get-FixCat).Steps.Contains($id)) { return $null }
    $x = New-FixStepRow $id $st
    $b = New-Object FixBtn; $b.Id = $id; $b.Name = $x.Name; $b.Tip = $x.Desc; $b.Enabled = $x.Enabled
    return $b
}
function Show-Fixes($st) {
    $c = Get-FixCat; $m = Get-Mode
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[FixGroupRow]'
    foreach ($p in $c.Problems) {
        $g = New-Object FixGroupRow; $g.Id = $p.Id; $g.Title = $p.Title; $g.Desc = $p.Desc
        foreach ($id in $p.Steps) {
            $s = $c.Steps[$id]; if (-not $s) { continue }
            $show = [int]$s.Lvl -le $m
            if ($id -eq 'diskpowerundo') { $show = ($st -and $st.DiskFix) -or $m -ge [int]$c.Steps['diskpower'].Lvl }   # 改过了就一直能恢复，不管什么模式
            if ($show) { $x = New-FixStepRow $id $st; $x.No = [string]($g.Steps.Count + 1); $g.Steps.Add($x) }
        }
        if ($g.Steps.Count -gt 0) { $col.Add($g) }
    }
    # 左边的问题列表换了内容，原来选的那个问题还选着（第一次打开选记住的那个，没有就选第一个）
    $keep = if ($ctl.FixGroups.SelectedItem) { [string]$ctl.FixGroups.SelectedItem.Id } else { Get-Setting 'FixGroup' '' }
    $ctl.FixGroups.ItemsSource = $col
    $sel = @($col | Where-Object { $_.Id -eq $keep })[0]
    if (-not $sel -and $col.Count -gt 0) { $sel = $col[0] }
    $ctl.FixGroups.SelectedItem = $sel
}
$ctl.FixGroups.Add_SelectionChanged({ if ($ctl.FixGroups.SelectedItem) { Set-Setting 'FixGroup' ([string]$ctl.FixGroups.SelectedItem.Id); $ctl.FixDetailScroll.ScrollToTop() } })
function Show-Verdicts($r) {
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[VerdictRow]'
    $rec = New-Object 'System.Collections.ObjectModel.ObservableCollection[FixBtn]'; $seen = @{}
    foreach ($v in @($r.Verdicts)) {
        $row = New-Object VerdictRow; $row.Title = $v.Title; $row.Body = $v.Body
        $tier = switch ($v.Level) { 'red' { $script:hcRed } 'amber' { $script:hcAmber } 'green' { $script:hcGreen } default { $script:hcBlue } }
        $row.Fg = $tier[0]; $row.Bg = $tier[1]
        foreach ($id in @($v.Fixes)) {
            $b = New-FixBtn $id $r.Power; if (-not $b) { continue }
            $row.Fixes.Add($b)
            if ($v.Id -ne 'none' -and -not $seen.ContainsKey($id)) { $seen[$id] = $true; $rec.Add((New-FixBtn $id $r.Power)) }
        }
        $row.HasFixes = $row.Fixes.Count -gt 0
        $pend = @(Get-PlanPending $v $r.Power)
        $row.HasPlan = $pend.Count -gt 0; $row.PlanTag = 'plan:' + [string]$v.Id; $row.PlanName = (T '按建议处理…')
        $row.PlanTip = (T '会做：') + ((@($pend | ForEach-Object { ([string](Get-FixCat).Steps[$_].Name).TrimEnd('…') })) -join (T '、'))
        $td = @($v.Todo | Where-Object { $_ })
        $row.HasTodo = $td.Count -gt 0
        $row.Todo = (@(for ($i = 0; $i -lt $td.Count; $i++) { '{0}. {1}' -f ($i + 1), $td[$i] })) -join "`n"
        $col.Add($row)
    }
    $ctl.HealthVerdicts.ItemsSource = $col
    $ctl.FixRec.ItemsSource = $rec
    $ctl.FixRecBox.Visibility = $(if ($rec.Count -gt 0) { 'Visible' } else { 'Collapsed' })
}
# 改完硬盘省电、快速启动后重新读一下状态，按钮跟着变
function Refresh-FixState {
    $st = Get-PowerFixState
    if ($script:healthData) { $script:healthData.Power = $st; Show-Verdicts $script:healthData }
    Show-Fixes $st
}
$script:uiFixRuns = New-Object System.Collections.Generic.List[string]
# 一条结论里还没做的自动步骤（硬盘省电已经关了、快速启动已经关了的就不再列）
function Get-PlanPending($v, $st) {
    $out = @()
    foreach ($id in @($v.Plan)) {
        if (-not $id -or -not (Get-FixCat).Steps.Contains($id)) { continue }
        if ($id -eq 'diskpower' -and $st -and $st.DiskFix) { continue }
        if ($id -eq 'faststartup' -and $st -and $st.FastStartup -ne 'on') { continue }
        $out += $id
    }
    return $out
}
# 按建议处理：本工具能直接做的几步一次做完（先列出来确认一次），做完告诉你哪些做好了、还剩哪些要你自己做
function Invoke-RepairPlan([string]$vid) {
    if (-not $script:healthData) { return }
    $v = @($script:healthData.Verdicts | Where-Object { [string]$_.Id -eq $vid })[0]
    if (-not $v) { return }
    $st = Get-PowerFixState; $c = Get-FixCatalog
    $pend = @(Get-PlanPending $v $st)
    if ($pend.Count -eq 0) { Show-Sheet -Title ([string]$v.Title) -Text (T '本工具能做的都已经做过了。剩下的要你自己做，见结论下面「需要你自己做的」。') | Out-Null; return }
    $items = @($pend | ForEach-Object { '{0}：{1}' -f ([string]$c.Steps[$_].Name).TrimEnd('…'), $c.Steps[$_].Desc })
    $td = @($v.Todo | Where-Object { $_ })
    $text = (T '本工具会直接做下面这几件，都能撤销（硬盘省电和快速启动可以在「常见问题修复」里改回来）。') + $(if ($td.Count) { "`n`n" + (T '做完以后还需要你自己做：') + "`n" + ((@(for ($i = 0; $i -lt $td.Count; $i++) { '{0}. {1}' -f ($i + 1), $td[$i] })) -join "`n") } else { '' })
    $ans = Show-Sheet -Kind warn -Title ((T '{0}：按建议处理？') -f $v.Title) -Text $text -Items $items -Buttons @((T '取消'), (T '开始处理')) -Primary (T '开始处理') -Cancel (T '取消')
    if ($ans -ne (T '开始处理')) { return }
    $done = @(); $fail = @()
    foreach ($id in $pend) {
        $name = ([string]$c.Steps[$id].Name).TrimEnd('…')
        try {
            switch ($id) {
                'diskpower' { $res = Set-DiskPowerFix $true; if ($res.Ok) { $done += ((T '{0}（马上生效）') -f $name) } else { $fail += ('{0}：{1}' -f $name, $res.Why) } }
                'faststartup' { Set-FastStartup $false; $done += ((T '{0}（下次关机起生效）') -f $name) }
                default { Invoke-FixStep $id -Quiet; $done += ((T '{0}（已在新窗口里打开或运行）') -f $name) }
            }
        } catch { $fail += ('{0}：{1}' -f $name, $_.Exception.Message) }
    }
    OpLog '系统设置' (T '按建议处理') ([string]$v.Title) (($done + $fail) -join (T '；'))
    Refresh-FixState
    $msg = (T '做好了：') + "`n" + (@($done | ForEach-Object { '• ' + $_ }) -join "`n")
    if ($fail.Count) { $msg += "`n`n" + (T '没做成：') + "`n" + (@($fail | ForEach-Object { '• ' + $_ }) -join "`n") }
    if ($td.Count) { $msg += "`n`n" + (T '还需要你自己做：') + "`n" + ((@(for ($i = 0; $i -lt $td.Count; $i++) { '{0}. {1}' -f ($i + 1), $td[$i] })) -join "`n") }
    $msg += "`n`n" + (T '改完用几天，再回来点「刷新」看还有没有新的蓝屏。')
    Show-Sheet -Kind done -Title (T '处理完了') -Text $msg | Out-Null
}
# 厂商驱动下载页：打开，同时把链接复制下来（这台电脑上不了网时，到别的电脑上打开）
function Open-VendorPage {
    $f = if ($script:healthData) { $script:healthData.Sys } else { $null }
    if (-not $f) { $f = Get-SysFacts }
    $url = Get-VendorSupportUrl $f
    if (-not $url) { return }
    try { [System.Windows.Clipboard]::SetText($url) } catch {}
    if ($script:uiTest) { $script:uiFixRuns.Add('vendor:' + $url); return }
    $txt = (T "{0} {1}，服务编号 / 序列号 {2}`n`n{3}`n`n链接已经复制。要下载的：BIOS、芯片组驱动、存储驱动（Intel RST）、固态硬盘固件；装的顺序是 BIOS → 芯片组 → 存储驱动 → 固件，每装一样重启一次。这台电脑上不了外网的话，在别的电脑上打开这个链接，下载好用 U 盘拷过来。") -f $f.Maker, $f.Model, $f.Serial, $url
    $ans = Show-Sheet -Title (T '厂商驱动下载页') -Text $txt -Buttons @((T '关闭'), (T '在浏览器里打开')) -Primary (T '在浏览器里打开') -Cancel (T '关闭')
    if ($ans -eq (T '在浏览器里打开')) { [void](Open-AsUser $url) }
}
# 改用 Windows 自带的硬盘驱动：只给步骤（要进 BIOS），先替你查好能不能改
function Show-AhciGuide {
    $f = if ($script:healthData) { $script:healthData.Sys } else { Get-SysFacts }
    $sd = if ($f) { $f.SysDisk } else { $null }
    $chk = @()
    $stop = $false
    if ($sd) {
        $chk += (T '系统盘：{0}，接口 {1}') -f $sd.Name, $sd.Bus
        if ($sd.RaidVolume) { $chk += (T '✗ 这看起来是 RAID 阵列（几块盘组在一起）：不要改，改了阵列会读不出来'); $stop = $true }
        elseif ($sd.Bus -ne 'RAID') { $chk += (T '✗ 系统盘没有接在 RAID / RST 控制器上，用不着改'); $stop = $true }
        else { $chk += (T '✓ 单块盘，不是 RAID 阵列') }
    } else { $chk += (T '读不到系统盘的接口，改之前自己在 BIOS 里确认是单块盘、没有组 RAID') }
    if ($f -and $f.BitLocker -eq 1) { $chk += (T '✗ BitLocker 开着：先在「控制面板 → BitLocker 驱动器加密」里点「暂停保护」，并准备好恢复密钥，否则改完要输恢复密钥') }
    elseif ($f -and $f.BitLocker -eq 0) { $chk += (T '✓ BitLocker 关着') }
    $steps = (T "1. 先把重要资料备份到另一块盘。`n2. 以管理员身份打开命令提示符，运行：`n      bcdedit /set {current} safeboot minimal`n3. 重启，开机时进 BIOS（Dell 按 F2），在 System Configuration → SATA/NVMe Operation 里把 RAID On 改成 AHCI/NVMe，保存退出。`n4. Windows 会进安全模式，并自动装上 Windows 自带的 NVMe / AHCI 驱动。`n5. 在安全模式里再以管理员身份运行：`n      bcdedit /deletevalue {current} safeboot`n   然后重启，回到正常模式。`n`n改完开不了机：进 BIOS 把模式改回 RAID On，一切照旧，数据不受影响。之后 Intel RST 的管理软件用不了，这没关系。")
    $txt = (T "适用：硬盘接在 Intel RST（RAID On）上、只有一块盘，更新 BIOS 和 RST 驱动后还是掉线。改用 Windows 自带的驱动后，就不经过 RST 了。`n`n这台电脑：`n{0}`n`n{1}`n`n本工具不替你改：要进 BIOS，中途出错要你手动改回来。") -f ($chk -join "`n"), $(if ($stop) { (T '按上面的检查结果，这台电脑不要这样改。') } else { $steps })
    $ans = Show-Sheet -Kind warn -Title (T '改用 Windows 自带的硬盘驱动') -Text $txt -Buttons @((T '关闭'), (T '复制两条命令')) -Primary (T '复制两条命令') -Cancel (T '关闭')
    if ($ans -eq (T '复制两条命令')) { try { [System.Windows.Clipboard]::SetText("bcdedit /set {current} safeboot minimal`r`nbcdedit /deletevalue {current} safeboot") } catch {} }
}
# 运行一步修复。会改动的先确认（界面自测时 Show-Sheet 当作点了取消）；命令都在看得见的终端窗口里跑
function Invoke-FixStep([string]$id, [switch]$Quiet) {
    $c = Get-FixCatalog; if (-not $c.Steps.Contains($id)) { return }   # 每次现取：命令里的时间戳（改名留底用）要是现在的
    $s = $c.Steps[$id]; $name = ([string]$s.Name).TrimEnd('…')
    if ($s.Kind -eq 'go') {
        switch ($s.Go) { 'startup' { Show-Page 'apps'; if ($ctl.AppsViewStartup.Visibility -eq 'Visible') { $ctl.AppsViewStartup.IsChecked = $true } } default { Select-HealthTab $s.Go } }
        return
    }
    if ($s.Kind -eq 'special') {
        switch ($id) {
            'diagpack' { Start-DiagPack }
            'vendor' { Open-VendorPage }
            'ahciguide' { Show-AhciGuide }
            'diskpower' {
                $ans = Show-Sheet -Kind warn -Title (T '关闭硬盘省电？') -Text $s.Confirm -Buttons @((T '取消'), (T '关闭省电')) -Primary (T '关闭省电') -Cancel (T '取消')
                if ($ans -ne (T '关闭省电')) { return }
                $res = Set-DiskPowerFix $true
                if ($res.Ok) { Show-Sheet -Kind done -Title (T '已关闭硬盘省电') -Text ((T "改了：{0}。马上生效，不用重启。想改回去，点「恢复硬盘省电」。") -f ($res.Names -join (T '、'))) | Out-Null }
                else { Show-Sheet -Kind warn -Title (T '没有改') -Text $res.Why | Out-Null }
                Refresh-FixState
            }
            'diskpowerundo' {
                $res = Set-DiskPowerFix $false
                if ($res.Ok) { Show-Sheet -Kind done -Title (T '已恢复硬盘省电') -Text (T '三项设置都改回了原来的值。') | Out-Null } else { Show-Sheet -Kind warn -Title (T '没有恢复') -Text $res.Why | Out-Null }
                Refresh-FixState
            }
            'faststartup' {
                $cur = Get-FastStartup
                if ($cur -eq 'na') { return }
                if ($cur -eq 'on') {
                    $ans = Show-Sheet -Kind warn -Title (T '关闭快速启动？') -Text $s.Confirm -Buttons @((T '取消'), (T '关闭快速启动')) -Primary (T '关闭快速启动') -Cancel (T '取消')
                    if ($ans -ne (T '关闭快速启动')) { return }
                } else {
                    $ans = Show-Sheet -Title (T '打开快速启动？') -Text (T '会重新打开快速启动：「关机」变成半休眠，下次开机快几秒。') -Buttons @((T '取消'), (T '打开')) -Primary (T '打开') -Cancel (T '取消')
                    if ($ans -ne (T '打开')) { return }
                }
                try { New-RestorePointIfWanted (T '快速启动'); Set-FastStartup ($cur -ne 'on'); UI-Log $(if ($cur -eq 'on') { (T '已关闭快速启动') } else { (T '已打开快速启动') }) } catch { Show-Sheet -Kind warn -Title (T '没能改') -Text (Get-FriendlyError $_) | Out-Null }
                Refresh-FixState
            }
        }
        return
    }
    if ($s.Kind -eq 'fix' -and -not $s.Harmless -and -not $Quiet) {   # Quiet：「按建议处理」已经一起确认过
        $ans = Show-Sheet -Kind warn -Title ((T '{0}？') -f $name) -Text $(if ($s.Confirm) { $s.Confirm } else { $s.Desc }) -Buttons @((T '取消'), (T '开始')) -Primary (T '开始') -Cancel (T '取消')
        if ($ans -ne (T '开始')) { return }
    }
    if ($script:uiTest) { $script:uiFixRuns.Add($id); return }   # 界面自测：不真的运行
    if ($s.Kind -eq 'fix') { New-RestorePointIfWanted $name }
    try {
        if ($s.Cmd) { Start-Process -FilePath "$env:SystemRoot\System32\cmd.exe" -ArgumentList ('/k title ClearC - {0} & {1} & echo. & echo {2}' -f $name, $s.Cmd, (T '运行完了，可以关掉这个窗口。')) }
        elseif ($s.Uri) { [void](Open-AsUser $s.Uri) }
        elseif ($s.Folder) { Open-Location $s.Folder; return }
        elseif ($s.Exe -and $s.Args) { Start-Process -FilePath $s.Exe -ArgumentList $s.Args }
        elseif ($s.Exe) { Start-Process -FilePath $s.Exe }
        if ($s.Kind -in 'fix', 'check') { OpLog '系统设置' $name '' $(if ($s.Cmd) { $s.Cmd } else { $s.Exe }) }
        UI-Log ((T "已打开：{0}") -f $name)
    } catch { Show-Sheet -Kind warn -Title ((T '没能打开：{0}') -f $name) -Text (Get-FriendlyError $_) | Out-Null }
}
foreach ($ic in @($ctl.HealthVerdicts, $ctl.FixRec, $ctl.FixDetail)) {
    $ic.AddHandler([System.Windows.Controls.Button]::ClickEvent, [System.Windows.RoutedEventHandler]{ param($s, $e) $b = $e.OriginalSource; if ($b -is [System.Windows.Controls.Button] -and $b.Tag -is [string] -and $b.Tag) { $t = [string]$b.Tag; if ($t.StartsWith('plan:')) { Invoke-RepairPlan $t.Substring(5) } else { Invoke-FixStep $t } } })
}
# 原来的两个按钮：和「常见问题修复」里的是同一步
function Start-SystemFileTool([bool]$repair) { Invoke-FixStep $(if ($repair) { 'sfcrepair' } else { 'sfccheck' }) }
$ctl.BtnSfcCheck.Add_Click({ Start-SystemFileTool $false })
$ctl.BtnSfcRepair.Add_Click({ Start-SystemFileTool $true })
# 诊断包：在后台打包，存到你选的位置（默认桌面），不覆盖已有的文件
function Start-DiagPack {
    if (-not $script:healthData) { Show-Sheet -Kind warn -Title (T '还在读取') -Text (T '等系统健康读完再导出。') | Out-Null; return }
    if ($script:uiTest) { $script:uiFixRuns.Add('diagpack'); return }
    # 先说清楚包里有什么：转储里有出事时内存里的一部分内容，日志和系统信息里有电脑名、用户名、装过的软件
    $dumps = @(Get-ChildItem -LiteralPath (Join-Path $env:SystemRoot 'Minidump') -Filter *.dmp -File -Force -ErrorAction SilentlyContinue)
    $db = [double]0; foreach ($f in $dumps) { $db += $f.Length }
    $items = @(
        (T '健康报告：硬件、Windows 和硬盘的状态')
        $(if ($dumps.Count) { (T "最近 {0} 个蓝屏小转储（{1}）：里面有蓝屏那一刻内存里的一部分内容") -f [math]::Min(20, $dumps.Count), (Fmt $db) } else { (T '蓝屏小转储：这台电脑上没有') })
        (T '最近 30 天的系统和应用日志')
        (T 'systeminfo、驱动列表、硬盘信息、Windows 错误报告的列表')
        (T '本工具最近的操作日志')
        (T '一份清单（manifest.txt），列出包里的每个文件')
    )
    $all = T '导出'; $lite = T '不带转储导出'
    $btns = if ($dumps.Count) { @((T '取消'), $lite, $all) } else { @((T '取消'), $all) }
    $ans = Show-Sheet -Kind warn -Title (T '导出诊断包？') -Text (T '诊断包里会有下面这些。里面有电脑名、用户名、装过的软件和文件路径，只发给你信得过、要帮你看问题的人。') -Items $items -Buttons $btns -Primary $all -Cancel (T '取消')
    if ($ans -ne $all -and $ans -ne $lite) { return }
    $noDumps = ($ans -eq $lite)
    $dlg = New-Object Microsoft.Win32.SaveFileDialog
    $dlg.Title = (T '诊断包保存到'); $dlg.Filter = (T 'zip 压缩包') + ' (*.zip)|*.zip'; $dlg.OverwritePrompt = $false
    $dlg.FileName = ('ClearC-diag-{0:yyyyMMdd-HHmm}.zip' -f (Get-Date)); $dlg.InitialDirectory = [Environment]::GetFolderPath('Desktop')
    if (-not $dlg.ShowDialog($win)) { return }
    $zip = $dlg.FileName
    if (Test-Path -LiteralPath $zip) { Show-Sheet -Kind warn -Title (T '已经有这个文件') -Text (T '换一个文件名再导出：不会覆盖已有的文件。') | Out-Null; return }
    $ctl.BtnDiagPack.IsEnabled = $false
    $ctl.HealthNote.Text = (T '正在导出诊断包，要半分钟到几分钟（systeminfo 比较慢）…')
    $ok = Start-BgEngine 'diagpack' 'Export-DiagPack $arg.Zip $arg.Health -NoDumps:$arg.NoDumps' @{ Zip = $zip; Health = $script:healthData; NoDumps = $noDumps } {
        param($res, $err)
        $ctl.BtnDiagPack.IsEnabled = $true
        if ($res -and $res.Ok) {
            $ctl.HealthNote.Text = (T "诊断包已导出：{0}（{1} 个文件，{2}）") -f $res.Path, $res.Count, (Fmt $res.Bytes)
            OpLog '系统设置' (T '导出诊断包') $res.Path ((T '{0} 个文件，{1}') -f $res.Count, (Fmt $res.Bytes))
            $ans = Show-Sheet -Kind done -Title (T '诊断包已导出') -Text ((T "{0}`n`n{1} 个文件，{2}。里面有蓝屏转储、日志和系统信息，可能包含电脑名、用户名、装过的软件和内存片段，只发给你信任的人。") -f $res.Path, $res.Count, (Fmt $res.Bytes)) -Buttons @((T '好'), (T '打开所在位置')) -Primary (T '打开所在位置') -Cancel (T '好')
            if ($ans -eq (T '打开所在位置')) { Open-Location $res.Path }
        } else { $ctl.HealthNote.Text = (T '没能导出诊断包'); Show-Sheet -Kind warn -Title (T '没能导出诊断包') -Text $(if ($res -and $res.Error) { $res.Error } else { [string]$err }) | Out-Null }
    }
    if (-not $ok) { $ctl.BtnDiagPack.IsEnabled = $true }
}
$ctl.BtnDiagPack.Add_Click({ Start-DiagPack })
$ctl.BtnCopyReport.Add_Click({
    if (-not $script:healthData) { return }
    try { [System.Windows.Clipboard]::SetText((Get-HealthReportText $script:healthData)); UI-Log (T '诊断报告已复制，可以直接粘贴') ; $ctl.HealthNote.Text = (T '诊断报告已复制，可以直接粘贴给别人。') } catch { Show-Sheet -Kind warn -Title (T '没能复制') -Text (Get-FriendlyError $_) | Out-Null }
})
Show-Fixes $null
# 活动监控：后台线程每 3 秒采一次样，把结果放进共享表；界面每秒看一眼
$script:monShared = $null; $script:monSeen = -1; $script:monTimer = $null
function Start-Monitor {
    if ($script:monShared -and -not $script:monShared.Stop) { return }
    $sh = [hashtable]::Synchronized(@{ Stop = $false; Ver = 0; Rows = $null; At = $null; Base = $null })
    $script:monShared = $sh; $script:monSeen = -1
    $threads = [Environment]::ProcessorCount
    $code = @'
$sh = $arg.Shared
$base = Get-ProcSample; $prev = $base; $sh.Base = $base.At
while (-not $sh.Stop) {
    Start-Sleep -Seconds 3
    if ($sh.Stop) { break }
    $cur = Get-ProcSample
    $sh.Rows = @(Compare-ProcSample $prev $cur $base $arg.Threads); $sh.At = $cur.At; $sh.Ver++
    $prev = $cur
}
'ok'
'@
    $ok = Start-BgEngine 'monitor' $code @{ Shared = $sh; Threads = $threads } { param($r, $err) if ($err) { $ctl.HealthMonText.Text = (T '监控出错：') + $err } }
    if (-not $ok) { return }
    $ctl.BtnMonStart.IsEnabled = $false; $ctl.BtnMonStop.IsEnabled = $true
    $ctl.HealthMonText.Text = (T '正在采样…第一组数据 3 秒后出来')
    if (-not $script:monTimer) {
        $script:monTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:monTimer.Interval = [TimeSpan]::FromMilliseconds(1000)
        $script:monTimer.Add_Tick({ Refresh-Monitor })
    }
    $script:monTimer.Start()
    OpLog '系统设置' (T '开始活动监控') '' ''
}
function Stop-Monitor {
    if ($script:monShared) { $script:monShared.Stop = $true }
    if ($script:monTimer) { $script:monTimer.Stop() }
    $ctl.BtnMonStart.IsEnabled = $true; $ctl.BtnMonStop.IsEnabled = $false
    if ($script:monShared -and $script:monShared.Base) { $ctl.HealthMonText.Text = (T "已停止。下面是从 {0:HH:mm:ss} 到 {1:HH:mm:ss} 的结果。") -f $script:monShared.Base, $(if ($script:monShared.At) { $script:monShared.At } else { Get-Date }) }
}
function Refresh-Monitor {
    $sh = $script:monShared
    if (-not $sh -or $sh.Ver -eq $script:monSeen -or -not $sh.Rows) { return }
    $script:monSeen = $sh.Ver
    Show-Monitor @($sh.Rows)
    $ctl.HealthMonText.Text = (T "从 {0:HH:mm:ss} 开始监控，到 {1:HH:mm:ss}，第 {2} 次采样。同名的进程合在一起算。") -f $sh.Base, $sh.At, $sh.Ver
}
function Show-Monitor($rows) {
    # 同名进程合并（Chrome、Edge 一个标签一个进程）
    $by = @{}
    foreach ($x in $rows) {
        $k = [string]$x.Name
        if (-not $by.ContainsKey($k)) { $by[$k] = @{ Name = $k; Path = $x.Path; N = 0; Cpu = 0.0; Ws = 0.0; Rate = 0.0; Since = 0.0; Total = 0.0 } }
        $a = $by[$k]; $a.N++; $a.Cpu += $x.Cpu; $a.Ws += $x.Ws; $a.Rate += $x.WriteRate; $a.Since += $x.WriteSince; $a.Total += $x.WriteTotal
        if (-not $a.Path -and $x.Path) { $a.Path = $x.Path }
    }
    # 只列 25 个：按表头选的那一列取前 25（点「CPU」就是 CPU 最高的 25 个），表格再按这一列排
    $cfg = $script:sortCfg['MonList']
    $sort = if ($cfg -and $cfg.Prop) { [string]$cfg.Prop } else { 'Since' }
    $desc = -not ($cfg -and $cfg.Prop -and -not $cfg.Desc)
    $key = switch ($sort) { 'Cpu' { { $_.Cpu } } 'Ws' { { $_.Ws } } 'Rate' { { $_.Rate } } 'Total' { { $_.Total } } 'Name' { { $_.Name } } default { { $_.Since * 1000000 + $_.Rate } } }
    $list = @($by.Values | Sort-Object $key -Descending:$desc | Select-Object -First 25)
    $max = [double]0; foreach ($a in $list) { if ($a.Since -gt $max) { $max = $a.Since } }
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[ProcRow]'
    foreach ($a in $list) {
        $p = New-Object ProcRow
        $p.Name = $a.Name; $p.Meta = $(if ($a.N -gt 1) { (T "{0} 个进程 · ") -f $a.N } else { '' }) + $(if ($a.Path) { Shorten $a.Path } else { '' })
        $p.CpuText = '{0:N0}%' -f $a.Cpu; $p.WsText = Fmt $a.Ws; $p.RateText = (T "{0}/秒") -f (Fmt $a.Rate); $p.SinceText = Fmt $a.Since; $p.TotalText = Fmt $a.Total
        $p.Cpu = [double]$a.Cpu; $p.Ws = [double]$a.Ws; $p.Rate = [double]$a.Rate; $p.Since = [double]$a.Since; $p.Total = [double]$a.Total
        $p.Bar = if ($max -gt 0) { [math]::Max(0, 100.0 * $a.Since / $max) } else { 0 }
        $col.Add($p)
    }
    $ctl.MonList.ItemsSource = $col
}
$ctl.BtnMonStart.Add_Click({ Start-Monitor })
$ctl.BtnMonStop.Add_Click({ Stop-Monitor })
$win.Add_Closed({ try { if ($script:monShared) { $script:monShared.Stop = $true } } catch {} })

# ---------- 省空间：左边目录，点哪项右边只显示那一项（记住上次看的） ----------
$script:saveGroups = [ordered]@{ Sys = @('Cos', 'Pf', 'Hib', 'Rs', 'Cs', 'Dump'); Safe = @('Rp', 'Tmp'); Files = @('Fc', 'Od', 'Merge'); Vd = @('Vd') }
$script:saveLvl = @{ Pf = 1; Rp = 1; Fc = 1; Vd = 1; Merge = 1; Rs = 2; Cs = 2; Dump = 2; Tmp = 2 }   # 没写的谁都能用
$script:saveSec = Get-Setting 'SaveSection' 'Cos'
function Update-SaveNav {
    $m = Get-Mode; $first = ''
    foreach ($g in $script:saveGroups.Keys) {
        $any = $false
        foreach ($k in $script:saveGroups[$g]) {
            $ok = $m -ge [int]$script:saveLvl[$k]
            $ctl['SaveNav' + $k].Visibility = $(if ($ok) { 'Visible' } else { 'Collapsed' })
            if ($ok) { $any = $true; if (-not $first) { $first = $k } }
        }
        $ctl['SaveHead' + $g].Visibility = $(if ($any) { 'Visible' } else { 'Collapsed' })
    }
    $k = $script:saveSec
    if (-not $ctl['SaveNav' + $k] -or $ctl['SaveNav' + $k].Visibility -ne 'Visible') { $k = $first }
    Select-SaveSection $k
}
function Select-SaveSection([string]$k) {
    if (-not $ctl['SaveCard' + $k]) { return }
    $script:saveSec = $k
    foreach ($g in $script:saveGroups.Keys) { foreach ($x in $script:saveGroups[$g]) { $ctl['SaveCard' + $x].Visibility = $(if ($x -eq $k) { 'Visible' } else { 'Collapsed' }) } }
    $rb = $ctl['SaveNav' + $k]; if (-not $rb.IsChecked) { $script:saveNavQuiet = $true; try { $rb.IsChecked = $true } finally { $script:saveNavQuiet = $false } }
    $ctl.SaveScroll.ScrollToTop()
}
foreach ($g in $script:saveGroups.Keys) { foreach ($k in $script:saveGroups[$g]) { $ctl['SaveNav' + $k].Add_Checked({ if ($script:saveNavQuiet) { return }; Select-SaveSection ([string]$this.Tag); Set-Setting 'SaveSection' $script:saveSec }) } }
function Load-Save {
    $on = Get-CompactOSOn
    $ctl.SaveCosState.Text = if ($on) { (T '当前：已开启，系统文件已压缩存放') } else { (T '当前：未开启') }
    $ctl.BtnCosOn.IsEnabled = -not $on; $ctl.BtnCosOff.IsEnabled = $on
    $pf = Get-PageFileInfo
    $desc = @($pf.Files | ForEach-Object { (T "{0}（约 {1}）") -f $_.Path, (Fmt ($_.MB * 1MB)) }) -join (T '、')
    if (-not $desc) { $desc = (T '没有页面文件') }
    $ctl.SavePfState.Text = ((T "当前：{0}") -f $desc) + $(if ($pf.Auto) { (T '，由系统自动管理') } else { '' })
    $ctl.SavePfDrive.Items.Clear()
    foreach ($d in (Fixed-Drives -NoSystem)) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        $it.Content = Drive-ChoiceLabel $d; $it.Tag = $d.Name.TrimEnd('\')
        [void]$ctl.SavePfDrive.Items.Add($it)
    }
    if ($ctl.SavePfDrive.Items.Count -gt 0) { $ctl.SavePfDrive.SelectedIndex = 0 }
    $ctl.BtnPfMove.IsEnabled = $ctl.SavePfDrive.Items.Count -gt 0
    Start-RestoreInfo
    $h = Get-HiberInfo
    $ctl.SaveHibState.Text = if (-not $h.Exists) { (T '当前：已关闭休眠，没有 hiberfil.sys') } elseif ($h.Reduced) { ((T "当前：精简（只留快速启动），占 {0}") -f $(Fmt $h.Bytes)) } else { ((T "当前：完整休眠，占 {0}") -f $(Fmt $h.Bytes)) }
    $col = New-Object 'System.Collections.ObjectModel.ObservableCollection[VdiskRow]'
    foreach ($v in (Get-VDisks)) {
        $r = New-Object VdiskRow
        $r.Name = $v.Name; $r.Path = $v.Path; $r.Kind = $v.Kind; $r.Note = $v.Note; $r.CanCompact = [bool]$v.Compact; $r.CanMove = [bool]$v.Move; if ($v.Distro) { $r.Distro = [string]$v.Distro }
        if (Test-Path -LiteralPath $v.Path -PathType Leaf) { $r.Size = (Get-Item -LiteralPath $v.Path -Force).Length; $r.SizeText = Fmt $r.Size }
        elseif ($script:worker) { $r.SizeText = '—' }
        else { $r.Size = [long](DirBytes $v.Path); $r.SizeText = Fmt $r.Size }
        $col.Add($r)
    }
    $ctl.VdList.ItemsSource = $col
    $ctl.VdEmpty.Visibility = if ($col.Count -gt 0) { 'Collapsed' } else { 'Visible' }
    # 保留的存储
    $rs = Get-ReservedStorageState
    $ctl.SaveRsState.Text = switch ($rs) { 'Enabled' { (T '当前：已开启（通常占 7 GB 左右）') } 'Disabled' { (T '当前：已关闭') } default { (T '当前：这个版本的 Windows 没有这项（Windows 10 1903 以后才有）') } }
    $ctl.BtnRsOff.IsEnabled = ($rs -eq 'Enabled'); $ctl.BtnRsOn.IsEnabled = ($rs -eq 'Disabled')
    # 蓝屏转储
    $dm = Get-CrashDumpMode
    $ctl.SaveDumpState.Text = (T '当前：') + $(switch ($dm) { 0 { (T '不保存') } 1 { (T '完整内存转储（和内存一样大）') } 2 { (T '内核内存转储') } 3 { (T '小内存转储（256 KB）') } 7 { (T '自动（通常是内核转储，可能有几 GB）') } default { (T '读不到') } })
    $ctl.BtnDumpSmall.IsEnabled = ($dm -ne 3 -and $dm -ge 0); $ctl.BtnDumpAuto.IsEnabled = ($dm -ne 7 -and $dm -ge 0)
    # 临时文件夹
    $tmp = Get-UserTemp
    $ctl.SaveTmpState.Text = (T "当前：{0}") -f $(if ($tmp) { $tmp + $(if ($tmp -ne $env:TEMP -and [Environment]::ExpandEnvironmentVariables($tmp) -ne $env:TEMP) { (T '（注销再登录后生效）') } else { '' }) } else { (T '系统默认') })
    $ctl.SaveTmpDrive.Items.Clear()
    foreach ($d in (Fixed-Drives -NoSystem)) {
        $it = New-Object System.Windows.Controls.ComboBoxItem
        $it.Content = Drive-ChoiceLabel $d; $it.Tag = $d.Name.TrimEnd('\')
        [void]$ctl.SaveTmpDrive.Items.Add($it)
    }
    if ($ctl.SaveTmpDrive.Items.Count -gt 0) { $ctl.SaveTmpDrive.SelectedIndex = 0 }
    $ctl.BtnTmpMove.IsEnabled = $ctl.SaveTmpDrive.Items.Count -gt 0
    $ctl.BtnTmpAuto.IsEnabled = [bool]$tmp -and ([Environment]::ExpandEnvironmentVariables($tmp) -ine "$env:USERPROFILE\AppData\Local\Temp")
    # OneDrive：文件多，到后台数（等没有后台任务时由定时器开始）
    $script:odWanted = $true
}
$ctl.BtnSaveRefresh.Add_Click({ Load-Save })
# ---------- OneDrive ----------
$script:odInfo = $null
Register-BgJob 'odinfo' -Cancel look -ReadOnly -Done { End-Op (T '完成'); Show-OneDriveInfo $sync.OdInfo }
function Start-OneDriveInfo {
    $folders = @(Get-OneDriveFolders)
    if ($folders.Count -eq 0) { $ctl.SaveOdState.Text = (T '这台电脑上没有登录 OneDrive。'); $ctl.BtnOdFree.IsEnabled = $false; return }
    if ($script:worker) { return }
    $ctl.SaveOdState.Text = (T '正在统计 OneDrive 文件夹里有多少本地副本…'); $ctl.BtnOdFree.IsEnabled = $false
    Use-BgJob 'odinfo'; $sync.OdInfo = $null
    Start-Op (T '统计 OneDrive 本地副本') -NoCard; UI-Busy $true
    Start-Worker @'
$sync.OdInfo = Get-OneDriveInfo
'@ $null
}
function Show-OneDriveInfo($i) {
    $script:odInfo = $i
    if (-not $i) { $ctl.SaveOdState.Text = (T '没统计到。'); return }
    $t = (T "当前：{0}，{1:N0} 个文件；本地有副本的 {2}，已经是仅在线的 {3}") -f ($i.Folders -join (T '、')), $i.Files, (Fmt $i.Local), (Fmt $i.Online)
    if ($i.Pinned -gt 0) { $t += (T "；设了「始终保留在此设备」的 {0}（不动）") -f (Fmt $i.Pinned) }
    if (-not $i.Running) { $t += (T "。OneDrive 现在没有运行，改了也要等它启动后才释放") }
    $ctl.SaveOdState.Text = $t
    $ctl.BtnOdFree.IsEnabled = ($i.Local -gt 0)
}
Register-BgJob 'odfree' -Cancel look -Done {
    $x = $sync.OdRes
    End-Op (T '完成')
    if ($x) { $script:pendingDialog = @{ Title = (T '已标记为仅在线'); Kind = 'done'; Text = ((T "{0} 个文件（{1}）已改成仅在线{2}。OneDrive 会在后台释放本地空间，要等它同步一会儿。") -f $x.Done, (Fmt $x.Bytes), $(if ($x.Fail) { ((T "，{0} 个没改成（可能正被占用）") -f $x.Fail) } else { '' })) } }
    $script:odWanted = $true
}
$ctl.BtnOdFree.Add_Click({
    $i = $script:odInfo
    if (-not $i -or $script:worker) { return }
    $ans = Show-Sheet -Title (T '把 OneDrive 里的本地副本都改成仅在线？') -Text ((T "本地有副本的 {0} 会改成「仅在线」：文件还在云端，资源管理器里照常显示，打开时自动下载。什么都不删。你设了「始终保留在此设备」的文件不动。`n`n改完由 OneDrive 自己在后台释放空间，要等它同步一会儿；断网时打不开这些文件。") -f (Fmt $i.Local)) -Buttons @((T '取消'), (T '改成仅在线')) -Primary (T '改成仅在线') -Cancel (T '取消')
    if ($ans -ne (T '改成仅在线')) { return }
    Use-BgJob 'odfree'; $sync.OdRes = $null
    Start-Op (T 'OneDrive 文件改成仅在线'); UI-Busy $true
    Start-Worker @'
SetP @{ Steps = 1; Step = 1; StepName = 'OneDrive'; SubKind = 'none'; Detail = (T '逐个文件标记') }
$res = @{}; Invoke-OneDriveFree $res; $sync.OdRes = $res
OpLog '系统设置' (T 'OneDrive 文件改成仅在线') '' ((T "{0} 个文件，{1}") -f $res.Done, (GB $res.Bytes))
'@ $null
})
# ---------- 保留的存储 ----------
foreach ($b in @($ctl.BtnRsOn, $ctl.BtnRsOff)) {
    $b.Add_Click({
        $on = [object]::ReferenceEquals($this, $ctl.BtnRsOn)
        $t = if ($on) { (T '重新开启保留的存储？') } else { (T '关闭保留的存储？') }
        $x = if ($on) { (T 'Windows 会重新预留 7 GB 左右给系统更新用。') } else { (T '这块空间会还给你。以后更新时 Windows 临时借用空闲空间；C 盘很满时更新可能提示空间不够，再开回来就好。有更新正在安装时改不了。') }
        $btn = if ($on) { (T '开启') } else { (T '关闭') }
        if ((Show-Sheet -Title $t -Text $x -Buttons @((T '取消'), $btn) -Primary $btn -Cancel (T '取消')) -ne $btn) { return }
        $win.Cursor = [System.Windows.Input.Cursors]::Wait
        try { $err = Set-ReservedStorage $on } finally { $win.Cursor = $null }
        if ($err) { Show-Sheet -Kind warn -Title (T '没改成') -Text $err | Out-Null }
        else { OpLog '系统设置' $(if ($on) { (T '开启保留的存储') } else { (T '关闭保留的存储') }) '' ''; UI-Log $(if ($on) { (T '保留的存储：已开启') } else { (T '保留的存储：已关闭') }) }
        Load-Save
    })
}
# ---------- 组件存储分析 ----------
Register-BgJob 'csanalyze' -ReadOnly -Done {
    $x = $sync.CsRes
    End-Op (T '完成')
    if ($x -and $x.Ok) {
        $rec = if ($x.Recommended -match '(?i)^(yes|是|true)') { (T '建议清理') } else { (T '不需要清理') }
        $ctl.SaveCsState.Text = (T "当前：资源管理器显示 {0}，实际 {1}（其中和系统共用的 {2}），可回收的旧组件 {3} 个，上次清理 {4}。Windows 的判断：{5}。") -f $x.Reported, $x.Actual, $x.Shared, $x.Reclaimable, $x.LastCleanup, $rec
    } else { $ctl.SaveCsState.Text = (T '没分析成。') + $(if ($x) { ' ' + (($x.Out -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' ') } else { '' }) }
}
$ctl.BtnCsAnalyze.Add_Click({
    if ($script:worker) { Show-Sheet -Title (T '请等当前操作做完') -Text (T '另一个操作还在进行中。') | Out-Null; return }
    $ctl.SaveCsState.Text = (T '正在分析（DISM，要一两分钟）…')
    Use-BgJob 'csanalyze'; $sync.CsRes = $null
    Start-Op (T '分析组件存储') -NoCard; UI-Busy $true
    Start-Worker @'
$sync.CsRes = Get-ComponentStoreInfo
'@ $null
})
$ctl.BtnCsClean.Add_Click({ Show-Page 'clean'; if (-not $script:rows -and -not $script:worker) { Do-Scan } })
# ---------- 蓝屏转储 ----------
foreach ($b in @($ctl.BtnDumpSmall, $ctl.BtnDumpAuto)) {
    $b.Add_Click({
        $small = [object]::ReferenceEquals($this, $ctl.BtnDumpSmall)
        $t = if ($small) { (T '蓝屏时只保存小转储？') } else { (T '恢复自动转储？') }
        $x = if ($small) { (T '以后蓝屏只保存 256 KB 的小内存转储（C:\Windows\Minidump），够看出是哪个驱动出的问题，不再生成几个 GB 的 MEMORY.DMP。') } else { (T '恢复 Windows 默认的「自动」：蓝屏时可能生成和内存差不多大的 MEMORY.DMP。') }
        $btn = (T '好')
        if ((Show-Sheet -Title $t -Text $x -Buttons @((T '取消'), $btn) -Primary $btn -Cancel (T '取消')) -ne $btn) { return }
        try { Set-CrashDumpMode $(if ($small) { 3 } else { 7 }) } catch { Show-Sheet -Kind warn -Title (T '没改成') -Text (Get-FriendlyError $_) | Out-Null; return }
        OpLog '系统设置' (T '蓝屏转储类型') $(if ($small) { (T '小内存转储') } else { (T '自动') }) ''
        Load-Save
    })
}
