SetP @{ Steps = 1; Step = 1; StepName = 'compact.exe'; SubKind = 'slow'; SubStart = (Get-Date); Detail = '' }
$res = @{}; Invoke-CompactOS ([bool]$arg.On) $res; $sync.CosRes = $res
