            $script:startRows['startup'] = New-Object System.Collections.Generic.List[StartRow]; foreach ($r in $sr) { $script:startRows['startup'].Add($r) }
            $ctl.AppsViewStartup.IsChecked = $true; $win.UpdateLayout()
