            $n0 = $script:uiSheets.Count; Start-BatchToggle $false
            if ($script:uiSheets.Count -ne $n0 + 1 -or @($sr | Where-Object { -not $_.Enabled }).Count) { throw 'batch disable did not ask first, or changed something' }
