            $script:startRows['leftover'] = New-Object System.Collections.Generic.List[StartRow]; foreach ($r in $lr) { $script:startRows['leftover'].Add($r) }
            $ctl.AppsViewLeft.IsChecked = $true; $win.UpdateLayout()
